import { promises as fs } from 'fs';
import os from 'os';
import { startAgent } from './agent';
import logger from './utils/logger';

interface CliOptions {
    serverUrl: string;
    onboardingCode?: string;
    hostname?: string;
    platform?: string;
    mac?: string;
}

interface OnboardingExchangeResponse {
    success: boolean;
    data?: {
        agentId?: string;
        apiKey?: string;
        secretKey?: string;
    };
}

function readEnvValue(...keys: string[]): string | undefined {
    for (const key of keys) {
        const value = process.env[key];
        if (typeof value === 'string' && value.trim()) {
            return value.trim();
        }
    }

    return undefined;
}

function setEnvValue(canonicalKey: string, legacyKey: string, value: string): void {
    process.env[canonicalKey] = value;
    process.env[legacyKey] = value;
}

function envFilePath(): string | undefined {
    return readEnvValue('AETHERGUARD_ENV_FILE', 'AetherGuard_ENV_FILE');
}

async function persistCredentialEnvFile(credentials: {
    agentId: string;
    apiKey: string;
    secretKey: string;
}): Promise<void> {
    const target = envFilePath();
    if (!target) {
        return;
    }

    const current = await fs.readFile(target, 'utf8').catch(() => '');
    const updates = new Map<string, string>([
        ['AETHERGUARD_AGENT_ID', credentials.agentId],
        ['AETHERGUARD_AGENT_API_KEY', credentials.apiKey],
        ['AETHERGUARD_AGENT_SECRET_KEY', credentials.secretKey],
        ['AETHERGUARD_ONBOARDING_CODE', '']
    ]);
    const lines = current ? current.split(/\r?\n/) : [];
    const seen = new Set<string>();
    const nextLines = lines.map((line) => {
        const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
        if (!match) {
            return line;
        }

        const key = match[1];
        if (!updates.has(key)) {
            return line;
        }

        seen.add(key);
        return `${key}=${updates.get(key)}`;
    });

    for (const [key, value] of updates.entries()) {
        if (!seen.has(key)) {
            nextLines.push(`${key}=${value}`);
        }
    }

    const serialized = `${nextLines.filter((line, index, items) => !(line === '' && index === items.length - 1)).join('\n')}\n`;
    await fs.writeFile(target, serialized, 'utf8');
}

function parseArgs(): CliOptions {
    const args = process.argv.slice(2);
    let serverUrl = readEnvValue('AETHERGUARD_SERVER', 'AetherGuard_SERVER') || 'http://localhost:8080';
    let onboardingCode = readEnvValue('AETHERGUARD_ONBOARDING_CODE', 'AetherGuard_ONBOARDING_CODE');
    let hostname = readEnvValue('AETHERGUARD_HOSTNAME', 'AetherGuard_HOSTNAME');
    let platform = readEnvValue('AETHERGUARD_PLATFORM', 'AetherGuard_PLATFORM');
    let mac = readEnvValue('AETHERGUARD_MAC', 'AetherGuard_MAC');

    for (const arg of args) {
        if (arg.startsWith('--server=')) {
            serverUrl = arg.replace('--server=', '');
        }
        if (arg.startsWith('--onboarding-code=')) {
            onboardingCode = arg.replace('--onboarding-code=', '');
        }
        if (arg.startsWith('--hostname=')) {
            hostname = arg.replace('--hostname=', '');
        }
        if (arg.startsWith('--platform=')) {
            platform = arg.replace('--platform=', '');
        }
        if (arg.startsWith('--mac=')) {
            mac = arg.replace('--mac=', '');
        }
    }

    return { serverUrl, onboardingCode, hostname, platform, mac };
}

async function exchangeOnboardingCode(options: CliOptions): Promise<void> {
    if (!options.onboardingCode) return;

    const baseUrl = options.serverUrl.replace(/\/+$/, '');
    const hostname = options.hostname || os.hostname();
    const platform = options.platform || process.platform;

    const response = await fetch(`${baseUrl}/api/agent-onboarding/exchange`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
            onboardingCode: options.onboardingCode,
            hostname,
            platform,
            mac: options.mac
        })
    });

    if (!response.ok) {
        const text = await response.text();
        throw new Error(`Onboarding exchange failed: ${response.status} ${text}`);
    }

    const data = await response.json() as OnboardingExchangeResponse;
    if (!data?.success || !data?.data?.agentId || !data?.data?.apiKey || !data?.data?.secretKey) {
        throw new Error('Onboarding exchange returned invalid payload');
    }

    setEnvValue('AETHERGUARD_AGENT_ID', 'AetherGuard_AGENT_ID', data.data.agentId);
    setEnvValue('AETHERGUARD_AGENT_API_KEY', 'AetherGuard_AGENT_API_KEY', data.data.apiKey);
    setEnvValue('AETHERGUARD_AGENT_SECRET_KEY', 'AetherGuard_AGENT_SECRET_KEY', data.data.secretKey);
    setEnvValue('AETHERGUARD_ONBOARDING_CODE', 'AetherGuard_ONBOARDING_CODE', '');

    await persistCredentialEnvFile({
        agentId: data.data.agentId,
        apiKey: data.data.apiKey,
        secretKey: data.data.secretKey
    });

    console.log(`[onboarding] exchanged code for agentId=${data.data.agentId}`);
}

export async function main(): Promise<void> {
    const options = parseArgs();

    console.log('AetherGuard Agent CLI');
    console.log(`server: ${options.serverUrl}`);

    try {
        await exchangeOnboardingCode(options);
        const agent = await startAgent(options.serverUrl);

        process.on('SIGINT', async () => {
            console.log('\nstopping agent...');
            await agent.stop();
            process.exit(0);
        });

        process.on('SIGTERM', async () => {
            console.log('\nstopping agent...');
            await agent.stop();
            process.exit(0);
        });
    } catch (error: any) {
        logger.error('Agent startup failed', { error: error.message });
        console.error(`Agent startup failed: ${error.message}`);
        process.exit(1);
    }
}

if (require.main === module) {
    void main();
}

/**
 * AetherGuard Agent - SECURE VERSION
 */

import os from 'os';
import crypto from 'crypto';
import { io, Socket } from 'socket.io-client';
import logger from '../utils/logger';
import { TrafficMonitor } from './traffic-monitor';
import { AgentReviewSample, AttackDetector } from './attack-detector';
import { FirewallController } from './firewall-controller';
import { protocolModuleRegistryService } from '../services/protocol-module-registry.service';
import type {
    AgentDeploymentClass,
    AgentNodeKind,
    AgentProtocolPolicy,
    AgentProtocolStats,
    AgentRuntimeMode,
    AgentRuntimePolicy,
    EdgeFinopsStats,
    ProtocolEvaluateRequest,
    ProtocolEvaluateResponse,
    ProtocolObserverAdapter,
} from '../types/edge-auto';
import {
    DEFAULT_AGENT_PROTOCOL_POLICY,
    DEFAULT_AGENT_PROTOCOL_STATS,
    DEFAULT_AGENT_RUNTIME_POLICY,
    DEFAULT_EDGE_FINOPS_STATS,
} from '../types/edge-auto';

export interface AgentConfig {
    serverUrl: string;
    agentId?: string;
    apiKey?: string;
    secretKey?: string;
    heartbeatInterval?: number;
    architecture?: string;
    nodeKind?: AgentNodeKind;
    deploymentClass?: AgentDeploymentClass;
    fastpathBaseUrl?: string;
}

interface SignedCommandInput {
    command: {
        type: string;
        payload?: any;
        timestamp: number;
        nonce: string;
    };
    signature: string;
    agentId: string;
    metadata?: Record<string, any>;
}

export interface AgentStatus {
    agentId: string;
    hostname: string;
    platform: string;
    architecture: string;
    nodeKind: AgentNodeKind;
    deploymentClass: AgentDeploymentClass;
    uptime: number;
    cpuUsage: number;
    memoryUsage: number;
    lastHeartbeat: string;
    isOnline: boolean;
    runtimeMode: AgentRuntimeMode;
    runtimePolicy: AgentRuntimePolicy;
    protocolStats: AgentProtocolStats;
    finopsStats: EdgeFinopsStats;
}

type MqttObservation = {
    channel: string;
    payload?: string | Buffer;
    sourceRef?: string;
    destRef?: string;
    metadata?: Record<string, any>;
};

type Ros2Observation = {
    channel: string;
    sourceRef?: string;
    destRef?: string;
    metadata?: Record<string, any>;
};

const CPU_MUTATING_COMMANDS = new Set(['scan', 'block_ip', 'unblock_ip', 'update_rules']);
const BYPASS_EXEMPT_COMMANDS = new Set(['update_runtime_policy', 'update_protocol_policy', 'clear_runtime_bypass']);

const PROTOCOL_OBSERVER_ADAPTERS: Record<'mqtt' | 'ros2_cyberrt', ProtocolObserverAdapter<any>> = {
    mqtt: {
        moduleId: 'mqtt',
        protocol: 'mqtt',
        activeGovernance: true,
        isEnabled: (policy) => Boolean(policy?.modules?.mqtt?.relayEnabled),
        buildRequest: (agentId, input, policy) => {
            const modulePolicy = policy?.modules?.mqtt || {};
            const payloadBase64 = Buffer.isBuffer(input.payload)
                ? input.payload.toString('base64')
                : Buffer.from(String(input.payload || ''), 'utf8').toString('base64');

            return {
                tenantId: 'global',
                requestId: `${agentId}:mqtt:${Date.now()}`,
                protocol: 'mqtt',
                direction: 'egress',
                sourceRef: input.sourceRef || agentId,
                destRef: input.destRef,
                channel: input.channel,
                headers: {},
                metadata: {
                    ...(input.metadata || {}),
                    heartbeatTopics: modulePolicy.heartbeatTopics || [],
                    heartbeatMinIntervalMs: modulePolicy.heartbeatMinIntervalMs,
                    suppressHighFrequency: Boolean(modulePolicy.suppressHighFrequency),
                },
                payloadBase64,
                truncated: false,
                timestamp: new Date().toISOString(),
            };
        }
    },
    ros2_cyberrt: {
        moduleId: 'ros2_cyberrt',
        protocol: 'ros2_cyberrt',
        activeGovernance: false,
        isEnabled: (policy) => Boolean(policy?.modules?.ros2_cyberrt?.observerEnabled),
        buildRequest: (agentId, input, policy) => ({
            tenantId: 'global',
            requestId: `${agentId}:ros2:${Date.now()}`,
            protocol: 'ros2_cyberrt',
            direction: 'internal',
            sourceRef: input.sourceRef || agentId,
            destRef: input.destRef,
            channel: input.channel,
            headers: {},
            metadata: {
                ...(input.metadata || {}),
                allowlist: policy?.modules?.ros2_cyberrt?.allowlist || [],
            },
            payloadBase64: '',
            truncated: false,
            timestamp: new Date().toISOString(),
        })
    }
};

function clone<T>(value: T): T {
    return JSON.parse(JSON.stringify(value)) as T;
}

function clampNumber(value: any, fallback: number, min: number, max: number): number {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) {
        return fallback;
    }
    return Math.min(Math.max(numeric, min), max);
}

function normalizeRuntimePolicy(raw: any, fallback: AgentRuntimePolicy = DEFAULT_AGENT_RUNTIME_POLICY): AgentRuntimePolicy {
    return {
        cpuCeilingPct: clampNumber(raw?.cpuCeilingPct, fallback.cpuCeilingPct, 1, 100),
        sampleIntervalSec: clampNumber(raw?.sampleIntervalSec, fallback.sampleIntervalSec, 1, 60),
        breachWindowSec: clampNumber(raw?.breachWindowSec, fallback.breachWindowSec, 1, 86400),
        recoveryWindowSec: clampNumber(raw?.recoveryWindowSec, fallback.recoveryWindowSec, 1, 86400),
        autoReadOnlyBypass: typeof raw?.autoReadOnlyBypass === 'boolean' ? raw.autoReadOnlyBypass : fallback.autoReadOnlyBypass
    };
}

function normalizeProtocolPolicy(raw: any, fallback: AgentProtocolPolicy = DEFAULT_AGENT_PROTOCOL_POLICY): AgentProtocolPolicy {
    return protocolModuleRegistryService.normalizePolicyEnvelope(raw, fallback);
}

function normalizeRuntimeMode(value: any, fallback: AgentRuntimeMode = 'normal'): AgentRuntimeMode {
    return value === 'read_only_bypass' ? 'read_only_bypass' : fallback;
}

function normalizeArchitecture(value: string | undefined): string {
    const normalized = String(value || os.arch()).trim().toLowerCase();
    if (normalized === 'arm64') {
        return 'aarch64';
    }
    return normalized || 'unknown';
}

function normalizeNodeKind(value: any): AgentNodeKind {
    return value === 'edge' || value === 'vehicle' ? value : 'cloud';
}

function normalizeDeploymentClass(value: any, nodeKind: AgentNodeKind): AgentDeploymentClass {
    if (value === 'edge' || value === 'vehicle') {
        return value;
    }
    if (nodeKind === 'edge' || nodeKind === 'vehicle') {
        return nodeKind;
    }
    return 'standard';
}

export class Agent {
    private config: AgentConfig;
    private socket: Socket | null = null;
    private agentId: string;
    private apiKey: string;
    private secretKey: string;
    private heartbeatTimer: NodeJS.Timeout | null = null;
    private trafficMonitor: TrafficMonitor;
    private attackDetector: AttackDetector;
    private firewallController: FirewallController;
    private usedNonces: Set<string> = new Set();
    private trafficStatsTimer: NodeJS.Timeout | null = null;
    private runtimeMonitorTimer: NodeJS.Timeout | null = null;
    private protocolEndpoint: string;
    private architecture: string;
    private nodeKind: AgentNodeKind;
    private deploymentClass: AgentDeploymentClass;
    private runtimeMode: AgentRuntimeMode = 'normal';
    private runtimePolicy: AgentRuntimePolicy = clone(DEFAULT_AGENT_RUNTIME_POLICY);
    private protocolPolicy: AgentProtocolPolicy = clone(DEFAULT_AGENT_PROTOCOL_POLICY);
    private protocolStats: AgentProtocolStats = clone(DEFAULT_AGENT_PROTOCOL_STATS);
    private finopsStats: EdgeFinopsStats = clone(DEFAULT_EDGE_FINOPS_STATS);
    private lastProcessCpuUsage = process.cpuUsage();
    private lastCpuSampleAt = Date.now();
    private consecutiveBreachSeconds = 0;
    private consecutiveHealthySeconds = 0;
    private localTrafficStats = {
        packetsProcessed: 0,
        packetsAllowed: 0,
        packetsBlocked: 0,
        packetsInspected: 0,
        bytesProcessed: 0,
        activeFlows: [] as any[]
    };

    constructor(config: AgentConfig) {
        this.config = {
            heartbeatInterval: 30000,
            ...config
        };

        if (!config.agentId || !config.apiKey || !config.secretKey) {
            throw new Error(
                'SECURITY ERROR: agentId, apiKey, and secretKey must be provided by server.\n' +
                'Use the agent registration API to obtain valid credentials.'
            );
        }

        this.agentId = config.agentId;
        this.apiKey = config.apiKey;
        this.secretKey = config.secretKey;
        this.protocolEndpoint = (config.fastpathBaseUrl || process.env.AETHERGUARD_FASTPATH_URL || 'http://127.0.0.1:8081').replace(/\/+$/, '');
        this.architecture = normalizeArchitecture(config.architecture || process.arch);
        this.nodeKind = normalizeNodeKind(config.nodeKind || process.env.AETHERGUARD_NODE_KIND || process.env.AetherGuard_NODE_KIND);
        this.deploymentClass = normalizeDeploymentClass(
            config.deploymentClass || process.env.AETHERGUARD_DEPLOYMENT_CLASS || process.env.AetherGuard_DEPLOYMENT_CLASS,
            this.nodeKind
        );

        this.trafficMonitor = new TrafficMonitor();
        this.attackDetector = new AttackDetector();
        this.firewallController = new FirewallController();
    }

    async start(): Promise<void> {
        logger.info(`Starting AetherGuard Agent: ${this.agentId}`);

        await this.connectToServer();
        this.startHeartbeat();
        this.startTrafficReporting();
        this.restartRuntimeMonitor();

        await this.trafficMonitor.start((event) => {
            this.localTrafficStats.packetsProcessed++;
            this.localTrafficStats.packetsInspected++;
            this.localTrafficStats.bytesProcessed += Math.floor(Math.random() * 500) + 200;

            if (event.sourceIP && event.destPort) {
                const flowId = `${event.sourceIP}:${event.destPort}`;
                const existingFlow = this.localTrafficStats.activeFlows.find((flow) => flow.id === flowId);
                if (!existingFlow) {
                    this.localTrafficStats.activeFlows.unshift({
                        id: flowId,
                        srcIp: event.sourceIP,
                        dstPort: event.destPort,
                        state: 'ESTABLISHED',
                        bytes: Math.floor(Math.random() * 1500) + 500,
                        protocol: 'TCP'
                    });
                    if (this.localTrafficStats.activeFlows.length > 50) {
                        this.localTrafficStats.activeFlows.pop();
                    }
                }
            }

            const threat = this.attackDetector.analyze(event);
            if (threat) {
                this.localTrafficStats.packetsBlocked++;
                this.handleThreat(threat);
            } else {
                this.localTrafficStats.packetsAllowed++;
                const reviewSample = this.attackDetector.assessForReview(event);
                if (reviewSample) {
                    this.handleAsyncReviewSample(reviewSample);
                }
            }
        });

        logger.info('Agent started successfully');
    }

    private startTrafficReporting(): void {
        this.trafficStatsTimer = setInterval(() => {
            if (this.socket?.connected) {
                this.socket.emit('agent:traffic_stats', {
                    agentId: this.agentId,
                    stats: {
                        packetsProcessed: this.localTrafficStats.packetsProcessed,
                        packetsAllowed: this.localTrafficStats.packetsAllowed,
                        packetsBlocked: this.localTrafficStats.packetsBlocked,
                        packetsInspected: this.localTrafficStats.packetsInspected,
                        bytesProcessed: this.localTrafficStats.bytesProcessed,
                        activeFlows: this.localTrafficStats.activeFlows
                    },
                    timestamp: new Date().toISOString()
                });

                this.localTrafficStats.packetsProcessed = 0;
                this.localTrafficStats.packetsAllowed = 0;
                this.localTrafficStats.packetsBlocked = 0;
                this.localTrafficStats.packetsInspected = 0;
                this.localTrafficStats.bytesProcessed = 0;
            }
        }, 5000);
    }

    private async connectToServer(): Promise<void> {
        return new Promise((resolve) => {
            logger.info(`Connecting to server: ${this.config.serverUrl}`);

            this.socket = io(this.config.serverUrl, {
                auth: {
                    type: 'agent',
                    agentId: this.agentId,
                    apiKey: this.apiKey
                },
                reconnection: true,
                reconnectionAttempts: Infinity,
                reconnectionDelay: 5000
            });

            this.socket.on('connect', () => {
                logger.info('Connected to control platform');
                this.sendRegistration();
                resolve();
            });

            this.socket.on('agent:authenticated', (data: { agentId: string; timestamp: number }) => {
                logger.info('Agent authenticated by server', { agentId: data.agentId });
                this.sendRegistration();
            });

            this.socket.on('disconnect', () => {
                logger.warn('Disconnected from control platform');
            });

            this.socket.on('connect_error', (error) => {
                logger.error('Connection error', { error: error.message });
            });

            this.socket.on('command', (signedCommand) => {
                void this.handleSignedCommand(signedCommand);
            });

            setTimeout(() => {
                if (!this.socket?.connected) {
                    logger.warn('Connection timeout, will retry in background');
                    resolve();
                }
            }, 10000);
        });
    }

    private sendRegistration(): void {
        if (!this.socket?.connected) {
            return;
        }

        this.socket.emit('agent:register', {
            agentId: this.agentId,
            hostname: os.hostname(),
            platform: os.platform(),
            arch: this.architecture,
            architecture: this.architecture,
            version: process.env.AETHERGUARD_AGENT_VERSION || process.env.npm_package_version || 'unknown',
            nodeKind: this.nodeKind,
            deploymentClass: this.deploymentClass
        });
    }

    private startHeartbeat(): void {
        this.heartbeatTimer = setInterval(() => {
            this.sendHeartbeat();
        }, this.config.heartbeatInterval);

        this.sendHeartbeat();
    }

    private sendHeartbeat(): void {
        if (!this.socket?.connected) return;

        const status: AgentStatus = {
            agentId: this.agentId,
            hostname: os.hostname(),
            platform: os.platform(),
            architecture: this.architecture,
            nodeKind: this.nodeKind,
            deploymentClass: this.deploymentClass,
            uptime: os.uptime(),
            cpuUsage: this.getCpuUsage(),
            memoryUsage: this.getMemoryUsage(),
            lastHeartbeat: new Date().toISOString(),
            isOnline: true,
            runtimeMode: this.runtimeMode,
            runtimePolicy: clone(this.runtimePolicy),
            protocolStats: clone(this.protocolStats),
            finopsStats: clone(this.finopsStats)
        };

        this.socket.emit('agent:heartbeat', status);
    }

    private restartRuntimeMonitor(): void {
        if (this.runtimeMonitorTimer) {
            clearInterval(this.runtimeMonitorTimer);
        }

        const intervalMs = Math.max(1000, this.runtimePolicy.sampleIntervalSec * 1000);
        this.lastProcessCpuUsage = process.cpuUsage();
        this.lastCpuSampleAt = Date.now();
        this.runtimeMonitorTimer = setInterval(() => {
            void this.evaluateRuntimeBudget();
        }, intervalMs);
    }

    private async evaluateRuntimeBudget(): Promise<void> {
        const cpuUsage = this.getProcessCpuUsage();
        const intervalSeconds = Math.max(1, this.runtimePolicy.sampleIntervalSec);
        const overBudget = cpuUsage > this.runtimePolicy.cpuCeilingPct;

        if (overBudget) {
            this.consecutiveBreachSeconds += intervalSeconds;
            this.consecutiveHealthySeconds = 0;
        } else {
            this.consecutiveHealthySeconds += intervalSeconds;
            this.consecutiveBreachSeconds = 0;
        }

        if (
            this.runtimePolicy.autoReadOnlyBypass
            && this.runtimeMode !== 'read_only_bypass'
            && this.consecutiveBreachSeconds >= this.runtimePolicy.breachWindowSec
        ) {
            this.runtimeMode = 'read_only_bypass';
            this.consecutiveHealthySeconds = 0;
            this.emitRuntimeLog('Agent entered read_only_bypass after CPU budget breach.', { cpuUsage, runtimePolicy: this.runtimePolicy });
            this.sendHeartbeat();
            return;
        }

        if (
            this.runtimeMode === 'read_only_bypass'
            && this.consecutiveHealthySeconds >= this.runtimePolicy.recoveryWindowSec
        ) {
            this.runtimeMode = 'normal';
            this.consecutiveBreachSeconds = 0;
            this.emitRuntimeLog('Agent recovered from read_only_bypass after healthy window.', { cpuUsage, runtimePolicy: this.runtimePolicy });
            this.sendHeartbeat();
        }
    }

    private getCpuUsage(): number {
        const cpus = os.cpus();
        let totalIdle = 0;
        let totalTick = 0;

        for (const cpu of cpus) {
            for (const type in cpu.times) {
                totalTick += cpu.times[type as keyof typeof cpu.times];
            }
            totalIdle += cpu.times.idle;
        }

        return Math.round((1 - totalIdle / totalTick) * 100);
    }

    private getProcessCpuUsage(): number {
        const now = Date.now();
        const usage = process.cpuUsage(this.lastProcessCpuUsage);
        const elapsedMs = Math.max(1, now - this.lastCpuSampleAt);
        const cpuCount = Math.max(1, os.cpus().length);
        this.lastProcessCpuUsage = process.cpuUsage();
        this.lastCpuSampleAt = now;
        const usedMicros = usage.user + usage.system;
        return Number(((usedMicros / (elapsedMs * 1000 * cpuCount)) * 100).toFixed(2));
    }

    private getMemoryUsage(): number {
        const total = os.totalmem();
        const free = os.freemem();
        return Math.round((1 - free / total) * 100);
    }

    private emitRuntimeLog(message: string, details?: Record<string, any>): void {
        logger.warn(message, details);
        if (this.socket?.connected) {
            this.socket.emit('agent:log', {
                level: 'WARN',
                message,
                details,
                timestamp: new Date().toISOString()
            });
        }
    }

    private async handleSignedCommand(signedCommand: SignedCommandInput): Promise<void> {
        const { command, signature, agentId, metadata } = signedCommand;

        if (agentId !== this.agentId) {
            logger.error(`Command not for this agent: expected ${this.agentId}, got ${agentId}`);
            return;
        }

        if (this.usedNonces.has(command.nonce)) {
            logger.warn('Replay attack detected - duplicate nonce', { nonce: command.nonce });
            return;
        }

        const message = JSON.stringify(command);
        const expectedSignature = crypto
            .createHmac('sha256', this.secretKey)
            .update(message)
            .digest('hex');

        try {
            const isValid = crypto.timingSafeEqual(
                Buffer.from(signature, 'hex'),
                Buffer.from(expectedSignature, 'hex')
            );

            if (!isValid) {
                logger.error('Invalid command signature - command rejected', {
                    commandType: command.type,
                    timestamp: command.timestamp
                });
                return;
            }
        } catch {
            logger.error('Signature verification failed - command rejected');
            return;
        }

        const now = Date.now();
        const commandAge = now - command.timestamp;
        const maxAge = 5 * 60 * 1000;

        if (commandAge > maxAge) {
            logger.warn('Stale command rejected', {
                age: commandAge,
                timestamp: command.timestamp
            });
            return;
        }

        if (command.timestamp > now + 60000) {
            logger.warn('Future timestamp in command rejected');
            return;
        }

        this.usedNonces.add(command.nonce);
        setTimeout(() => this.usedNonces.delete(command.nonce), 10 * 60 * 1000);

        logger.info(`Executing verified command: ${command.type}`);
        try {
            await this.executeCommand(command);
            if (this.socket?.connected) {
                this.socket.emit('agent:command_ack', {
                    agentId: this.agentId,
                    commandType: command.type,
                    actionId: command.payload?.actionId || metadata?.actionId,
                    tenantId: metadata?.tenantId,
                    nonce: command.nonce,
                    message: this.runtimeMode === 'read_only_bypass' ? 'Command accepted in read-only bypass context.' : 'Command executed.',
                    timestamp: new Date().toISOString()
                });
            }
        } catch (error: any) {
            if (this.socket?.connected) {
                this.socket.emit('agent:command_failed', {
                    agentId: this.agentId,
                    commandType: command.type,
                    actionId: command.payload?.actionId || metadata?.actionId,
                    tenantId: metadata?.tenantId,
                    nonce: command.nonce,
                    message: error.message || 'Command execution failed',
                    error: error.message || 'Command execution failed',
                    timestamp: new Date().toISOString()
                });
            }
        }
    }

    private async executeCommand(command: { type: string; payload?: any }): Promise<void> {
        if (this.runtimeMode === 'read_only_bypass' && CPU_MUTATING_COMMANDS.has(command.type) && !BYPASS_EXEMPT_COMMANDS.has(command.type)) {
            throw new Error('Agent is in read_only_bypass and rejected a mutating command.');
        }

        switch (command.type) {
            case 'scan':
                await this.runLocalScan();
                break;

            case 'block_ip':
                if (command.payload?.ip) {
                    await this.firewallController.blockIP(command.payload.ip, Number(command.payload.duration || 3600));
                    logger.info(`Blocked IP: ${command.payload.ip}`);
                }
                break;

            case 'unblock_ip':
                if (command.payload?.ip) {
                    await this.firewallController.unblockIP(command.payload.ip);
                    logger.info(`Unblocked IP: ${command.payload.ip}`);
                }
                break;

            case 'update_rules':
                if (Array.isArray(command.payload?.rules)) {
                    const rules = command.payload.rules;
                    const isLegacyRuleSet = rules.every((rule: any) => Array.isArray(rule?.patterns));
                    if (isLegacyRuleSet) {
                        this.attackDetector.updateRules(rules);
                    } else {
                        this.attackDetector.updateRemoteRules(rules);
                    }
                    logger.info('Updated detection rules', {
                        ruleCount: rules.length,
                        mode: isLegacyRuleSet ? 'legacy' : 'remote'
                    });
                }
                break;

            case 'update_runtime_policy':
                this.runtimePolicy = normalizeRuntimePolicy(command.payload?.runtimePolicy, this.runtimePolicy);
                if (typeof command.payload?.runtimeMode === 'string') {
                    this.runtimeMode = normalizeRuntimeMode(command.payload.runtimeMode, this.runtimeMode);
                }
                this.restartRuntimeMonitor();
                this.sendHeartbeat();
                break;

            case 'update_protocol_policy':
                this.protocolPolicy = normalizeProtocolPolicy(command.payload?.protocolPolicy, this.protocolPolicy);
                this.sendHeartbeat();
                break;

            case 'clear_runtime_bypass':
                this.runtimeMode = 'normal';
                this.consecutiveBreachSeconds = 0;
                this.consecutiveHealthySeconds = 0;
                this.sendHeartbeat();
                break;

            default:
                logger.warn(`Unknown command: ${command.type}`);
        }
    }

    private handleThreat(threat: any): void {
        logger.warn('Threat detected', { threat });

        if (this.socket?.connected) {
            this.socket.emit('agent:threat', {
                agentId: this.agentId,
                threat,
                timestamp: new Date().toISOString()
            });
        }

        if (threat.autoBlock && threat.sourceIP) {
            void this.firewallController.blockIP(threat.sourceIP, threat.blockDuration || 3600);
        }
    }

    private handleAsyncReviewSample(sample: AgentReviewSample): void {
        if (!this.socket?.connected) {
            return;
        }

        this.socket.emit('agent:review_sample', {
            agentId: this.agentId,
            sample,
            timestamp: new Date().toISOString()
        });
    }

    async observeMqttMessage(input: MqttObservation): Promise<ProtocolEvaluateResponse | null> {
        return this.observeProtocol('mqtt', input);
    }

    async observeRos2CyberRtEvent(input: Ros2Observation): Promise<ProtocolEvaluateResponse | null> {
        return this.observeProtocol('ros2_cyberrt', input);
    }

    private async observeProtocol(
        protocol: 'mqtt' | 'ros2_cyberrt',
        input: MqttObservation | Ros2Observation
    ): Promise<ProtocolEvaluateResponse | null> {
        const adapter = PROTOCOL_OBSERVER_ADAPTERS[protocol];
        if (!adapter || !adapter.isEnabled(this.protocolPolicy)) {
            return null;
        }

        const request = adapter.buildRequest(this.agentId, input, this.protocolPolicy);
        let response = await this.evaluateProtocol(request);
        if (response && this.runtimeMode === 'read_only_bypass' && adapter.activeGovernance && response.action !== 'inspect') {
            response = {
                ...response,
                verdict: 'monitor',
                action: 'inspect',
                decisionSource: `${response.decisionSource}:read-only-bypass`,
            };
        }

        this.applyProtocolResponse(adapter.moduleId, request.channel || input.channel, response);
        return response;
    }

    private applyProtocolResponse(moduleId: string, channel: string, response: ProtocolEvaluateResponse | null): void {
        const now = new Date().toISOString();
        const applied = protocolModuleRegistryService.applyObservation(moduleId, this.protocolStats, this.finopsStats, {
            response,
            channel,
            sourceRef: this.agentId,
            timestamp: now,
        });
        this.protocolStats = applied.protocolStats;
        this.finopsStats = applied.finopsStats;

        if (this.socket?.connected) {
            this.socket.emit('agent:protocol_observation', {
                agentId: this.agentId,
                protocol: moduleId,
                channel,
                sourceRef: this.agentId,
                response,
                timestamp: now
            });
        }
    }

    private async evaluateProtocol(input: ProtocolEvaluateRequest): Promise<ProtocolEvaluateResponse | null> {
        const fetchImpl = (globalThis as any).fetch;
        if (typeof fetchImpl !== 'function') {
            return null;
        }

        try {
            const response = await fetchImpl(`${this.protocolEndpoint}/v1/traffic/protocol/evaluate`, {
                method: 'POST',
                headers: { 'content-type': 'application/json' },
                body: JSON.stringify(input)
            });

            if (!response?.ok) {
                return null;
            }

            const payload = await response.json();
            return payload as ProtocolEvaluateResponse;
        } catch (error: any) {
            logger.warn('Local protocol fastpath unavailable', {
                agentId: this.agentId,
                protocol: input.protocol,
                error: error?.message
            });
            return null;
        }
    }

    private async runLocalScan(): Promise<void> {
        logger.info('Running local security scan...');

        if (this.socket?.connected) {
            this.socket.emit('agent:scan_started', { agentId: this.agentId });
        }
    }

    async stop(): Promise<void> {
        logger.info('Stopping Agent...');

        if (this.heartbeatTimer) {
            clearInterval(this.heartbeatTimer);
        }
        if (this.trafficStatsTimer) {
            clearInterval(this.trafficStatsTimer);
        }
        if (this.runtimeMonitorTimer) {
            clearInterval(this.runtimeMonitorTimer);
        }

        await this.trafficMonitor.stop();

        if (this.socket) {
            this.socket.disconnect();
        }

        logger.info('Agent stopped');
    }
}

export async function startAgent(serverUrl: string): Promise<Agent> {
    const agentId = process.env.AETHERGUARD_AGENT_ID || process.env.AetherGuard_AGENT_ID || process.env.AGENT_ID || 'probe-agent-01';
    const apiKey = process.env.AETHERGUARD_AGENT_API_KEY || process.env.AetherGuard_AGENT_API_KEY || process.env.AGENT_API_KEY;
    if (!apiKey) {
        throw new Error('AETHERGUARD_AGENT_API_KEY or AGENT_API_KEY environment variable is required');
    }
    const secretKey = process.env.AETHERGUARD_AGENT_SECRET_KEY || process.env.AetherGuard_AGENT_SECRET_KEY || process.env.AGENT_SECRET_KEY;
    const heartbeatIntervalSource = process.env.AETHERGUARD_HEARTBEAT_INTERVAL_MS || process.env.AetherGuard_HEARTBEAT_INTERVAL_MS;
    const heartbeatInterval = heartbeatIntervalSource ? Number(heartbeatIntervalSource) : undefined;

    const nodeKind = normalizeNodeKind(process.env.AETHERGUARD_NODE_KIND || process.env.AetherGuard_NODE_KIND);
    const deploymentClass = normalizeDeploymentClass(
        process.env.AETHERGUARD_DEPLOYMENT_CLASS || process.env.AetherGuard_DEPLOYMENT_CLASS,
        nodeKind
    );

    const agent = new Agent({
        serverUrl,
        agentId,
        apiKey,
        secretKey,
        heartbeatInterval,
        architecture: process.env.AETHERGUARD_AGENT_ARCH || process.env.AetherGuard_AGENT_ARCH || process.arch,
        nodeKind,
        deploymentClass,
        fastpathBaseUrl: process.env.AETHERGUARD_FASTPATH_URL || process.env.AetherGuard_FASTPATH_URL
    });
    await agent.start();
    return agent;
}

/**
 * Attack detector with local rule matching plus shared rule-first review heuristics.
 */

import { randomUUID } from 'crypto';
import logger from '../utils/logger';
import {
  assessDetectionHeuristics,
  buildSeedDetectionRules,
  DetectionAttackFamily,
  DetectionRequest,
  DetectionRuleMatcher,
  DetectionRuleRecord,
  DetectionSeverity,
  DetectionSignal,
  evaluateDetectionRules,
  inferAttackFamily,
  severityToBlockDurationSeconds
} from '../services/detection-engine';
import { TrafficEvent } from './traffic-monitor';

export interface ThreatAlert {
  type: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  sourceIP: string;
  description: string;
  evidence: string;
  ruleId: string;
  autoBlock: boolean;
  blockDuration?: number;
  timestamp: Date;
}

interface DetectionRule {
  id: string;
  name: string;
  type: string;
  severity: ThreatAlert['severity'];
  patterns: RegExp[];
  autoBlock: boolean;
  blockDuration?: number;
}

export interface AgentReviewSample {
  requestId: string;
  timestamp: string;
  sourceIp: string;
  method?: string;
  path?: string;
  headers: Record<string, string>;
  body?: string;
  userAgent?: string;
  evidence?: string;
  protocol: string;
  rawPayload?: string;
  existingSignals: DetectionSignal[];
  matchedRuleIds: string[];
  riskScore: number;
  attackFamily: DetectionAttackFamily;
  decisionSource: string;
  metadata?: Record<string, any>;
}

function mapAttackFamilyToThreatType(family: DetectionAttackFamily | undefined): string {
  switch (family) {
    case 'sqli':
      return 'sql_injection';
    case 'xss':
      return 'xss';
    case 'path_traversal':
      return 'lfi';
    case 'command_injection':
      return 'command_injection';
    case 'ssrf':
      return 'ssrf';
    case 'automation':
      return 'bad_bot';
    default:
      return 'other';
  }
}

export class AttackDetector {
  private rules: DetectionRule[] = [];
  private remoteRules: DetectionRuleRecord[] = [];
  private ipRequestCount: Map<string, { count: number; firstSeen: number }> = new Map();
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor() {
    this.initializeDefaultRules();
    this.startCleanupTimer();
  }

  private initializeDefaultRules(): void {
    this.rules = [
      {
        id: 'SQL-001',
        name: 'SQL Injection - UNION SELECT',
        type: 'sql_injection',
        severity: 'critical',
        patterns: [
          /(\s|%20)union(\s|%20)+select/i,
          /(\s|%20)union(\s|%20)+all(\s|%20)+select/i
        ],
        autoBlock: true,
        blockDuration: 3600
      },
      {
        id: 'SQL-002',
        name: 'SQL Injection - Comment Bypass',
        type: 'sql_injection',
        severity: 'high',
        patterns: [
          /'\s*or\s*'1'\s*=\s*'1/i,
          /'\s*or\s*1\s*=\s*1/i,
          /'\s*--/,
          /'\s*#/
        ],
        autoBlock: true,
        blockDuration: 3600
      },
      {
        id: 'SQL-003',
        name: 'SQL Injection - Stacked Queries',
        type: 'sql_injection',
        severity: 'critical',
        patterns: [/;\s*(drop|delete|insert|update|create|alter|truncate)/i],
        autoBlock: true,
        blockDuration: 7200
      },
      {
        id: 'XSS-001',
        name: 'XSS - Script Tag',
        type: 'xss',
        severity: 'high',
        patterns: [/<script[^>]*>/i, /<\/script>/i, /javascript:/i],
        autoBlock: true,
        blockDuration: 1800
      },
      {
        id: 'XSS-002',
        name: 'XSS - Event Handler',
        type: 'xss',
        severity: 'medium',
        patterns: [/on(load|error|click|mouseover|submit|focus|blur)\s*=/i, /onerror\s*=/i],
        autoBlock: false
      },
      {
        id: 'XSS-003',
        name: 'XSS - Data URI',
        type: 'xss',
        severity: 'high',
        patterns: [/data:\s*text\/html/i, /data:\s*application\/javascript/i],
        autoBlock: true,
        blockDuration: 1800
      },
      {
        id: 'LFI-001',
        name: 'Path Traversal',
        type: 'lfi',
        severity: 'high',
        patterns: [/\.\.\//, /\.\.%2[fF]/, /%2e%2e%2f/i, /\.\.\\/],
        autoBlock: true,
        blockDuration: 3600
      },
      {
        id: 'LFI-002',
        name: 'Sensitive File Access',
        type: 'lfi',
        severity: 'critical',
        patterns: [/\/etc\/passwd/i, /\/etc\/shadow/i, /\/proc\/self/i, /web\.config/i, /\.env/, /\.git\//],
        autoBlock: true,
        blockDuration: 7200
      },
      {
        id: 'CMD-001',
        name: 'Command Injection',
        type: 'command_injection',
        severity: 'critical',
        patterns: [/;\s*(ls|cat|whoami|id|uname|pwd|wget|curl)/i, /\|\s*(ls|cat|whoami|id|uname|pwd|wget|curl)/i, /`[^`]+`/, /\$\([^)]+\)/],
        autoBlock: true,
        blockDuration: 7200
      },
      {
        id: 'BOT-001',
        name: 'Malicious Bot User-Agent',
        type: 'bad_bot',
        severity: 'medium',
        patterns: [/sqlmap/i, /nikto/i, /nessus/i, /masscan/i, /zgrab/i, /python-requests/i, /libwww-perl/i],
        autoBlock: true,
        blockDuration: 86400
      }
    ];

    logger.info(`Loaded ${this.rules.length} detection rules`);
  }

  analyze(event: TrafficEvent): ThreatAlert | null {
    this.updateIPCounter(event.sourceIP);

    const rateThreat = this.checkRateLimit(event.sourceIP);
    if (rateThreat) {
      return rateThreat;
    }

    const contentToCheck = this.buildContentToCheck(event);
    const commandRules = this.rules.filter((rule) => rule.id.startsWith('CMD-'));
    const commandThreat = this.matchLegacyRules(commandRules, contentToCheck, event);
    if (commandThreat) {
      return commandThreat;
    }

    const remainingRules = this.rules.filter((rule) => !rule.id.startsWith('CMD-'));
    const legacyThreat = this.matchLegacyRules(remainingRules, contentToCheck, event);
    if (legacyThreat) {
      return legacyThreat;
    }

    if (this.remoteRules.length > 0) {
      const request = this.buildDetectionRequest(event);
      const evaluation = evaluateDetectionRules(request, this.remoteRules);
      if (evaluation.highestPriorityRule?.action === 'block') {
        return this.buildThreatFromRemoteRule(request, evaluation.highestPriorityRule);
      }
    }

    return null;
  }

  assessForReview(event: TrafficEvent): AgentReviewSample | null {
    const request = this.buildDetectionRequest(event);
    const ruleEvaluation = evaluateDetectionRules(request, [...buildSeedDetectionRules(), ...this.remoteRules]);
    const heuristicAssessment = assessDetectionHeuristics(request);
    const combinedSignals = [...ruleEvaluation.signals, ...heuristicAssessment.signals];
    const riskScore = Math.max(ruleEvaluation.riskScore, heuristicAssessment.riskScore);

    if (ruleEvaluation.ruleVerdict === 'block') {
      return null;
    }

    if (!ruleEvaluation.shouldEscalate && riskScore < 0.4) {
      return null;
    }

    return {
      requestId: request.requestId,
      timestamp: request.timestamp,
      sourceIp: request.sourceIp || '',
      method: request.method,
      path: request.path,
      headers: request.headers || {},
      body: request.body,
      userAgent: request.userAgent,
      evidence: request.evidence,
      protocol: request.protocol || 'agent',
      rawPayload: request.rawPayload,
      existingSignals: combinedSignals,
      matchedRuleIds: ruleEvaluation.matchedRuleIds,
      riskScore: Number(riskScore.toFixed(4)),
      attackFamily: inferAttackFamily(request, combinedSignals),
      decisionSource: ruleEvaluation.highestPriorityRule
        ? `${ruleEvaluation.highestPriorityRule.source}:${ruleEvaluation.highestPriorityRule.action}`
        : 'heuristic_only',
      metadata: {
        localRuleVerdict: ruleEvaluation.ruleVerdict || 'allow',
        eventPort: event.destPort
      }
    };
  }

  private buildContentToCheck(event: TrafficEvent): string {
    return [event.path || '', event.requestBody || '', event.userAgent || '', event.rawLog || ''].join(' ');
  }

  private buildDetectionRequest(event: TrafficEvent): DetectionRequest {
    const headers: Record<string, string> = {};
    if (event.userAgent) {
      headers['user-agent'] = event.userAgent;
    }

    return {
      tenantId: 'agent-local',
      channel: 'agent',
      requestId: randomUUID(),
      timestamp: event.timestamp instanceof Date ? event.timestamp.toISOString() : new Date().toISOString(),
      sourceIp: event.sourceIP,
      method: event.method,
      path: event.path || '/',
      headers,
      body: event.requestBody || '',
      userAgent: event.userAgent || '',
      evidence: event.rawLog || '',
      protocol: `tcp/${event.destPort || 0}`,
      rawPayload: this.buildContentToCheck(event),
      metadata: {
        destPort: event.destPort
      }
    };
  }

  private matchLegacyRules(rules: DetectionRule[], contentToCheck: string, event: TrafficEvent): ThreatAlert | null {
    for (const rule of rules) {
      for (const pattern of rule.patterns) {
        if (pattern.test(contentToCheck)) {
          logger.warn(`Attack detected: ${rule.name}`, {
            ip: event.sourceIP,
            ruleId: rule.id
          });

          return {
            type: rule.type,
            severity: rule.severity,
            sourceIP: event.sourceIP,
            description: rule.name,
            evidence: this.extractEvidence(contentToCheck, pattern),
            ruleId: rule.id,
            autoBlock: rule.autoBlock,
            blockDuration: rule.blockDuration,
            timestamp: new Date()
          };
        }
      }
    }

    return null;
  }

  private buildThreatFromRemoteRule(request: DetectionRequest, rule: DetectionRuleRecord): ThreatAlert {
    return {
      type: mapAttackFamilyToThreatType(rule.attackFamily),
      severity: rule.severity,
      sourceIP: request.sourceIp || 'unknown',
      description: rule.name,
      evidence: this.extractMatcherEvidence(request, rule.matcher),
      ruleId: rule.ruleId,
      autoBlock: rule.action === 'block',
      blockDuration: severityToBlockDurationSeconds(rule.severity),
      timestamp: new Date()
    };
  }

  private extractMatcherEvidence(request: DetectionRequest, matcher: DetectionRuleMatcher): string {
    const content = [
      request.path || '',
      request.body || '',
      request.evidence || '',
      request.userAgent || '',
      request.rawPayload || ''
    ].join(' ');

    const patterns = [
      ...(matcher.pathPatterns || []),
      ...(matcher.bodyPatterns || []),
      ...(matcher.evidencePatterns || []),
      ...(matcher.userAgentPatterns || []),
      ...(matcher.keywordPatterns || [])
    ];

    for (const pattern of patterns) {
      try {
        const evidence = this.extractEvidence(content, new RegExp(pattern, 'i'));
        if (evidence) {
          return evidence;
        }
      } catch {
        continue;
      }
    }

    return content.length > 180 ? `${content.slice(0, 177)}...` : content;
  }

  private updateIPCounter(ip: string): void {
    const now = Date.now();
    const existing = this.ipRequestCount.get(ip);

    if (existing) {
      existing.count += 1;
    } else {
      this.ipRequestCount.set(ip, { count: 1, firstSeen: now });
    }
  }

  private checkRateLimit(ip: string): ThreatAlert | null {
    const data = this.ipRequestCount.get(ip);
    if (!data) {
      return null;
    }

    const elapsed = (Date.now() - data.firstSeen) / 1000;
    const ratePerSecond = data.count / Math.max(elapsed, 1);

    if (ratePerSecond > 100) {
      return {
        type: 'ddos',
        severity: 'critical',
        sourceIP: ip,
        description: 'DDoS Attack Detected - High Request Rate',
        evidence: `${data.count} requests in ${elapsed.toFixed(1)}s (${ratePerSecond.toFixed(1)}/s)`,
        ruleId: 'DDOS-001',
        autoBlock: true,
        blockDuration: 3600,
        timestamp: new Date()
      };
    }

    if (ratePerSecond > 30) {
      return {
        type: 'brute_force',
        severity: 'high',
        sourceIP: ip,
        description: 'Possible Brute Force Attack',
        evidence: `${data.count} requests in ${elapsed.toFixed(1)}s (${ratePerSecond.toFixed(1)}/s)`,
        ruleId: 'BF-001',
        autoBlock: true,
        blockDuration: 1800,
        timestamp: new Date()
      };
    }

    return null;
  }

  private extractEvidence(content: string, pattern: RegExp): string {
    const match = content.match(pattern);
    if (match) {
      const index = content.indexOf(match[0]);
      const start = Math.max(0, index - 20);
      const end = Math.min(content.length, index + match[0].length + 20);
      return `...${content.substring(start, end)}...`;
    }
    return '';
  }

  private startCleanupTimer(): void {
    this.cleanupInterval = setInterval(() => {
      const now = Date.now();
      const expiryTime = 60000;

      for (const [ip, data] of this.ipRequestCount) {
        if (now - data.firstSeen > expiryTime) {
          this.ipRequestCount.delete(ip);
        }
      }
    }, 60000);
  }

  updateRules(newRules: DetectionRule[]): void {
    this.rules = newRules;
    logger.info(`Updated detection rules: ${newRules.length} rules loaded`);
  }

  updateRemoteRules(newRules: DetectionRuleRecord[]): void {
    this.remoteRules = Array.isArray(newRules)
      ? newRules
        .filter((rule) => rule && rule.enabled !== false)
        .filter((rule) => rule.scope === 'all' || rule.scope === 'agent')
      : [];

    logger.info('Updated remote detection rules', {
      ruleCount: this.remoteRules.length
    });
  }

  addRule(rule: DetectionRule): void {
    this.rules.push(rule);
    logger.info(`Added detection rule: ${rule.id}`);
  }

  getRules(): DetectionRule[] {
    return [...this.rules];
  }

  stop(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
    }
    this.ipRequestCount.clear();
  }
}

﻿/**
 * 防火墙控制器
 * 
 * 调用系统防火墙工具封禁/解封 IP:
 * - Linux: iptables / firewalld / ufw
 * - Windows: netsh
 */

import { exec, execFile } from 'child_process';
import { promisify } from 'util';
import os from 'os';
import logger from '../utils/logger';

const execAsync = promisify(exec);
const execFileAsync = promisify(execFile);

interface BlockedIP {
    ip: string;
    reason: string;
    blockedAt: Date;
    expiresAt?: Date;
    timerId?: NodeJS.Timeout;
}

type FirewallBackend = 'iptables' | 'firewalld' | 'ufw' | 'netsh' | 'none';

export class FirewallController {
    private blockedIPs: Map<string, BlockedIP> = new Map();
    private backend: FirewallBackend = 'none';

    constructor() {
        this.detectBackend();
    }

    /**
     * 检测可用的防火墙后端
     */
    private async detectBackend(): Promise<void> {
        const platform = os.platform();

        if (platform === 'win32') {
            this.backend = 'netsh';
            logger.info('Firewall backend: Windows netsh');
            return;
        }

        // Linux: 按优先级检测
        try {
            await execAsync('which firewall-cmd');
            this.backend = 'firewalld';
            logger.info('Firewall backend: firewalld');
            return;
        } catch { }

        try {
            await execAsync('which ufw');
            this.backend = 'ufw';
            logger.info('Firewall backend: ufw');
            return;
        } catch { }

        try {
            await execAsync('which iptables');
            this.backend = 'iptables';
            logger.info('Firewall backend: iptables');
            return;
        } catch { }

        logger.warn('No firewall backend detected');
        this.backend = 'none';
    }

    /**
     * 封禁 IP
     * @param ip 要封禁的 IP 地址
     * @param duration 封禁时长 (秒), 0 表示永久
     * @param reason 封禁原因
     */
    async blockIP(ip: string, duration: number = 3600, reason: string = 'Threat detected'): Promise<boolean> {
        // 验证 IP 格式
        if (!this.isValidIP(ip)) {
            logger.error(`Invalid IP address: ${ip}`);
            return false;
        }

        // 跳过本地地址
        if (this.isLocalIP(ip)) {
            logger.warn(`Skipping local IP: ${ip}`);
            return false;
        }

        // 检查是否已封禁
        if (this.blockedIPs.has(ip)) {
            logger.info(`IP already blocked: ${ip}`);
            return true;
        }

        let success = false;

        try {
            switch (this.backend) {
                case 'iptables':
                    success = await this.blockWithIptables(ip);
                    break;
                case 'firewalld':
                    success = await this.blockWithFirewalld(ip);
                    break;
                case 'ufw':
                    success = await this.blockWithUfw(ip);
                    break;
                case 'netsh':
                    success = await this.blockWithNetsh(ip);
                    break;
                default:
                    logger.warn(`No firewall backend available, IP not blocked: ${ip}`);
                    // 即使没有防火墙，也记录到内存
                    success = true;
            }

            if (success) {
                const blockedIP: BlockedIP = {
                    ip,
                    reason,
                    blockedAt: new Date(),
                    expiresAt: duration > 0 ? new Date(Date.now() + duration * 1000) : undefined
                };

                // 设置自动解封计时器
                if (duration > 0) {
                    blockedIP.timerId = setTimeout(() => {
                        this.unblockIP(ip);
                    }, duration * 1000);
                }

                this.blockedIPs.set(ip, blockedIP);
                logger.info(`Blocked IP: ${ip} for ${duration}s (${reason})`);
            }

            return success;
        } catch (error: any) {
            logger.error(`Failed to block IP: ${ip}`, { error: error.message });
            return false;
        }
    }

    /**
     * 解封 IP
     */
    async unblockIP(ip: string): Promise<boolean> {
        const blocked = this.blockedIPs.get(ip);
        if (!blocked) {
            logger.info(`IP not in block list: ${ip}`);
            return true;
        }

        // 清除计时器
        if (blocked.timerId) {
            clearTimeout(blocked.timerId);
        }

        let success = false;

        try {
            switch (this.backend) {
                case 'iptables':
                    success = await this.unblockWithIptables(ip);
                    break;
                case 'firewalld':
                    success = await this.unblockWithFirewalld(ip);
                    break;
                case 'ufw':
                    success = await this.unblockWithUfw(ip);
                    break;
                case 'netsh':
                    success = await this.unblockWithNetsh(ip);
                    break;
                default:
                    success = true;
            }

            if (success) {
                this.blockedIPs.delete(ip);
                logger.info(`Unblocked IP: ${ip}`);
            }

            return success;
        } catch (error: any) {
            logger.error(`Failed to unblock IP: ${ip}`, { error: error.message });
            return false;
        }
    }

    // === iptables 实现 - SECURITY FIX: 使用 execFile 防止命令注入 ===

    private async blockWithIptables(ip: string): Promise<boolean> {
        try {
            // 使用 execFile 代替 exec，防止命令注入
            // 参数作为数组传递，不进行 shell 解析
            const args = ['-A', 'INPUT', '-s', ip, '-j', 'DROP'];
            await execFileAsync('iptables', args);
            logger.info(`iptables: Blocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`iptables block failed: ${error.message}`);
            return false;
        }
    }

    private async unblockWithIptables(ip: string): Promise<boolean> {
        try {
            const args = ['-D', 'INPUT', '-s', ip, '-j', 'DROP'];
            await execFileAsync('iptables', args);
            logger.info(`iptables: Unblocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`iptables unblock failed: ${error.message}`);
            return false;
        }
    }

    // === firewalld 实现 - SECURITY FIX: 使用 execFile 防止命令注入 ===

    private async blockWithFirewalld(ip: string): Promise<boolean> {
        try {
            // 使用参数化命令执行
            const args = [
                '--add-rich-rule',
                `rule family="ipv4" source address="${ip}" reject`
            ];
            await execFileAsync('firewall-cmd', args);
            logger.info(`firewalld: Blocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`firewalld block failed: ${error.message}`);
            return false;
        }
    }

    private async unblockWithFirewalld(ip: string): Promise<boolean> {
        try {
            const args = [
                '--remove-rich-rule',
                `rule family="ipv4" source address="${ip}" reject`
            ];
            await execFileAsync('firewall-cmd', args);
            logger.info(`firewalld: Unblocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`firewalld unblock failed: ${error.message}`);
            return false;
        }
    }

    // === ufw 实现 - SECURITY FIX: 使用 execFile 防止命令注入 ===

    private async blockWithUfw(ip: string): Promise<boolean> {
        try {
            // 使用参数化命令执行
            const args = ['deny', 'from', ip];
            await execFileAsync('ufw', args);
            logger.info(`ufw: Blocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`ufw block failed: ${error.message}`);
            return false;
        }
    }

    private async unblockWithUfw(ip: string): Promise<boolean> {
        try {
            const args = ['delete', 'deny', 'from', ip];
            await execFileAsync('ufw', args);
            logger.info(`ufw: Unblocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`ufw unblock failed: ${error.message}`);
            return false;
        }
    }

    // === Windows netsh 实现 - SECURITY FIX: 使用 execFile 防止命令注入 ===

    private async blockWithNetsh(ip: string): Promise<boolean> {
        try {
            // 生成安全的规则名称
            const ruleName = `AetherGuard_Block_${ip.replace(/\./g, '_')}`;

            // 使用参数化命令执行
            const args = [
                'advfirewall',
                'firewall',
                'add',
                'rule',
                `name=${ruleName}`,
                'dir=in',
                'action=block',
                `remoteip=${ip}`
            ];
            await execFileAsync('netsh', args);
            logger.info(`netsh: Blocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`netsh block failed: ${error.message}`);
            return false;
        }
    }

    private async unblockWithNetsh(ip: string): Promise<boolean> {
        try {
            const ruleName = `AetherGuard_Block_${ip.replace(/\./g, '_')}`;

            const args = [
                'advfirewall',
                'firewall',
                'delete',
                'rule',
                `name=${ruleName}`
            ];
            await execFileAsync('netsh', args);
            logger.info(`netsh: Unblocked IP ${ip}`);
            return true;
        } catch (error: any) {
            logger.error(`netsh unblock failed: ${error.message}`);
            return false;
        }
    }

    // === 辅助方法 ===

    /**
     * 验证 IP 格式 - SECURITY FIX: 严格验证防止命令注入
     */
    private isValidIP(ip: string): boolean {
        // 严格IPv4验证: 每个八位字节必须是0-255
        const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
        // 严格IPv6验证
        const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::(?:[0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4}$|^(?:[0-9a-fA-F]{1,4}:){1,7}:$/;

        // 额外安全检查: 确保没有shell特殊字符
        const shellChars = /[;&|`$(){}[\]<>\\'"!#%^*?\n\r\t]/;
        if (shellChars.test(ip)) {
            logger.warn(`Blocked IP with shell characters: ${ip}`);
            return false;
        }

        return ipv4Regex.test(ip) || ipv6Regex.test(ip);
    }

    /**
     * 检查是否为本地 IP
     * SECURITY FIX CVE-2026-022: Complete private IP range detection
     */
    private isLocalIP(ip: string): boolean {
        // IPv4 loopback
        if (ip === '127.0.0.1' || ip.startsWith('127.')) {
            return true;
        }

        // IPv6 loopback
        if (ip === '::1') {
            return true;
        }

        // Private ranges (RFC 1918)
        if (ip.startsWith('10.')) {
            return true;
        }

        if (ip.startsWith('192.168.')) {
            return true;
        }

        // SECURITY FIX CVE-2026-022: Check full 172.16.0.0/12 range (172.16.0.0 - 172.31.255.255)
        const parts = ip.split('.');
        if (parts[0] === '172') {
            const secondOctet = parseInt(parts[1], 10);
            if (secondOctet >= 16 && secondOctet <= 31) {
                return true;
            }
        }

        // Link-local (APIPA)
        if (ip.startsWith('169.254.')) {
            return true;
        }

        // IPv6 link-local
        if (ip.toLowerCase().startsWith('fe80:')) {
            return true;
        }

        // IPv6 unique local addresses
        if (ip.toLowerCase().startsWith('fc') || ip.toLowerCase().startsWith('fd')) {
            return true;
        }

        return false;
    }

    /**
     * 获取所有被封禁的 IP
     */
    getBlockedIPs(): BlockedIP[] {
        return Array.from(this.blockedIPs.values());
    }

    /**
     * 检查 IP 是否被封禁
     */
    isBlocked(ip: string): boolean {
        return this.blockedIPs.has(ip);
    }

    /**
     * 获取当前使用的防火墙后端
     */
    getBackend(): FirewallBackend {
        return this.backend;
    }

    /**
     * 清除所有封禁
     */
    async clearAll(): Promise<void> {
        for (const ip of this.blockedIPs.keys()) {
            await this.unblockIP(ip);
        }
    }
}

