/**
 * Tool Executor - L4: Capability Incarnation Layer
 * Safe execution of security analysis tools
 */

import { v4 as uuidv4 } from 'uuid';
import { spawn } from 'child_process';
import {
    ToolDefinition,
    ToolExecutionRequest,
    ToolExecutionResult,
    SandboxOptions
} from '../core/types';
import logger from '../../utils/logger';

const DEFAULT_SANDBOX_OPTIONS: SandboxOptions = {
    enabled: true,
    timeout: 30000,
    memoryLimit: 256 * 1024 * 1024,
    networkAccess: false,
    fileSystemAccess: false
};

export class ToolExecutor {
    private registeredTools: Map<string, ToolDefinition> = new Map();
    private executionHistory: Map<string, ToolExecutionResult> = new Map();
    private defaultSandbox: SandboxOptions;

    constructor(sandboxOptions: Partial<SandboxOptions> = {}) {
        this.defaultSandbox = { ...DEFAULT_SANDBOX_OPTIONS, ...sandboxOptions };
        this.registerBuiltinTools();
    }

    private registerBuiltinTools(): void {
        this.registerTool({
            name: 'explain_sql',
            description: 'Safely execute EXPLAIN on SQL queries to detect injection risks',
            parameters: [
                { name: 'query', type: 'string', required: true, description: 'SQL query to explain' },
                { name: 'database', type: 'string', required: false, description: 'Database type (mysql, postgresql)' }
            ],
            riskLevel: 'low',
            requiresSandbox: true
        });

        this.registerTool({
            name: 'http_probe',
            description: 'Send safe HTTP probe to check endpoint behavior',
            parameters: [
                { name: 'url', type: 'string', required: true, description: 'URL to probe' },
                { name: 'method', type: 'string', required: false, description: 'HTTP method' },
                { name: 'headers', type: 'object', required: false, description: 'Headers to send' }
            ],
            riskLevel: 'medium',
            requiresSandbox: true
        });

        this.registerTool({
            name: 'decode_payload',
            description: 'Decode various encoding formats to analyze payloads',
            parameters: [
                { name: 'payload', type: 'string', required: true, description: 'Encoded payload' },
                { name: 'encoding', type: 'string', required: false, description: 'Encoding type (base64, url, hex)' }
            ],
            riskLevel: 'low',
            requiresSandbox: false
        });

        this.registerTool({
            name: 'analyze_headers',
            description: 'Analyze HTTP headers for security issues',
            parameters: [
                { name: 'headers', type: 'object', required: true, description: 'Headers to analyze' }
            ],
            riskLevel: 'low',
            requiresSandbox: false
        });

        this.registerTool({
            name: 'check_pattern',
            description: 'Check content against security patterns',
            parameters: [
                { name: 'content', type: 'string', required: true, description: 'Content to check' },
                { name: 'patterns', type: 'array', required: false, description: 'Patterns to match' }
            ],
            riskLevel: 'low',
            requiresSandbox: false
        });
    }

    registerTool(tool: ToolDefinition): void {
        this.registeredTools.set(tool.name, tool);
        logger.info(`Tool registered: ${tool.name}`);
    }

    async execute(request: ToolExecutionRequest): Promise<ToolExecutionResult> {
        const tool = this.registeredTools.get(request.toolName);
        
        if (!tool) {
            return this.createErrorResult(request, `Unknown tool: ${request.toolName}`);
        }

        const validation = this.validateParameters(tool, request.parameters);
        if (!validation.valid) {
            return this.createErrorResult(request, validation.error!);
        }

        const sandbox = request.sandboxOptions || 
            (tool.requiresSandbox ? this.defaultSandbox : { ...DEFAULT_SANDBOX_OPTIONS, enabled: false });

        const startTime = Date.now();

        try {
            let output: any;

            switch (tool.name) {
                case 'explain_sql':
                    output = await this.executeExplainSQL(request.parameters, sandbox);
                    break;
                case 'http_probe':
                    output = await this.executeHTTPProbe(request.parameters, sandbox);
                    break;
                case 'decode_payload':
                    output = this.executeDecodePayload(request.parameters);
                    break;
                case 'analyze_headers':
                    output = this.executeAnalyzeHeaders(request.parameters);
                    break;
                case 'check_pattern':
                    output = this.executeCheckPattern(request.parameters);
                    break;
                default:
                    output = await this.executeGenericTool(tool, request.parameters, sandbox);
            }

            const result: ToolExecutionResult = {
                requestId: request.requestId,
                toolName: request.toolName,
                success: true,
                output,
                executionTime: Date.now() - startTime,
                sandboxed: sandbox.enabled
            };

            this.executionHistory.set(request.requestId, result);
            return result;

        } catch (error: any) {
            const result: ToolExecutionResult = {
                requestId: request.requestId,
                toolName: request.toolName,
                success: false,
                output: null,
                error: error.message,
                executionTime: Date.now() - startTime,
                sandboxed: sandbox.enabled
            };

            this.executionHistory.set(request.requestId, result);
            return result;
        }
    }

    private validateParameters(
        tool: ToolDefinition, 
        params: Record<string, any>
    ): { valid: boolean; error?: string } {
        for (const param of tool.parameters) {
            if (param.required && !(param.name in params)) {
                return { valid: false, error: `Missing required parameter: ${param.name}` };
            }

            if (param.name in params && param.validation) {
                const regex = new RegExp(param.validation);
                if (!regex.test(String(params[param.name]))) {
                    return { valid: false, error: `Parameter ${param.name} failed validation` };
                }
            }
        }

        return { valid: true };
    }

    private async executeExplainSQL(
        params: Record<string, any>,
        sandbox: SandboxOptions
    ): Promise<any> {
        const { query, database = 'mysql' } = params;

        const sanitized = this.sanitizeSQLQuery(query);
        
        const analysis = {
            originalQuery: query.substring(0, 200),
            sanitizedQuery: sanitized.substring(0, 200),
            riskIndicators: [] as string[],
            suggestedIndex: null as string | null,
            warnings: [] as string[]
        };

        const dangerousPatterns = [
            { pattern: /;\s*(drop|delete|truncate|update|insert)/i, risk: 'Multiple statements detected' },
            { pattern: /union\s+select/i, risk: 'UNION injection pattern' },
            { pattern: /'\s*or\s+'/i, risk: 'Boolean injection pattern' },
            { pattern: /--\s*$/m, risk: 'Comment injection pattern' },
            { pattern: /load_file\s*\(/i, risk: 'File access attempt' },
            { pattern: /into\s+(out|dump)file/i, risk: 'File write attempt' }
        ];

        for (const { pattern, risk } of dangerousPatterns) {
            if (pattern.test(query)) {
                analysis.riskIndicators.push(risk);
            }
        }

        if (query.length > 10000) {
            analysis.warnings.push('Query exceeds safe length limit');
        }

        return analysis;
    }

    private sanitizeSQLQuery(query: string): string {
        let sanitized = query;
        sanitized = sanitized.replace(/--.*$/gm, '');
        sanitized = sanitized.replace(/\/\*[\s\S]*?\*\//g, '');
        sanitized = sanitized.replace(/;\s*(drop|delete|truncate|update|insert)/gi, '');
        return sanitized;
    }

    private async executeHTTPProbe(
        params: Record<string, any>,
        sandbox: SandboxOptions
    ): Promise<any> {
        const { url, method = 'GET', headers = {} } = params;

        if (!sandbox.networkAccess) {
            return {
                status: 'blocked',
                reason: 'Network access disabled in sandbox',
                url: this.sanitizeURL(url)
            };
        }

        const sanitizedURL = this.sanitizeURL(url);
        
        return {
            status: 'simulated',
            url: sanitizedURL,
            method,
            simulatedResponse: {
                statusCode: 200,
                headers: { 'content-type': 'application/json' },
                body: '{ "status": "ok" }'
            },
            note: 'HTTP probe executed in safe mode'
        };
    }

    private sanitizeURL(url: string): string {
        try {
            const parsed = new URL(url);
            const dangerousParams = ['password', 'token', 'secret', 'key', 'auth'];
            
            const sanitizedParams = new URLSearchParams();
            for (const [key, value] of parsed.searchParams) {
                if (dangerousParams.some(d => key.toLowerCase().includes(d))) {
                    sanitizedParams.set(key, '[REDACTED]');
                } else {
                    sanitizedParams.set(key, value.substring(0, 100));
                }
            }
            
            parsed.search = sanitizedParams.toString();
            return parsed.toString();
        } catch {
            return '[INVALID_URL]';
        }
    }

    private executeDecodePayload(params: Record<string, any>): any {
        const { payload, encoding = 'auto' } = params;
        const results: { encoding: string; decoded: string; success: boolean }[] = [];

        const tryDecode = (enc: string): { decoded: string; success: boolean } => {
            try {
                let decoded: string;
                
                switch (enc) {
                    case 'base64':
                        decoded = Buffer.from(payload, 'base64').toString('utf-8');
                        break;
                    case 'url':
                        decoded = decodeURIComponent(payload);
                        break;
                    case 'hex':
                        decoded = Buffer.from(payload.replace(/\s/g, ''), 'hex').toString('utf-8');
                        break;
                    case 'unicode':
                        decoded = payload.replace(/\\u([0-9a-f]{4})/gi, (_match: string, hex: string) => 
                            String.fromCharCode(parseInt(hex, 16))
                        );
                        break;
                    case 'html':
                        decoded = payload.replace(/&#x([0-9a-f]+);/gi, (_match: string, hex: string) =>
                            String.fromCharCode(parseInt(hex, 16))
                        ).replace(/&#(\d+);/g, (_match: string, dec: string) =>
                            String.fromCharCode(parseInt(dec, 10))
                        );
                        break;
                    default:
                        return { decoded: payload, success: false };
                }
                
                return { decoded, success: true };
            } catch {
                return { decoded: payload, success: false };
            }
        };

        const encodings = encoding === 'auto' 
            ? ['base64', 'url', 'hex', 'unicode', 'html']
            : [encoding];

        for (const enc of encodings) {
            const result = tryDecode(enc);
            if (result.success) {
                results.push({ encoding: enc, decoded: result.decoded, success: true });
            }
        }

        return {
            original: payload.substring(0, 500),
            decodedVersions: results,
            totalDecoded: results.length
        };
    }

    private executeAnalyzeHeaders(params: Record<string, any>): any {
        const { headers } = params;
        const issues: { header: string; issue: string; severity: string }[] = [];
        const recommendations: string[] = [];

        const securityHeaders = {
            'strict-transport-security': { required: true, recommendation: 'Add HSTS header' },
            'content-security-policy': { required: true, recommendation: 'Add CSP header' },
            'x-frame-options': { required: true, recommendation: 'Add X-Frame-Options header' },
            'x-content-type-options': { required: true, recommendation: 'Add X-Content-Type-Options header' },
            'x-xss-protection': { required: false, recommendation: 'Consider adding X-XSS-Protection header' }
        };

        const headerKeys = Object.keys(headers).map(k => k.toLowerCase());

        for (const [header, config] of Object.entries(securityHeaders)) {
            if (!headerKeys.includes(header)) {
                issues.push({
                    header,
                    issue: 'Missing security header',
                    severity: config.required ? 'high' : 'medium'
                });
                recommendations.push(config.recommendation);
            }
        }

        for (const [key, value] of Object.entries(headers)) {
            const lowerKey = key.toLowerCase();
            
            if (lowerKey === 'server' && String(value).length > 20) {
                issues.push({
                    header: key,
                    issue: 'Server header reveals too much information',
                    severity: 'low'
                });
            }

            if (lowerKey === 'x-powered-by') {
                issues.push({
                    header: key,
                    issue: 'Technology disclosure',
                    severity: 'low'
                });
                recommendations.push('Remove X-Powered-By header');
            }
        }

        return {
            headerCount: Object.keys(headers).length,
            issues,
            recommendations,
            securityScore: Math.max(0, 100 - issues.length * 15)
        };
    }

    private executeCheckPattern(params: Record<string, any>): any {
        const { content, patterns = [] } = params;
        const matches: { pattern: string; match: string; position: number }[] = [];

        const defaultPatterns = [
            { name: 'sql_injection', pattern: /'\s*(or|and)\s+('|\d)/i },
            { name: 'xss_script', pattern: /<script[^>]*>/i },
            { name: 'xss_event', pattern: /on\w+\s*=/i },
            { name: 'path_traversal', pattern: /\.\.[\/\\]/ },
            { name: 'command_injection', pattern: /[;&|`$]/ },
            { name: 'ssrf', pattern: /^(https?:)?\/\/(localhost|127\.0\.0\.1|0\.0\.0\.0)/i }
        ];

        const patternsToCheck = patterns.length > 0 
            ? patterns.map((p: string) => ({ name: p, pattern: new RegExp(p, 'gi') }))
            : defaultPatterns;

        for (const { name, pattern } of patternsToCheck) {
            const regex = pattern instanceof RegExp ? pattern : new RegExp(pattern, 'gi');
            let match;
            
            while ((match = regex.exec(content)) !== null) {
                matches.push({
                    pattern: name,
                    match: match[0].substring(0, 50),
                    position: match.index
                });
            }
        }

        return {
            contentLength: content.length,
            patternsChecked: patternsToCheck.length,
            matchesFound: matches.length,
            matches: matches.slice(0, 20),
            riskLevel: matches.length > 5 ? 'high' : matches.length > 0 ? 'medium' : 'low'
        };
    }

    private async executeGenericTool(
        tool: ToolDefinition,
        params: Record<string, any>,
        sandbox: SandboxOptions
    ): Promise<any> {
        return {
            tool: tool.name,
            status: 'not_implemented',
            params: Object.keys(params),
            sandboxed: sandbox.enabled
        };
    }

    private createErrorResult(request: ToolExecutionRequest, error: string): ToolExecutionResult {
        return {
            requestId: request.requestId,
            toolName: request.toolName,
            success: false,
            output: null,
            error,
            executionTime: 0,
            sandboxed: false
        };
    }

    getTool(name: string): ToolDefinition | undefined {
        return this.registeredTools.get(name);
    }

    listTools(): ToolDefinition[] {
        return Array.from(this.registeredTools.values());
    }

    getExecutionHistory(requestId?: string): ToolExecutionResult | ToolExecutionResult[] {
        if (requestId) {
            return this.executionHistory.get(requestId) || [];
        }
        return Array.from(this.executionHistory.values());
    }
}

export const toolExecutor = new ToolExecutor();

/**
 * Agent Orchestrator - L1: Multi-Agent Collaboration Layer
 * Routes traffic to specialized agents and coordinates analysis
 */

import { v4 as uuidv4 } from 'uuid';
import {
    AgentRole,
    AgentConfig,
    TrafficContext,
    TrafficRequest,
    AnalysisResult,
    SecurityDecision,
    MultiAgentConfig,
    Evidence,
    CaseAction,
    AttackFamily,
    AnalysisResult as AgentAnalysisResult
} from './types';
import { BaseAgent, ExpertAgent } from './base-agent';
import { MessageBus, globalMessageBus } from './message-bus';
import { SocratesAgent } from '../roles/socrates-agent';
import { PlatoAgent } from '../roles/plato-agent';
import { AristotleAgent } from '../roles/aristotle-agent';
import { DebateProtocol } from '../debate/debate-protocol';
import {
    blendDistributions,
    buildDebateTriggerMetrics,
    confidenceFromDistribution,
    dominantVerdict,
    verdictToDecision
} from './scoring';
import logger from '../../utils/logger';

interface AgentRegistry {
    [key: string]: BaseAgent;
}

interface AnalysisTask {
    id: string;
    requestId: string;
    startTime: Date;
    status: 'pending' | 'running' | 'completed' | 'failed';
    results: Map<AgentRole, AnalysisResult>;
    finalDecision?: SecurityDecision;
    threatType?: AttackFamily;
}

export class AgentOrchestrator {
    private agents: AgentRegistry = {};
    private messageBus: MessageBus;
    private config: MultiAgentConfig;
    private activeTasks: Map<string, AnalysisTask> = new Map();
    private expertRouting: Map<string, AgentRole[]> = new Map();
    private debateProtocol: DebateProtocol;

    constructor(config: MultiAgentConfig, messageBus: MessageBus = globalMessageBus) {
        this.config = config;
        this.messageBus = messageBus;
        this.debateProtocol = new DebateProtocol(this.messageBus);
        this.initializeAgents();
        this.setupExpertRouting();
    }

    private initializeAgents(): void {
        const agentConfigs = this.createAgentConfigs();

        for (const [role, agentConfig] of Object.entries(agentConfigs)) {
            let agent: BaseAgent;

            switch (role as AgentRole) {
                case 'socrates':
                    agent = new SocratesAgent(agentConfig, this.messageBus);
                    break;
                case 'plato':
                    agent = new PlatoAgent(agentConfig, this.messageBus);
                    break;
                case 'aristotle':
                    agent = new AristotleAgent(agentConfig, this.messageBus);
                    break;
                case 'arbitrator':
                case 'orchestrator':
                    continue;
                default:
                    continue;
            }

            this.agents[role] = agent;
            logger.info(`Agent registered: ${role}`);
        }
    }

    private createAgentConfigs(): Record<AgentRole, AgentConfig> {
        const baseConfig = {
            timeout: this.config.timeouts.analysis,
            modelTimeout: this.config.timeouts.modelResponse,
            maxRetries: 3,
            heuristicOnly: this.config.heuristicOnly
        };

        return {
            socrates: {
                identity: {
                    id: `socrates-${uuidv4()}`,
                    role: 'socrates',
                    team: 'red',
                    name: 'Socrates',
                    description: 'Red team agent - Attempts to find bypasses and mutations',
                    capabilities: ['mutation', 'bypass_detection', 'attack_simulation']
                },
                modelConfig: this.config.models.cloud,
                ...baseConfig
            },
            plato: {
                identity: {
                    id: `plato-${uuidv4()}`,
                    role: 'plato',
                    team: 'blue',
                    name: 'Plato',
                    description: 'Blue team agent - Schema validation and compliance checking',
                    capabilities: ['schema_validation', 'compliance_check', 'pattern_matching']
                },
                modelConfig: this.config.models.cloud,
                ...baseConfig
            },
            aristotle: {
                identity: {
                    id: `aristotle-${uuidv4()}`,
                    role: 'aristotle',
                    team: 'analyst',
                    name: 'Aristotle',
                    description: 'Analyst agent - Historical behavior and anomaly analysis',
                    capabilities: ['anomaly_detection', 'behavior_analysis', 'statistical_analysis']
                },
                modelConfig: this.config.models.cloud,
                ...baseConfig
            },
            arbitrator: {
                identity: {
                    id: `arbitrator-${uuidv4()}`,
                    role: 'arbitrator',
                    team: 'arbitrator',
                    name: 'Arbitrator',
                    description: 'Final decision maker - Resolves debates and makes final calls',
                    capabilities: ['debate_resolution', 'final_decision', 'policy_enforcement']
                },
                modelConfig: this.config.models.cloud,
                ...baseConfig
            },
            orchestrator: {
                identity: {
                    id: `orchestrator-${uuidv4()}`,
                    role: 'orchestrator',
                    team: 'analyst',
                    name: 'Orchestrator',
                    description: 'System coordinator - Routes requests and manages agents',
                    capabilities: ['routing', 'coordination', 'task_management']
                },
                modelConfig: this.config.models.cloud,
                ...baseConfig
            }
        };
    }

    private setupExpertRouting(): void {
        this.expertRouting.set('sqli', ['socrates', 'plato', 'aristotle']);
        this.expertRouting.set('xss', ['socrates', 'plato', 'aristotle']);
        this.expertRouting.set('command_injection', ['socrates', 'plato']);
        this.expertRouting.set('path_traversal', ['socrates', 'plato']);
        this.expertRouting.set('ssrf', ['socrates', 'plato', 'aristotle']);
        this.expertRouting.set('automation', ['aristotle', 'plato']);
        this.expertRouting.set('authentication', ['aristotle', 'plato']);
        this.expertRouting.set('rate_limit', ['aristotle']);
        this.expertRouting.set('business_logic', ['socrates', 'aristotle']);
        this.expertRouting.set('benign', ['socrates', 'plato', 'aristotle']);
        this.expertRouting.set('default', ['socrates', 'plato', 'aristotle']);
    }

    async initialize(): Promise<void> {
        for (const agent of Object.values(this.agents)) {
            await agent.initialize();
        }
        logger.info('Agent Orchestrator initialized');
    }

    async analyze(request: TrafficRequest, context?: Partial<TrafficContext>): Promise<SecurityDecision> {
        const startTime = Date.now();
        const taskId = uuidv4();

        const fullContext: TrafficContext = {
            request,
            history: context?.history || [],
            openApiSpec: context?.openApiSpec,
            relatedRequests: context?.relatedRequests || []
        };

        const task: AnalysisTask = {
            id: taskId,
            requestId: request.id,
            startTime: new Date(),
            status: 'running',
            results: new Map()
        };
        this.activeTasks.set(taskId, task);

        try {
            const threatType = this.classifyThreatType(request);
            task.threatType = threatType;
            const assignedAgents = this.routeToExperts(threatType);

            logger.debug(`Task ${taskId}: Assigned agents ${assignedAgents.join(', ')} for threat type ${threatType}`);

            const analysisPromises = assignedAgents.map(async (role) => {
                const agent = this.agents[role];
                if (!agent) {
                    logger.warn(`Agent not found: ${role}`);
                    return null;
                }

                try {
                    const result = await agent.analyze(fullContext);
                    task.results.set(role, result);
                    return result;
                } catch (error: any) {
                    logger.error(`Agent ${role} analysis failed`, { error: error.message });
                    return null;
                }
            });

            await Promise.all(analysisPromises);

            const decision = await this.makeDecision(task, request, threatType);

            task.status = 'completed';
            task.finalDecision = decision;

            return decision;
        } catch (error: any) {
            task.status = 'failed';
            logger.error(`Analysis task ${taskId} failed`, { error: error.message });
            throw error;
        } finally {
            this.activeTasks.delete(taskId);
        }
    }

    private classifyThreatType(request: TrafficRequest): AttackFamily {
        const content = [
            request.path,
            request.body || '',
            JSON.stringify(request.queryParams || {}),
            request.userAgent || ''
        ].join(' ').toLowerCase();

        if (content.includes('select') || content.includes('union') || content.includes("' or ")) {
            return 'sqli';
        }
        if (content.includes('<script') || content.includes('javascript:') || content.includes('onerror')) {
            return 'xss';
        }
        if (content.includes('../') || content.includes('/etc/') || content.includes('cmd.exe')) {
            return 'path_traversal';
        }
        if (content.includes('|') || content.includes(';') || content.includes('&&')) {
            return 'command_injection';
        }
        if (content.includes('169.254.169.254') || content.includes('metadata.google.internal') || content.includes('latest/meta-data')) {
            return 'ssrf';
        }
        if (
            content.includes('sqlmap') ||
            content.includes('python-requests') ||
            content.includes('headless') ||
            content.includes('selenium') ||
            content.includes('curl/') ||
            content.includes('wget/')
        ) {
            return 'automation';
        }
        if (content.includes('login') || content.includes('auth') || content.includes('token')) {
            return 'authentication';
        }

        return 'benign';
    }

    private routeToExperts(threatType: AttackFamily): AgentRole[] {
        if (this.config.experimentMode === 'single_agent') {
            return [this.config.primarySingleAgentRole || 'aristotle'];
        }

        return this.expertRouting.get(threatType) || this.expertRouting.get('default')!;
    }

    private async makeDecision(
        task: AnalysisTask,
        request: TrafficRequest,
        threatType: AttackFamily
    ): Promise<SecurityDecision> {
        const results = Array.from(task.results.values());
        
        if (results.length === 0) {
            return this.createDefaultDecision(request, task.id, threatType);
        }

        const allEvidence: Evidence[] = [];
        let worstVerdict: 'safe' | 'suspicious' | 'malicious' | 'unknown' = 'safe';

        for (const result of results) {
            if (result) {
                allEvidence.push(...result.evidence);

                if (this.verdictSeverity(result.verdict) > this.verdictSeverity(worstVerdict)) {
                    worstVerdict = result.verdict;
                }
            }
        }

        const aggregateDistribution = blendDistributions(results);
        const aggregateVerdict = dominantVerdict(aggregateDistribution);
        const triggerMetrics = this.shouldTriggerDebate(results);
        const shouldDebate =
            this.config.experimentMode !== 'single_agent' &&
            this.config.experimentMode !== 'multi_agent_no_debate' &&
            triggerMetrics.triggered;
        let finalVerdict: SecurityDecision['verdict'] = verdictToDecision(aggregateVerdict);
        let finalConfidence = confidenceFromDistribution(aggregateDistribution);
        let debateSession;

        if (shouldDebate) {
            logger.info(`Debate triggered for request ${request.id}`);
            debateSession = await this.triggerDebate(task, request, results, triggerMetrics);
            if (debateSession.finalVerdict) {
                finalVerdict = this.mapDebateVerdictToDecision(debateSession.finalVerdict.decision);
                finalConfidence = debateSession.finalVerdict.confidence;
            }
        }

        const threatLevel = this.calculateThreatLevel(
            finalVerdict === 'block' ? 'malicious' : finalVerdict === 'monitor' ? 'suspicious' : worstVerdict,
            allEvidence
        );
        const actions = this.determineActions(finalVerdict, threatLevel, request);
        const roleAnalysisMs = Number(
            Math.max(...results.map((result) => result.analysisLatencyMs || result.modelLatencyMs || 0)).toFixed(2)
        );
        const debateMs = Number((debateSession?.latencyMs || 0).toFixed(2));
        const endToEndMs = Number((Date.now() - task.startTime.getTime()).toFixed(2));
        const layersActivated = [1, 2];
        if (results.some((result) => result.modelTier)) {
            layersActivated.push(6);
        }
        if (debateSession) {
            layersActivated.push(5);
        }

        return {
            id: uuidv4(),
            requestId: request.id,
            timestamp: new Date(),
            verdict: finalVerdict,
            confidence: finalConfidence,
            threatLevel,
            reasoning: this.buildReasoning(results, triggerMetrics, debateSession?.finalVerdict?.reasoning),
            evidence: allEvidence,
            actions,
            caseFileId: task.id,
            processingTime: endToEndMs,
            layersActivated,
            aggregatedDistribution: debateSession?.finalVerdict?.aggregatedDistribution || aggregateDistribution,
            analysisResults: results,
            experimentMode: this.config.experimentMode || 'multi_agent_with_debate',
            attackFamily: threatType,
            routeMode: results.find((result) => result.routeMode && result.routeMode !== 'unknown')?.routeMode || 'unknown',
            stageLatencies: {
                proxyMs: 0,
                roleAnalysisMs,
                debateMs,
                synthesisMs: 0,
                asyncReviewMs: roleAnalysisMs + debateMs,
                endToEndMs
            },
            debateSession
        };
    }

    private verdictSeverity(verdict: string): number {
        const severityMap: Record<string, number> = {
            'safe': 0,
            'unknown': 1,
            'suspicious': 2,
            'malicious': 3
        };
        return severityMap[verdict] || 0;
    }

    private mapVerdictToDecision(verdict: string): SecurityDecision['verdict'] {
        const mapping: Record<string, SecurityDecision['verdict']> = {
            'safe': 'allow',
            'suspicious': 'monitor',
            'malicious': 'block',
            'unknown': 'challenge'
        };
        return mapping[verdict] || 'challenge';
    }

    private shouldTriggerDebate(results: AgentAnalysisResult[]): ReturnType<typeof buildDebateTriggerMetrics> {
        const validResults = results.filter(r => r !== null) as AnalysisResult[];
        
        if (validResults.length < 2) {
            return {
                triggered: false,
                labelConflict: false,
                confidenceRange: 0,
                divergence: 0,
                reasons: []
            };
        }

        return buildDebateTriggerMetrics(
            validResults,
            this.config.thresholds.debateDivergence,
            this.config.thresholds.debateConfidenceRange
        );
    }

    private async triggerDebate(
        task: AnalysisTask, 
        request: TrafficRequest, 
        results: AnalysisResult[],
        triggerMetrics: ReturnType<typeof buildDebateTriggerMetrics>
    ) {
        return this.debateProtocol.initiateDebate(
            task.requestId,
            results.filter((result): result is AnalysisResult => result != null),
            request,
            triggerMetrics
        );
    }

    private mapDebateVerdictToDecision(verdict: 'safe' | 'malicious' | 'requires_review'): SecurityDecision['verdict'] {
        switch (verdict) {
            case 'safe':
                return 'allow';
            case 'malicious':
                return 'block';
            default:
                return 'monitor';
        }
    }

    private calculateThreatLevel(
        verdict: string, 
        evidence: Evidence[]
    ): SecurityDecision['threatLevel'] {
        if (verdict === 'malicious') {
            const hasCritical = evidence.some(e => e.severity === 'critical');
            return hasCritical ? 'critical' : 'high';
        }

        if (verdict === 'suspicious') {
            return 'medium';
        }

        if (verdict === 'unknown') {
            return 'low';
        }

        return 'none';
    }

    private determineActions(
        verdict: SecurityDecision['verdict'],
        threatLevel: string,
        request: TrafficRequest
    ): CaseAction[] {
        const actions: CaseAction[] = [];

        switch (verdict) {
            case 'block':
                actions.push({
                    action: 'block',
                    target: request.sourceIP,
                    reason: `Threat detected: ${threatLevel}`,
                    duration: 3600,
                    automated: true
                });
                break;
            case 'monitor':
                actions.push({
                    action: 'monitor',
                    target: request.sourceIP,
                    reason: 'Suspicious activity detected',
                    automated: true
                });
                break;
            case 'challenge':
                actions.push({
                    action: 'investigate',
                    target: request.sourceIP,
                    reason: 'Uncertain - requires review',
                    automated: false
                });
                break;
        }

        return actions;
    }

    private buildReasoning(
        results: (AnalysisResult | null)[],
        triggerMetrics?: ReturnType<typeof buildDebateTriggerMetrics>,
        debateReasoning?: string
    ): string {
        const validResults = results.filter(r => r !== null) as AnalysisResult[];
        
        if (validResults.length === 0) {
            return 'No analysis results available';
        }

        const parts = validResults.map(r => 
            `[${r.role}]: ${r.reasoning} (confidence: ${(r.confidence * 100).toFixed(0)}%, route: ${r.routeMode || 'unknown'})`
        );

        if (triggerMetrics?.triggered) {
            parts.push(`debate_trigger=${triggerMetrics.reasons.join(',')}; divergence=${triggerMetrics.divergence.toFixed(3)}; range=${triggerMetrics.confidenceRange.toFixed(3)}`);
        }
        if (debateReasoning) {
            parts.push(`debate_outcome=${debateReasoning}`);
        }

        return parts.join(' | ');
    }

    private createDefaultDecision(request: TrafficRequest, taskId: string, threatType: AttackFamily): SecurityDecision {
        return {
            id: uuidv4(),
            requestId: request.id,
            timestamp: new Date(),
            verdict: 'challenge',
            confidence: 0.5,
            threatLevel: 'low',
            reasoning: 'Unable to complete analysis - defaulting to challenge',
            evidence: [],
            actions: [{
                action: 'investigate',
                target: request.sourceIP,
                reason: 'Analysis incomplete',
                automated: false
            }],
            caseFileId: taskId,
            processingTime: 0,
            layersActivated: [1],
            experimentMode: this.config.experimentMode || 'multi_agent_with_debate',
            attackFamily: threatType,
            routeMode: 'unknown',
            stageLatencies: {
                proxyMs: 0,
                roleAnalysisMs: 0,
                debateMs: 0,
                synthesisMs: 0,
                asyncReviewMs: 0,
                endToEndMs: 0
            }
        };
    }

    async shutdown(): Promise<void> {
        for (const agent of Object.values(this.agents)) {
            await agent.shutdown();
        }
        this.activeTasks.clear();
        logger.info('Agent Orchestrator shutdown complete');
    }

    getAgent(role: AgentRole): BaseAgent | undefined {
        return this.agents[role];
    }

    getActiveTaskCount(): number {
        return this.activeTasks.size;
    }

    getStats(): {
        activeTasks: number;
        registeredAgents: number;
        messageBusStats: ReturnType<MessageBus['getStats']>;
    } {
        return {
            activeTasks: this.activeTasks.size,
            registeredAgents: Object.keys(this.agents).length,
            messageBusStats: this.messageBus.getStats()
        };
    }

    getAgents(): Record<string, BaseAgent> {
        return { ...this.agents };
    }
}

export default AgentOrchestrator;

/**
 * Base Agent - Abstract Base Class for All Agents
 * L1: Collaboration Layer Foundation
 */

import { v4 as uuidv4 } from 'uuid';
import {
    AgentConfig,
    AgentIdentity,
    AgentMessage,
    AgentRole,
    AnalysisResult,
    TrafficContext,
    ModelConfig,
    ModelResponse,
    Evidence,
    AttackFamily,
    SecurityVerdict
} from './types';
import { MessageBus } from './message-bus';
import { distributionFromVerdict, normalizeDistribution } from './scoring';
import logger from '../../utils/logger';

// Re-export AgentMessage for convenience
export type { AgentMessage };

interface HeuristicSignalMatch {
    family: AttackFamily;
    label: string;
    severity: 'hard' | 'soft';
}

interface ContentHeuristicSignals {
    attackFamily: AttackFamily;
    hardSignals: HeuristicSignalMatch[];
    softSignals: HeuristicSignalMatch[];
    normalizedInput: string;
}

export abstract class BaseAgent {
    protected config: AgentConfig;
    protected identity: AgentIdentity;
    protected messageBus: MessageBus;
    protected isActive: boolean = false;
    protected pendingTasks: Map<string, Promise<any>> = new Map();

    constructor(config: AgentConfig, messageBus: MessageBus) {
        this.config = config;
        this.identity = config.identity;
        this.messageBus = messageBus;
    }

    abstract analyze(context: TrafficContext): Promise<AnalysisResult>;

    abstract getSystemPrompt(): string;

    async initialize(): Promise<void> {
        this.isActive = true;
        this.subscribeToMessages();
        logger.info(`Agent initialized: ${this.identity.name} (${this.identity.role})`);
    }

    async shutdown(): Promise<void> {
        this.isActive = false;
        logger.info(`Agent shutdown: ${this.identity.name}`);
    }

    protected subscribeToMessages(): void {
        this.messageBus.subscribe(this.identity.role, async (message: AgentMessage) => {
            await this.handleMessage(message);
        });
    }

    protected async handleMessage(message: AgentMessage): Promise<void> {
        if (!this.isActive) {
            logger.warn(`Agent ${this.identity.name} received message while inactive`);
            return;
        }

        try {
            switch (message.type) {
                case 'analysis_request':
                    await this.handleAnalysisRequest(message);
                    break;
                case 'debate_invitation':
                    await this.handleDebateInvitation(message);
                    break;
                case 'debate_argument':
                    await this.handleDebateArgument(message);
                    break;
                case 'tool_result':
                    await this.handleToolResult(message);
                    break;
                default:
                    logger.debug(`Agent ${this.identity.name} ignoring message type: ${message.type}`);
            }
        } catch (error: any) {
            logger.error(`Agent ${this.identity.name} error handling message`, {
                error: error.message,
                messageType: message.type
            });
        }
    }

    protected abstract handleAnalysisRequest(message: AgentMessage): Promise<void>;
    protected abstract handleDebateInvitation(message: AgentMessage): Promise<void>;
    protected abstract handleDebateArgument(message: AgentMessage): Promise<void>;
    protected abstract handleToolResult(message: AgentMessage): Promise<void>;

    async sendMessage(to: AgentRole | 'broadcast', type: AgentMessage['type'], payload: any): Promise<void> {
        const message: AgentMessage = {
            id: uuidv4(),
            type,
            from: this.identity.role,
            to,
            payload,
            timestamp: new Date(),
            priority: 'medium'
        };

        await this.messageBus.publish(message);
    }

    protected async callModel(prompt: string, context?: Record<string, any>): Promise<ModelResponse> {
        const timeoutMs = this.config.modelTimeout ?? this.config.timeout;
        const routeModeOverride = context?.routeModeOverride;
        const analysisPurpose = context?.analysisPurpose;

        if (this.config.heuristicOnly) {
            throw new Error('heuristic_fallback_enabled');
        }

        try {
            const response = await this.messageBus.requestModel({
                id: uuidv4(),
                prompt,
                context: {
                    role: this.identity.role,
                    agentId: this.identity.id,
                    ...(context || {})
                },
                tier: this.determineModelTier(),
                priority: 'medium',
                timeout: timeoutMs,
                sanitizationLevel: 'basic',
                routeModeOverride,
                analysisPurpose
            });

            return response;
        } catch (error: any) {
            logger.error(`Model call failed for ${this.identity.name}`, {
                error: error.message,
                timeoutMs
            });
            throw error;
        }
    }

    protected determineModelTier(): 'local' | 'cloud' {
        if (this.config.modelConfig.provider === 'dashscope' || 
            this.config.modelConfig.provider === 'zhipu' ||
            this.config.modelConfig.provider === 'openai' ||
            this.config.modelConfig.provider === 'anthropic') {
            return 'cloud';
        }
        return 'local';
    }

    protected buildAnalysisPrompt(context: TrafficContext): string {
        const { request, history, openApiSpec } = context;

        let prompt = this.getSystemPrompt();
        prompt += '\n\n--- REQUEST TO ANALYZE ---\n';
        prompt += `Method: ${request.method}\n`;
        prompt += `Path: ${request.path}\n`;
        prompt += `Source IP: ${request.sourceIP}\n`;
        prompt += `User-Agent: ${request.userAgent || 'Unknown'}\n`;

        if (request.body) {
            prompt += `Body: ${this.sanitizeForPrompt(request.body)}\n`;
        }

        if (request.queryParams && Object.keys(request.queryParams).length > 0) {
            prompt += `Query Params: ${JSON.stringify(request.queryParams)}\n`;
        }

        if (history.length > 0) {
            prompt += '\n--- RECENT HISTORY ---\n';
            prompt += `Total historical events: ${history.length}\n`;
            const recentHistory = history.slice(-5);
            for (const event of recentHistory) {
                prompt += `- ${event.timestamp}: ${event.action} (${event.result})\n`;
            }
        }

        if (openApiSpec) {
            prompt += '\n--- EXPECTED API SCHEMA ---\n';
            prompt += `Path: ${openApiSpec.path}\n`;
            prompt += `Method: ${openApiSpec.method}\n`;
        }

        return prompt;
    }

    protected buildModelContext(context: TrafficContext, extra: Record<string, any> = {}): Record<string, any> {
        return {
            tenantId: context.request.tenantId,
            requestId: context.request.id,
            routeModeOverride: context.request.routeModeOverride,
            analysisPurpose: context.request.analysisPurpose || 'primary',
            ...extra
        };
    }

    protected sanitizeForPrompt(input: string): string {
        let sanitized = input;
        sanitized = sanitized.replace(/Bearer\s+[A-Za-z0-9\-._~+/]+=*/gi, 'Bearer [REDACTED]');
        sanitized = sanitized.replace(/password["\s:=]+["']?[^"'\s,}]+/gi, 'password=[REDACTED]');
        sanitized = sanitized.replace(/api[_-]?key["\s:=]+["']?[^"'\s,}]+/gi, 'api_key=[REDACTED]');
        sanitized = sanitized.replace(/token["\s:=]+["']?[^"'\s,}]+/gi, 'token=[REDACTED]');
        return sanitized;
    }

    protected createEvidence(
        type: Evidence['type'],
        description: string,
        severity: Evidence['severity'],
        data: any,
        source: string = this.identity.name
    ): Evidence {
        return {
            type,
            description,
            severity,
            data,
            source
        };
    }

    protected inferAttackFamily(input: string): AttackFamily {
        return this.inspectContentHeuristics(input).attackFamily;
    }

    protected inspectContentHeuristics(input: string): ContentHeuristicSignals {
        const normalizedInput = input.toLowerCase();
        const hardSignals: HeuristicSignalMatch[] = [];
        const softSignals: HeuristicSignalMatch[] = [];

        const hardRules: Array<{ family: AttackFamily; label: string; pattern: RegExp }> = [
            { family: 'sqli', label: 'sql_or_bypass', pattern: /'\s*(or|and)\s*['"(]?[a-z0-9_]+/i },
            { family: 'sqli', label: 'sql_union', pattern: /union\s+select/i },
            { family: 'sqli', label: 'sql_stacked_query', pattern: /;\s*(drop|delete|update|insert)\b/i },
            { family: 'sqli', label: 'sql_time_probe', pattern: /\b(sleep|benchmark)\s*\(/i },
            { family: 'xss', label: 'script_tag', pattern: /<script/i },
            { family: 'xss', label: 'event_handler', pattern: /on(?:error|load|click)\s*=/i },
            { family: 'xss', label: 'javascript_scheme', pattern: /javascript:/i },
            { family: 'path_traversal', label: 'relative_traversal', pattern: /\.\.\//i },
            { family: 'path_traversal', label: 'encoded_traversal', pattern: /%2e%2e|%252e%252e/i },
            { family: 'path_traversal', label: 'sensitive_file', pattern: /\/etc\/passwd|boot\.ini/i },
            { family: 'command_injection', label: 'shell_separator', pattern: /(?:;|&&|\|\|)\s*(cat|curl|wget|bash|sh|type|powershell)\b/i },
            { family: 'command_injection', label: 'command_substitution', pattern: /\$\(|`[^`]+`/i },
            { family: 'ssrf', label: 'metadata_service', pattern: /169\.254\.169\.254|metadata\.google\.internal|latest\/meta-data/i }
        ];

        const softRules: Array<{ family: AttackFamily; label: string; pattern: RegExp }> = [
            { family: 'sqli', label: 'sql_keyword', pattern: /\bselect\b|\bfrom\b|\border\s+by\b/i },
            { family: 'xss', label: 'html_markup', pattern: /<[^>]+>/i },
            { family: 'path_traversal', label: 'filesystem_probe', pattern: /\b(?:config|backup|logs?)\b/i },
            { family: 'command_injection', label: 'loopback_target', pattern: /\b127\.0\.0\.1\b|\blocalhost\b/i },
            { family: 'command_injection', label: 'network_probe', pattern: /\bping\b|\bnslookup\b|\btraceroute\b/i },
            { family: 'ssrf', label: 'url_fetch_surface', pattern: /\bhttps?:\/\/|\burl\s*=|\bfetch\b/i },
            { family: 'automation', label: 'automation_user_agent', pattern: /\bsqlmap\b|\bnikto\b|\bpython-requests\b|\bheadless\b|\bselenium\b|\bcurl\/|\bwget\//i },
            { family: 'authentication', label: 'auth_surface', pattern: /\blogin\b|\bauth\b|\btoken\b|\bsession\b/i }
        ];

        for (const rule of hardRules) {
            if (rule.pattern.test(normalizedInput)) {
                hardSignals.push({
                    family: rule.family,
                    label: rule.label,
                    severity: 'hard'
                });
            }
        }

        for (const rule of softRules) {
            if (rule.pattern.test(normalizedInput)) {
                softSignals.push({
                    family: rule.family,
                    label: rule.label,
                    severity: 'soft'
                });
            }
        }

        const rankedFamilies: AttackFamily[] = [
            'sqli',
            'xss',
            'path_traversal',
            'command_injection',
            'ssrf',
            'automation',
            'authentication',
            'business_logic',
            'other',
            'benign'
        ];

        const familyScores = new Map<AttackFamily, number>();
        for (const signal of hardSignals) {
            familyScores.set(signal.family, (familyScores.get(signal.family) || 0) + 3);
        }
        for (const signal of softSignals) {
            familyScores.set(signal.family, (familyScores.get(signal.family) || 0) + 1);
        }

        const attackFamily = rankedFamilies.reduce<AttackFamily>((best, family) => {
            if ((familyScores.get(family) || 0) > (familyScores.get(best) || 0)) {
                return family;
            }
            return best;
        }, 'benign');

        return {
            attackFamily,
            hardSignals,
            softSignals,
            normalizedInput
        };
    }

    protected finalizeAnalysisResult(
        partial: Omit<AnalysisResult, 'classScores'> & { classScores?: AnalysisResult['classScores'] }
    ): AnalysisResult {
        const classScores = partial.classScores
            ? normalizeDistribution(partial.classScores)
            : distributionFromVerdict(partial.verdict as SecurityVerdict, partial.confidence);

        return {
            ...partial,
            classScores
        };
    }

    getIdentity(): AgentIdentity {
        return this.identity;
    }

    isAgentActive(): boolean {
        return this.isActive;
    }

    getPendingTaskCount(): number {
        return this.pendingTasks.size;
    }
}

export abstract class ExpertAgent extends BaseAgent {
    protected expertise: string[];

    constructor(config: AgentConfig, messageBus: MessageBus, expertise: string[]) {
        super(config, messageBus);
        this.expertise = expertise;
    }

    canHandle(requestType: string): boolean {
        return this.expertise.some(exp => 
            requestType.toLowerCase().includes(exp.toLowerCase())
        );
    }

    getExpertise(): string[] {
        return this.expertise;
    }
}

export interface AgentFactory {
    createAgent(role: AgentRole, config: AgentConfig, messageBus: MessageBus): BaseAgent;
}

/**
 * Message Bus - Inter-Agent Communication System
 * L1: Collaboration Layer - Message Routing
 */

import { v4 as uuidv4 } from 'uuid';
import { EventEmitter } from 'events';
import {
    AgentMessage,
    AgentRole,
    ModelRequest,
    ModelResponse,
    MessageEnvelope
} from './types';
import logger from '../../utils/logger';

export type MessageHandler = (message: AgentMessage) => Promise<void>;
export type ModelRequestHandler = (request: ModelRequest) => Promise<ModelResponse>;

interface Subscription {
    id: string;
    role: AgentRole;
    handler: MessageHandler;
}

interface PendingRequest {
    resolve: (response: ModelResponse) => void;
    reject: (error: Error) => void;
    timeout: NodeJS.Timeout;
}

const MESSAGE_EVENT = 'message_queued';
const SHUTDOWN_EVENT = 'shutdown';

export class MessageBus extends EventEmitter {
    private subscriptions: Map<AgentRole, Subscription[]> = new Map();
    private messageQueue: MessageEnvelope[] = [];
    private pendingModelRequests: Map<string, PendingRequest> = new Map();
    private modelRequestHandler: ModelRequestHandler | null = null;
    private isProcessing: boolean = false;
    private maxQueueSize: number = 10000;
    private defaultTTL: number = 60000;
    private maxRetries: number = 3;
    private processingPromise: Promise<void> | null = null;
    private processingTimeout: NodeJS.Timeout | null = null;
    private readonly PROCESSING_TIMEOUT_MS: number = 30000;

    constructor() {
        super();
        this.setMaxListeners(100);
        this.startProcessing();
    }

    subscribe(role: AgentRole, handler: MessageHandler): () => void {
        const subscriptionId = uuidv4();
        const subscription: Subscription = {
            id: subscriptionId,
            role,
            handler
        };

        if (!this.subscriptions.has(role)) {
            this.subscriptions.set(role, []);
        }

        this.subscriptions.get(role)!.push(subscription);
        logger.debug(`Subscription added for role: ${role}`);

        return () => {
            const subs = this.subscriptions.get(role);
            if (subs) {
                const index = subs.findIndex(s => s.id === subscriptionId);
                if (index !== -1) {
                    subs.splice(index, 1);
                    logger.debug(`Subscription removed for role: ${role}`);
                }
            }
        };
    }

    async publish(message: AgentMessage): Promise<void> {
        if (this.messageQueue.length >= this.maxQueueSize) {
            logger.warn('Message queue full, dropping oldest messages');
            this.messageQueue = this.messageQueue.slice(-this.maxQueueSize / 2);
        }

        const envelope: MessageEnvelope = {
            message,
            routingKey: this.createRoutingKey(message),
            ttl: this.defaultTTL,
            retryCount: 0
        };

        this.messageQueue.push(envelope);
        logger.debug(`Message published: ${message.type} from ${message.from} to ${message.to}`);
        
        this.emit(MESSAGE_EVENT);
    }

    async publishDirect(role: AgentRole, message: AgentMessage): Promise<void> {
        const subscriptions = this.subscriptions.get(role);
        if (!subscriptions || subscriptions.length === 0) {
            logger.warn(`No subscribers for role: ${role}`);
            return;
        }

        for (const subscription of subscriptions) {
            try {
                await subscription.handler(message);
            } catch (error: any) {
                logger.error(`Error in message handler for ${role}`, { error: error.message });
            }
        }
    }

    setModelRequestHandler(handler: ModelRequestHandler): void {
        this.modelRequestHandler = handler;
    }

    async requestModel(request: ModelRequest): Promise<ModelResponse> {
        return new Promise((resolve, reject) => {
            const timeout = setTimeout(() => {
                this.pendingModelRequests.delete(request.id);
                reject(new Error(`Model request timeout: ${request.id}`));
            }, request.timeout);

            this.pendingModelRequests.set(request.id, {
                resolve,
                reject,
                timeout
            });

            this.processModelRequest(request).catch(error => {
                clearTimeout(timeout);
                this.pendingModelRequests.delete(request.id);
                reject(error);
            });
        });
    }

    private async processModelRequest(request: ModelRequest): Promise<void> {
        if (!this.modelRequestHandler) {
            throw new Error('No model request handler registered');
        }

        try {
            const response = await this.modelRequestHandler(request);
            const pending = this.pendingModelRequests.get(request.id);
            if (pending) {
                clearTimeout(pending.timeout);
                pending.resolve(response);
                this.pendingModelRequests.delete(request.id);
            }
        } catch (error: any) {
            const pending = this.pendingModelRequests.get(request.id);
            if (pending) {
                clearTimeout(pending.timeout);
                pending.reject(error);
                this.pendingModelRequests.delete(request.id);
            }
        }
    }

    private startProcessing(): void {
        this.isProcessing = true;
        this.processingPromise = this.processQueue();
    }

    private async processQueue(): Promise<void> {
        while (this.isProcessing) {
            while (this.messageQueue.length > 0) {
                const envelope = this.messageQueue.shift();
                if (!envelope) continue;

                if (this.isExpired(envelope)) {
                    logger.debug(`Message expired: ${envelope.message.id}`);
                    continue;
                }

                await this.deliverMessage(envelope);
            }

            if (!this.isProcessing) break;

            try {
                await this.waitForNewMessage();
            } catch (error) {
                if (this.isProcessing) {
                    logger.debug('Message queue wait interrupted, continuing processing');
                }
                break;
            }
        }
    }

    private waitForNewMessage(): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                this.removeListener(MESSAGE_EVENT, onMessage);
                this.removeListener(SHUTDOWN_EVENT, onShutdown);
                if (this.isProcessing) {
                    resolve();
                } else {
                    reject(new Error('Shutdown'));
                }
            }, this.PROCESSING_TIMEOUT_MS);

            const onMessage = () => {
                clearTimeout(timeoutId);
                this.removeListener(SHUTDOWN_EVENT, onShutdown);
                resolve();
            };

            const onShutdown = () => {
                clearTimeout(timeoutId);
                this.removeListener(MESSAGE_EVENT, onMessage);
                reject(new Error('Shutdown'));
            };

            if (typeof timeoutId.unref === 'function') {
                timeoutId.unref();
            }
            this.once(MESSAGE_EVENT, onMessage);
            this.once(SHUTDOWN_EVENT, onShutdown);
        });
    }

    private async deliverMessage(envelope: MessageEnvelope): Promise<void> {
        const { message } = envelope;
        const targetRoles = message.to === 'broadcast' 
            ? Array.from(this.subscriptions.keys())
            : [message.to as AgentRole];

        for (const role of targetRoles) {
            const subscriptions = this.subscriptions.get(role);
            if (!subscriptions) continue;

            for (const subscription of subscriptions) {
                try {
                    await subscription.handler(message);
                } catch (error: any) {
                    logger.error(`Failed to deliver message to ${role}`, {
                        error: error.message,
                        messageId: message.id
                    });

                    if (envelope.retryCount < this.maxRetries) {
                        envelope.retryCount++;
                        this.messageQueue.unshift(envelope);
                        logger.debug(`Retrying message delivery (attempt ${envelope.retryCount})`);
                    }
                }
            }
        }
    }

    private createRoutingKey(message: AgentMessage): string {
        return `${message.type}.${message.from}.${message.to}`;
    }

    private isExpired(envelope: MessageEnvelope): boolean {
        const age = Date.now() - envelope.message.timestamp.getTime();
        return age > envelope.ttl;
    }

    shutdown(): void {
        this.isProcessing = false;
        this.emit(SHUTDOWN_EVENT);
        
        if (this.processingTimeout) {
            clearTimeout(this.processingTimeout);
            this.processingTimeout = null;
        }

        this.subscriptions.clear();
        this.messageQueue = [];

        for (const [, pending] of this.pendingModelRequests) {
            clearTimeout(pending.timeout);
            pending.reject(new Error('Message bus shutdown'));
        }
        this.pendingModelRequests.clear();

        this.removeAllListeners();

        logger.info('Message bus shutdown complete');
    }

    getStats(): {
        queueSize: number;
        subscriptionCount: number;
        pendingRequests: number;
    } {
        let totalSubscriptions = 0;
        for (const subs of this.subscriptions.values()) {
            totalSubscriptions += subs.length;
        }

        return {
            queueSize: this.messageQueue.length,
            subscriptionCount: totalSubscriptions,
            pendingRequests: this.pendingModelRequests.size
        };
    }
}

export const globalMessageBus = new MessageBus();

/**
 * Multi-Agent Decision System - Core Types
 * 7-Layer Architecture for AI-powered Security Analysis
 */

import type { AIRoutingMode } from '../../services/platform-config.service';

// ============================================================================
// Layer 1: Collaboration - Base Types
// ============================================================================

export type AgentRole = 'socrates' | 'plato' | 'aristotle' | 'arbitrator' | 'orchestrator';
export type AgentTeam = 'red' | 'blue' | 'analyst' | 'arbitrator';
export type SecurityVerdict = 'safe' | 'suspicious' | 'malicious' | 'unknown';
export type AttackFamily =
    | 'benign'
    | 'sqli'
    | 'xss'
    | 'path_traversal'
    | 'command_injection'
    | 'ssrf'
    | 'automation'
    | 'authentication'
    | 'business_logic'
    | 'other';
export type AnalysisPurpose = 'primary' | 'learning_verification';
export type ExperimentMode =
    | 'single_agent'
    | 'multi_agent_no_debate'
    | 'multi_agent_with_debate';

export interface VerdictDistribution {
