import { Request, Response } from 'express';
import os from 'os';
import { getAgentSystem } from '../routes/ai-system.routes';
import logger from '../../utils/logger';
import { isDemoMode } from '../../config/app-mode';

export class AdminController {
    static getErrors(req: Request, res: Response) {
        try {
            const agentSystem = getAgentSystem();
            let errors: any[] = [];

            if (agentSystem && agentSystem.isInitialized()) {
                const probeReport = agentSystem.getProbeReport();
                const alerts = probeReport.alerts || [];

                errors = alerts
                    .filter((alert: any) => alert.severity === 'critical' || alert.severity === 'high')
                    .slice(0, 10)
                    .map((alert: any) => ({
                        userId: alert.metadata?.sourceIP || 'unknown',
                        errorCode: alert.metadata?.ruleId || 'SECURITY_ALERT',
                        message: alert.message || 'Security event detected',
                        timestamp: alert.timestamp || new Date().toISOString()
                    }));
            }

            // 无论是否是演示模式，都返回真实数据
            res.json(errors);
        } catch (error: any) {
            logger.error('Failed to get errors', { error: error.message });
            res.json([]);
        }
    }

    static getPerformance(req: Request, res: Response) {
        try {
            const cpus = os.cpus();
            const totalMemory = os.totalmem();
            const freeMemory = os.freemem();
            const usedMemory = totalMemory - freeMemory;
            const memoryUsage = (usedMemory / totalMemory) * 100;

            let totalIdle = 0;
            let totalTick = 0;
            cpus.forEach(cpu => {
                for (const type in cpu.times) {
                    totalTick += (cpu.times as any)[type];
                }
                totalIdle += cpu.times.idle;
            });
            const cpuUsage = 100 - ~~(100 * totalIdle / totalTick);

            const agentSystem = getAgentSystem();
            let totalAgents = 0;
            let avgCpuOverhead = 0;
            let avgLatency = 0;

            if (agentSystem && agentSystem.isInitialized()) {
                const stats = agentSystem.getStats();
                totalAgents = stats.orchestrator.registeredAgents;

                const probeReport = agentSystem.getProbeReport();
                const agents = probeReport.agents || [];

                if (agents.length > 0) {
                    const totalCpu = agents.reduce((sum: number, a: any) => sum + (a.cpuUsage || 0), 0);
                    const totalLatency = agents.reduce((sum: number, a: any) => sum + (a.responseTime || 0), 0);
                    avgCpuOverhead = totalCpu / agents.length;
                    avgLatency = totalLatency / agents.length;
                }
            }

            const performance = {
                server: {
                    cpu: Math.round(cpuUsage * 10) / 10,
                    memory: Math.round(memoryUsage * 10) / 10,
                    uptime: os.uptime(),
                    platform: os.platform(),
                    hostname: os.hostname()
                },
                clients: {
                    total_agents: totalAgents,
                    avg_cpu_overhead: avgCpuOverhead.toFixed(2),
                    avg_latency_added: `${Math.round(avgLatency)}ms`
                }
            };

            res.json(performance);
        } catch (error: any) {
            logger.error('Failed to get performance', { error: error.message });
            res.json({
                server: {
                    cpu: 0,
                    memory: 0,
                    uptime: 0
                },
                clients: {
                    total_agents: 0,
                    avg_cpu_overhead: '0',
                    avg_latency_added: '0ms'
                }
            });
        }
    }

    static submitLogs(req: Request, res: Response) {
        try {
            const { data } = req.body;

            if (!data) {
                return res.status(400).json({ error: 'backend.missing_data' });
            }

            logger.info('[ADMIN] Received logs', { data });

            res.json({ success: true, message: 'backend.logs_received' });
        } catch (error) {
            logger.error('[ADMIN] Processing failed', {
                error: error instanceof Error ? error.message : String(error)
            });
            res.status(400).json({ error: 'backend.processing_failed' });
        }
    }
}

/**
 * Investigation Controller
 *
 * Handles API requests for bug investigation agent team.
 */

import { Request, Response, NextFunction } from 'express';
import { BugInvestigationTeam } from '../../ai-agents/investigation';
import { InvestigationService } from '../../services/investigation.service';

export class InvestigationController {
  private investigationTeam: BugInvestigationTeam;
  private investigationService: InvestigationService;

  constructor() {
    this.investigationTeam = BugInvestigationTeam.getInstance();
    this.investigationService = new InvestigationService();
  }

  /**
   * Start a new investigation
   */
  public startInvestigation = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const {
        title,
        description,
        severity,
        category,
        reproductionSteps,
        environment,
        reporter,
        logs,
        traces,
        metrics,
        codeContext
      } = req.body;

      const agentId = (req as Request & { agent?: { id?: string } }).agent?.id;

      // Create bug report
      const bugReport = BugInvestigationTeam.createBugReport({
        title,
        description,
        severity,
        category,
        reproductionSteps,
        environment,
        reporter: reporter || agentId || 'api'
      });

      // Create investigation context
      const context = BugInvestigationTeam.createContext({
        bugReport,
        logs,
        traces,
        metrics,
        codeContext
      });

      // Start investigation
      console.log(`[InvestigationController] Starting investigation for bug ${bugReport.id}`);
      const result = await this.investigationTeam.investigate(bugReport, context);

      // Save investigation to database
      await this.investigationService.saveInvestigation({
        investigationId: result.investigationId,
        bugReportId: bugReport.id,
        bugReport,
        context,
        result,
        createdAt: new Date(),
        status: 'completed'
      });

      res.status(200).json({
        success: true,
        data: {
          investigationId: result.investigationId,
          bugReportId: bugReport.id,
          result,
          status: 'completed'
        }
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to start investigation:', error);
      next(error);
    }
  };

  /**
   * Get investigation status
   */
  public getInvestigationStatus = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { investigationId } = req.params;

      const status = this.investigationTeam.getInvestigationStatus(investigationId);

      if (!status || status.status === 'not_found') {
        res.status(404).json({
          success: false,
          error: 'backend.investigation_not_found'
        });
        return;
      }

      res.status(200).json({
        success: true,
        data: status
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to get investigation status:', error);
      next(error);
    }
  };

  /**
   * Get investigation result
   */
  public getInvestigationResult = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { investigationId } = req.params;

      // Try to get from database first
      const savedResult = await this.investigationService.getInvestigation(investigationId);

      if (savedResult) {
        res.status(200).json({
          success: true,
          data: savedResult
        });
        return;
      }

      // If not in database, check active investigations
      const status = this.investigationTeam.getInvestigationStatus(investigationId);

      if (!status || status.status === 'not_found') {
        res.status(404).json({
          success: false,
          error: 'backend.investigation_not_found'
        });
        return;
      }

      if (status.status === 'in_progress') {
        res.status(202).json({
          success: true,
          data: {
            investigationId,
            status: 'in_progress',
            message: 'backend.investigation_still_in_progress'
          }
        });
        return;
      }

      res.status(404).json({
        success: false,
        error: 'backend.investigation_result_not_found'
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to get investigation result:', error);
      next(error);
    }
  };

  /**
   * Get active investigations
   */
  public getActiveInvestigations = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const investigations = this.investigationTeam.getActiveInvestigations();

      res.status(200).json({
        success: true,
        data: investigations,
        count: investigations.length
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to get active investigations:', error);
      next(error);
    }
  };

  /**
   * Get agent capabilities
   */
  public getCapabilities = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const capabilities = this.investigationTeam.getAgentCapabilities();

      res.status(200).json({
        success: true,
        data: capabilities
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to get capabilities:', error);
      next(error);
    }
  };

  /**
   * Cancel an investigation
   */
  public cancelInvestigation = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { investigationId } = req.params;

      // TODO: Implement cancellation logic in coordinator
      res.status(501).json({
        success: false,
        error: 'backend.investigation_cancellation_not_yet_implemented'
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to cancel investigation:', error);
      next(error);
    }
  };

  /**
   * Get investigation history
   */
  public getInvestigationHistory = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { limit = 50, offset = 0, severity, category } = req.query;

      const history = await this.investigationService.getInvestigationHistory({
        limit: Number(limit),
        offset: Number(offset),
        severity: severity as string,
        category: category as string
      });

      res.status(200).json({
        success: true,
        data: history.investigations,
        pagination: {
          total: history.total,
          limit: Number(limit),
          offset: Number(offset)
        }
      });
    } catch (error) {
      console.error('[InvestigationController] Failed to get investigation history:', error);
      next(error);
    }
  };
}

