      const latency = Date.now() - startTime;

      await aiEndpointStoreService.updateEndpoint(tenantId, endpoint.id, req.user?.userId || 'unknown', {
        lastTest: {
          success: false,
          latency,
          timestamp: new Date().toISOString()
