  const alert = await securityOperationsService.transitionAlertView(tenantOf(req), req.params.id, 'suppressed', req.user?.email || req.user?.userId || 'unknown');
  if (!alert) {
    return sendError(res, 404, {
      code: 'ALERT_NOT_FOUND',
      message: 'backend.alert_not_found'
    });
  }
  return sendSuccess(res, alert, {
    legacy: { alert }
  });
});

export default router;

import { Router, Request, Response } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { TrafficRequest } from '../../ai-agents';
import logger from '../../utils/logger';
import { isAttackSimulatorEnabled } from '../../config/app-mode';
import { getAgentSystem, getTrafficStats, getAgentGateway } from './ai-system.routes';
import { securityOperationsService } from '../../services/security-operations.service';
import { authenticate, AuthenticatedRequest } from '../../middleware/auth.middleware';
import { PLATFORM_API_CONFIG } from '../../utils/model-access';

const router = Router();
router.use(authenticate);

let attackHistory: any[] = [];

const requireAttackSimulatorEnabled = (res: Response): boolean => {
    if (isAttackSimulatorEnabled()) {
        return true;
    }
    res.status(404).json({ error: 'backend.not_found' });
    return false;
};

router.get('/types', (req: Request, res: Response) => {
