function sanitizePlatformConfig(config: any): any {
  if (!config) {
    return config;
  }

  return {
    ...config,
    edgeAuto: config.edgeAuto ? toPublicEdgeAutoPlatformSettings(config.edgeAuto) : config.edgeAuto,
  };
}

router.get('/', authenticate, async (req: AuthenticatedRequest, res) => {
