    isOnline: boolean;
    lastHeartbeat: Date;
    connectedAgents: string[];
    status?: {
        cpuUsage: number;
        memoryUsage: number;
        uptime: number;
        wifiRssi: number;
    };
    systemInfo?: {
        hostname: string;
        os: string;
        kernel: string;
        arch: string;
    };
    transport?: 'wifi' | 'usb_serial' | 'ethernet' | 'unknown';
    externalPowerPresent?: boolean;
    secureElementPresent?: boolean;
    pendingPhysicalApproval?: boolean;
    interlockState?: 'disabled' | 'armed' | 'asserted' | 'fault' | 'unknown';
    hostActionState?: 'idle' | 'running' | 'awaiting_confirmation' | 'completed' | 'failed' | 'unknown';
    physicalAuth?: {
        publicKeyPem?: string;
        monotonicCounter?: number;
        lastConfirmedAt?: string;
    };
}

interface DeviceConfig {
    displayName: string;
    group: string;
    site: string;
    networkProfile: string;
    scanProfile: string;
    notes: string;
    commandPermissions: string[];
    tags: string[];
    updatedAt: string;
}

interface DeviceCommandRecord {
    id: string;
    deviceId: string;
    command: string;
    status: 'queued' | 'completed' | 'failed';
    message: string;
    executedBy: string;
    createdAt: string;
    completedAt?: string;
    params?: Record<string, any>;
}

interface DeviceEvent {
    id: string;
    deviceId: string;
    type: 'register' | 'heartbeat' | 'data' | 'alert' | 'unknown_error' | 'disconnect' | 'command';
    payload: any;
    timestamp: string;
}

const devices = new Map<string, DeviceInfo>();
const deviceEvents = new Map<string, DeviceEvent[]>();
const deviceConfigs = new Map<string, DeviceConfig>();
const deviceCommands = new Map<string, DeviceCommandRecord[]>();
let deviceCommandTransport: ((deviceId: string, command: string, params?: Record<string, any>) => Promise<boolean> | boolean) | null = null;

const ALL_DEVICE_COMMANDS = [
    'collect',
    'sync-config',
    'ota_update',
    'host_backup',
    'host_install',
    'reboot',
    'host_remove',
    'recovery_flash',
    'factory_reset',
    'diagnostic_unlock',
    'vehicle_ota_flash',
    'cellular_breaker_assert',
    'cellular_breaker_release'
];

function resolveActorTenantId(req?: AuthenticatedRequest): string {
    if (!req) {
        return PLATFORM_TENANT_ID;
    }

    const context = resolveRequestTenantContext(req, {
        allowAdminPlatformFallback: req.user?.role === 'admin'
    });

    return context?.tenantId || req.user?.tenantId || PLATFORM_TENANT_ID;
}

function safeAuditLog(payload: any): void {
    Promise.resolve(auditLogger.log(payload)).catch((error: any) => {
        logger.warn('Device audit log unavailable', { error: error?.message });
    });
}

// Codebook
const codebook: Record<string, string> = {
    'E001': 'Connection refused',
    'E002': 'Permission denied',
    'E003': 'Out of memory',
    'E004': 'Disk full',
    'E005': 'Service unavailable',
    'S001': 'CPU usage critical (>90%)',
    'S002': 'Memory usage critical (>85%)',
    'S003': 'Disk usage critical (>90%)',
    'A001': 'SQL Injection detected',
    'A002': 'XSS attempt blocked',
    'A003': 'Path traversal attempt',
    'A004': 'Command injection detected',
    'A005': 'Brute force attack',
    'A006': 'DDoS pattern detected',
};

function buildDefaultConfig(device: DeviceInfo): DeviceConfig {
    return {
        displayName: device.deviceId,
        group: device.mode === 'online' ? 'core-edge' : 'field-edge',
        site: device.systemInfo?.hostname || 'unassigned-site',
        networkProfile: device.mode === 'online' ? 'cloud-mesh' : 'standalone-buffer',
        scanProfile: device.isOnline ? 'balanced' : 'offline-recovery',
        notes: `${device.chipModel} running firmware ${device.version}`,
        commandPermissions: [...ALL_DEVICE_COMMANDS],
        tags: [device.chipModel.toLowerCase(), device.mode, device.isOnline ? 'online' : 'offline'],
        updatedAt: new Date().toISOString()
    };
}

function normalizeCommandPermissions(input: unknown, fallback: string[]): string[] {
    if (!Array.isArray(input)) {
        return fallback;
    }

    const next = input
        .map((value) => String(value || '').trim())
        .filter((value, index, list) => value && ALL_DEVICE_COMMANDS.includes(value) && list.indexOf(value) === index);

    return next.length > 0 ? next : fallback;
}

function serializeDevice(device: DeviceInfo) {
    return {
        ...device,
        lastHeartbeat: device.lastHeartbeat.toISOString(),
        physicalAuth: {
            hasPublicKey: Boolean(device.physicalAuth?.publicKeyPem),
            monotonicCounter: device.physicalAuth?.monotonicCounter || 0,
            lastConfirmedAt: device.physicalAuth?.lastConfirmedAt || null
        }
    };
}

function ensureDeviceConfig(device: DeviceInfo): DeviceConfig {
    const existing = deviceConfigs.get(device.deviceId);
    if (existing) {
        return existing;
    }
    const next = buildDefaultConfig(device);
    deviceConfigs.set(device.deviceId, next);
    return next;
}

function getDeviceCommandHistory(deviceId: string, limit = 10): DeviceCommandRecord[] {
    return (deviceCommands.get(deviceId) || []).slice(0, limit);
}

function pushDeviceCommand(record: DeviceCommandRecord): void {
    const rows = deviceCommands.get(record.deviceId) || [];
    rows.unshift(record);
    if (rows.length > 50) {
        rows.length = 50;
    }
    deviceCommands.set(record.deviceId, rows);
}

function getLatestConfirmationSessionSafe(deviceId: string) {
    try {
        const { deviceControlService } = require('../../services/device-control.service');
        return deviceControlService?.getLatestConfirmationSession?.(deviceId) || null;
    } catch {
        return null;
    }
}

export function getDeviceById(deviceId: string): DeviceInfo | undefined {
    return devices.get(deviceId);
}

export function patchDeviceRuntime(deviceId: string, patch: Partial<DeviceInfo>): void {
    const device = devices.get(deviceId);
    if (!device) {
        return;
    }

    const next: DeviceInfo = {
        ...device,
        ...patch,
        systemInfo: patch.systemInfo ? { ...(device.systemInfo || {}), ...patch.systemInfo } : device.systemInfo,
        physicalAuth: patch.physicalAuth ? { ...(device.physicalAuth || {}), ...patch.physicalAuth } : device.physicalAuth
    };

    devices.set(deviceId, next);
}

export function setDeviceCommandTransport(
    transport: ((deviceId: string, command: string, params?: Record<string, any>) => Promise<boolean> | boolean) | null
): void {
    deviceCommandTransport = transport;
}

export async function executeDeviceCommandInternal(input: {
    deviceId: string;
    command: string;
    params?: Record<string, any>;
    actorId: string;
    actorEmail?: string;
    actorIp?: string;
    actionId?: string;
}): Promise<{ success: boolean; record?: DeviceCommandRecord; message: string; reason?: string }> {
    const device = devices.get(input.deviceId);
    if (!device) {
        return { success: false, message: 'Device not found.', reason: 'device_not_found' };
    }

    const config = ensureDeviceConfig(device);
    if (!config.commandPermissions.includes(input.command)) {
        return { success: false, message: `Command ${input.command} is not permitted for this device.`, reason: 'command_not_permitted' };
    }

    if (!device.isOnline) {
        return { success: false, message: 'Device is offline.', reason: 'device_offline' };
    }

    if (deviceCommandTransport) {
        const accepted = await Promise.resolve(deviceCommandTransport(input.deviceId, input.command, input.params || {}));
        if (!accepted) {
            return { success: false, message: `Device gateway rejected command ${input.command}.`, reason: 'device_gateway_rejected' };
        }
    }

    const now = new Date().toISOString();
    const commandMessages: Record<string, string> = {
        collect: `Telemetry collection completed on ${input.deviceId}`,
        'sync-config': `Configuration synchronized on ${input.deviceId}`,
        ota_update: `OTA workflow acknowledged on ${input.deviceId}`,
        host_backup: `Host backup requested on ${input.deviceId}`,
        host_install: `Host install workflow queued on ${input.deviceId}`,
        reboot: `Reboot command executed on ${input.deviceId}`,
        host_remove: `Host removal workflow queued on ${input.deviceId}`,
        recovery_flash: `Recovery flash workflow queued on ${input.deviceId}`,
        factory_reset: `Factory reset workflow queued on ${input.deviceId}`,
        diagnostic_unlock: `Diagnostic unlock workflow queued on ${input.deviceId}`,
        vehicle_ota_flash: `Vehicle OTA flash workflow queued on ${input.deviceId}`,
        cellular_breaker_assert: `Cellular breaker asserted on ${input.deviceId}`,
        cellular_breaker_release: `Cellular breaker released on ${input.deviceId}`
    };
    const record: DeviceCommandRecord = {
        id: input.actionId || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
        deviceId: input.deviceId,
        command: input.command,
        status: 'completed',
        message: commandMessages[input.command] || `Command "${input.command}" executed successfully on ${input.deviceId}`,
        executedBy: input.actorEmail || input.actorId || 'unknown',
        createdAt: now,
        completedAt: now,
        params: input.params || {}
    };

    pushDeviceCommand(record);
    addDeviceEvent(input.deviceId, 'command', {
        action: input.command,
        params: input.params || {},
        status: record.status,
        message: record.message,
        queuedBy: record.executedBy,
        actionId: input.actionId || null
    });

    if (input.command === 'collect') {
        device.lastHeartbeat = new Date();
        device.freeHeap = Math.max(64_000, device.freeHeap - 2_048);
    }

    if (input.command === 'reboot') {
        device.lastHeartbeat = new Date();
        device.status = device.status
            ? { ...device.status, uptime: 0, cpuUsage: Math.max(5, Math.round(device.status.cpuUsage * 0.6)) }
            : device.status;
        device.pendingPhysicalApproval = false;
        device.hostActionState = 'completed';
    }

    if (input.command === 'host_backup') {
        device.hostActionState = 'running';
    }

    if (['host_install', 'host_remove', 'recovery_flash', 'factory_reset'].includes(input.command)) {
        device.pendingPhysicalApproval = false;
        device.hostActionState = 'running';
    }

    if (['diagnostic_unlock', 'vehicle_ota_flash'].includes(input.command)) {
        device.pendingPhysicalApproval = false;
        device.hostActionState = 'running';
    }

    if (input.command === 'cellular_breaker_assert') {
        device.pendingPhysicalApproval = false;
        device.hostActionState = 'completed';
        device.interlockState = 'asserted';
    }

    if (input.command === 'cellular_breaker_release') {
        device.pendingPhysicalApproval = false;
        device.hostActionState = 'completed';
        device.interlockState = device.externalPowerPresent ? 'armed' : 'disabled';
    }

    devices.set(input.deviceId, device);
    try {
        const asset = ensureDeviceAsset(device);
        syncDeviceSignals(device, asset.assetId);
    } catch {
        // Ignore when operations database is unavailable.
    }

    logger.info('Command sent to device', {
        deviceId: input.deviceId,
        command: input.command,
        params: input.params || {},
        actionId: input.actionId || null
    });

    return {
        success: true,
        record,
        message: record.message
    };
}

