router.post('/tasks/:taskId/retry', async (req: AuthenticatedRequest, res: Response) => {
  const task = await getTaskForView(req.params.taskId);
  if (!task || task.tenantId !== tenantOf(req)) {
    return sendError(res, 404, {
      code: 'TASK_NOT_FOUND',
