    return sendSuccess(res, {
      taskId: retryTask.id,
      status: retryTask.status,
      createdAt: retryTask.createdAt
    }, {
      legacy: {
        taskId: retryTask.id,
        status: retryTask.status
      }
    });
  } catch (error: any) {
