      createdBy: req.user!.userId,
      enginePolicy: 'opt_then_nuclei',
      targets: {
        urls: validation.filteredUrls,
        host: {
          mode: 'local',
          includeSystem: true,
          includeWeb: true,
          includePorts: true
        }
