import 'dotenv/config';
import { spawn } from 'child_process';
import { createReadStream, createWriteStream, existsSync, readFileSync } from 'fs';
import { hostname } from 'os';
import { createInterface, Interface } from 'readline';
import { io, Socket } from 'socket.io-client';

type SerialFrame = Record<string, any>;
type HostActionName =
  | 'host_backup'
  | 'host_install'
  | 'host_remove'
  | 'recovery_flash'
  | 'factory_reset'
  | 'diagnostic_unlock'
  | 'vehicle_ota_flash';

type BoardState = {
  version: string;
  chipModel: string;
  flashSize: number;
  freeHeap: number;
  sdkVersion: string;
  cpuUsage: number;
  memoryUsage: number;
  uptime: number;
  transport: 'usb_serial';
  externalPowerPresent: boolean;
  secureElementPresent: boolean;
  pendingPhysicalApproval: boolean;
  interlockState: string;
  hostActionState: string;
  systemInfo: {
    hostname: string;
    os: string;
    kernel: string;
    arch: string;
  };
  physicalAuth?: {
    publicKeyPem?: string;
    monotonicCounter?: number;
  };
};

const CONTROL_PLANE_URL = process.env.DEVICE_COMPANION_CONTROL_PLANE_URL || process.env.DEVICE_SMOKE_BASE_URL || 'http://127.0.0.1:3005';
const DEVICE_GATEWAY_PATH = process.env.DEVICE_COMPANION_GATEWAY_PATH || '/ws/device';
const SERIAL_DEVICE = process.env.DEVICE_COMPANION_SERIAL_DEVICE || '/dev/ttyACM0';
const SERIAL_BAUD = String(process.env.DEVICE_COMPANION_SERIAL_BAUD || '115200');
const SERIAL_REOPEN_DELAY_MS = Number(process.env.DEVICE_COMPANION_SERIAL_REOPEN_DELAY_MS || 3000);
const HEARTBEAT_INTERVAL_MS = Number(process.env.DEVICE_COMPANION_HEARTBEAT_INTERVAL_MS || 5000);
const DEVICE_ID = process.env.DEVICE_COMPANION_DEVICE_ID || hostname();
const DEVICE_API_KEY = process.env.DEVICE_COMPANION_DEVICE_API_KEY || process.env.DEVICE_SMOKE_API_KEY || 'dev-device-key-2026';
const DEVICE_VERSION = process.env.DEVICE_COMPANION_DEVICE_VERSION || 'v1-companion';
const CHIP_MODEL = process.env.DEVICE_COMPANION_CHIP_MODEL || 'ESP32-S3-WROOM-1';
const SDK_VERSION = process.env.DEVICE_COMPANION_SDK_VERSION || 'aetherguard-companion';
const DEVICE_FLASH_SIZE = Number(process.env.DEVICE_COMPANION_FLASH_SIZE || 8 * 1024 * 1024);
const PUBLIC_KEY_FILE = process.env.DEVICE_COMPANION_PUBLIC_KEY_FILE || '';

const DEFAULT_BACKUP_CMD = process.env.AETHERGUARD_BACKUP_CMD || 'ts=$(date +%Y%m%d%H%M%S); backup_dir=/tmp/aetherguard_backup_$ts; mkdir -p "$backup_dir" && tar -czf "$backup_dir/etc_aetherguard.tgz" /etc/AetherGuard /etc/hosts 2>/dev/null';
const DEFAULT_INSTALL_CMD = process.env.AETHERGUARD_INSTALL_CMD || '';
const DEFAULT_REMOVE_CMD = process.env.AETHERGUARD_REMOVE_CMD || 'rm -rf /opt/AetherGuard';
const DEFAULT_RECOVERY_FLASH_CMD = process.env.AETHERGUARD_RECOVERY_FLASH_CMD || '';
const DEFAULT_FACTORY_RESET_CMD = process.env.AETHERGUARD_FACTORY_RESET_CMD || '';
const DEFAULT_DIAGNOSTIC_UNLOCK_CMD = process.env.AETHERGUARD_DIAGNOSTIC_UNLOCK_CMD || '';
const DEFAULT_VEHICLE_OTA_FLASH_CMD = process.env.AETHERGUARD_VEHICLE_OTA_FLASH_CMD || '';

let socket: Socket | null = null;
let serialReader: Interface | null = null;
let serialWriter: NodeJS.WritableStream | null = null;
let heartbeatTimer: NodeJS.Timeout | null = null;
let serialReconnectTimer: NodeJS.Timeout | null = null;
let isRegistered = false;

const boardState: BoardState = {
  version: DEVICE_VERSION,
  chipModel: CHIP_MODEL,
  flashSize: DEVICE_FLASH_SIZE,
  freeHeap: 196608,
  sdkVersion: SDK_VERSION,
  cpuUsage: 4,
  memoryUsage: 18,
  uptime: 0,
  transport: 'usb_serial',
  externalPowerPresent: false,
  secureElementPresent: Boolean(PUBLIC_KEY_FILE),
  pendingPhysicalApproval: false,
  interlockState: 'disabled',
  hostActionState: 'idle',
  systemInfo: {
    hostname: hostname(),
    os: 'linux',
    kernel: process.env.DEVICE_COMPANION_KERNEL || 'unknown',
    arch: process.arch
  },
  physicalAuth: PUBLIC_KEY_FILE && existsSync(PUBLIC_KEY_FILE)
    ? { publicKeyPem: readFileSync(PUBLIC_KEY_FILE, 'utf8') }
    : undefined
};

function log(message: string, details?: Record<string, any>): void {
  const suffix = details ? ` ${JSON.stringify(details)}` : '';
  process.stdout.write(`[device-companion] ${message}${suffix}\n`);
}

function configureSerialDevice(): Promise<void> {
  return new Promise((resolve, reject) => {
    const child = spawn('stty', [
      '-F',
      SERIAL_DEVICE,
      SERIAL_BAUD,
      'raw',
      '-echo',
      '-echoe',
      '-echok',
      '-echoctl',
      '-echoke',
      'cs8',
      '-cstopb',
      '-parenb',
      '-ixon',
      '-ixoff',
      '-crtscts'
    ], { stdio: 'ignore' });

    child.once('exit', (code) => {
      if (code === 0) {
        resolve();
        return;
      }
      reject(new Error(`stty exited with code ${code}`));
    });
    child.once('error', reject);
  });
}

function writeSerialFrame(frame: SerialFrame): void {
  if (!serialWriter) {
    return;
  }
  serialWriter.write(`${JSON.stringify(frame)}\n`);
}

function emitBoardSnapshot(): void {
  if (!socket?.connected) {
    return;
  }

  socket.emit('data', {
    timestamp: new Date().toISOString(),
    payload: {
      transport: boardState.transport,
      externalPowerPresent: boardState.externalPowerPresent,
      secureElementPresent: boardState.secureElementPresent,
      pendingPhysicalApproval: boardState.pendingPhysicalApproval,
      interlockState: boardState.interlockState,
      hostActionState: boardState.hostActionState,
      systemInfo: boardState.systemInfo,
      physicalAuth: boardState.physicalAuth,
      freeHeap: boardState.freeHeap
    }
  });
}

function sendRegister(): void {
  if (!socket?.connected || isRegistered) {
    return;
  }

  socket.emit('register', {
    device_id: DEVICE_ID,
    version: boardState.version,
    chip_model: boardState.chipModel,
    flash_size: boardState.flashSize,
    free_heap: boardState.freeHeap,
    sdk_version: boardState.sdkVersion,
    api_key: DEVICE_API_KEY
  });
}

function emitHeartbeat(): void {
  if (!socket?.connected || !isRegistered) {
    return;
  }

  boardState.uptime += Math.max(1, Math.floor(HEARTBEAT_INTERVAL_MS / 1000));
  socket.emit('heartbeat', {
    cpu_usage: boardState.cpuUsage,
    memory_usage: boardState.memoryUsage,
    uptime: boardState.uptime,
    wifi_rssi: 0,
    free_heap: boardState.freeHeap
  });
}

function ensureHeartbeat(): void {
  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
  }
  heartbeatTimer = setInterval(() => emitHeartbeat(), HEARTBEAT_INTERVAL_MS);
}

function getHostActionCommand(action: HostActionName): string {
  switch (action) {
    case 'host_backup':
      return DEFAULT_BACKUP_CMD;
    case 'host_install':
      return DEFAULT_INSTALL_CMD;
    case 'host_remove':
      return DEFAULT_REMOVE_CMD;
    case 'recovery_flash':
      return DEFAULT_RECOVERY_FLASH_CMD;
    case 'factory_reset':
      return DEFAULT_FACTORY_RESET_CMD;
    case 'diagnostic_unlock':
      return DEFAULT_DIAGNOSTIC_UNLOCK_CMD;
    case 'vehicle_ota_flash':
      return DEFAULT_VEHICLE_OTA_FLASH_CMD;
    default:
      return '';
  }
}

function runHostAction(action: HostActionName, params?: Record<string, any>): void {
  const command = getHostActionCommand(action);
  if (!command) {
    socket?.emit('alert', {
      alert_type: 'host_action_unconfigured',
      message: `${action} is not configured on this host`,
      timestamp: new Date().toISOString()
    });
    return;
  }

  boardState.hostActionState = 'running';
  emitBoardSnapshot();

  const child = spawn('bash', ['-lc', command], {
    env: {
      ...process.env,
      AETHERGUARD_ACTION: action,
      AETHERGUARD_ACTION_PARAMS: JSON.stringify(params || {})
    }
  });

  const output: string[] = [];
  child.stdout.on('data', (data) => output.push(String(data)));
  child.stderr.on('data', (data) => output.push(String(data)));
  child.once('exit', (code) => {
    const success = code === 0;
    boardState.hostActionState = success ? 'completed' : 'failed';
    emitBoardSnapshot();
    socket?.emit('data', {
      timestamp: new Date().toISOString(),
      payload: {
        hostActionState: boardState.hostActionState,
        lastHostAction: {
          action,
          success,
          output: output.join('').slice(-4000)
        }
      }
    });
  });
}

function handleSocketCommand(rawPayload: Record<string, any>): void {
  const command = rawPayload?.command && typeof rawPayload.command === 'object'
    ? rawPayload.command
    : rawPayload;
  const commandType = String(command?.cmd || rawPayload?.cmd || '').trim();
  const params = command?.params || rawPayload?.params || {};

  if (!commandType) {
    return;
  }

  if (commandType === 'physical_confirmation_required') {
    boardState.pendingPhysicalApproval = true;
    boardState.hostActionState = 'awaiting_confirmation';
    emitBoardSnapshot();
  }

  if (['host_backup', 'host_install', 'host_remove', 'recovery_flash', 'factory_reset', 'diagnostic_unlock', 'vehicle_ota_flash'].includes(commandType)) {
    runHostAction(commandType as HostActionName, params);
    return;
  }

  if (commandType === 'cellular_breaker_assert') {
    boardState.pendingPhysicalApproval = false;
    boardState.interlockState = 'asserted';
    boardState.hostActionState = 'completed';
    emitBoardSnapshot();
    socket?.emit('data', {
      timestamp: new Date().toISOString(),
      payload: {
        interlockState: boardState.interlockState,
        hostActionState: boardState.hostActionState,
        cellularBreaker: 'asserted'
      }
    });
    return;
  }

  if (commandType === 'cellular_breaker_release') {
    boardState.pendingPhysicalApproval = false;
    boardState.interlockState = boardState.externalPowerPresent ? 'armed' : 'disabled';
    boardState.hostActionState = 'completed';
    emitBoardSnapshot();
    socket?.emit('data', {
      timestamp: new Date().toISOString(),
      payload: {
        interlockState: boardState.interlockState,
        hostActionState: boardState.hostActionState,
        cellularBreaker: 'released'
      }
    });
    return;
  }

  writeSerialFrame({
    op: 'command',
    deviceId: DEVICE_ID,
    command: commandType,
    params,
    envelope: rawPayload
  });
}

function updateBoardState(input: Record<string, any>): void {
  const next = input.state && typeof input.state === 'object' ? input.state : input;
  boardState.version = String(next.version || boardState.version);
  boardState.chipModel = String(next.chipModel || next.chip_model || boardState.chipModel);
  boardState.flashSize = Number(next.flashSize || next.flash_size || boardState.flashSize);
  boardState.freeHeap = Number(next.freeHeap || next.free_heap || boardState.freeHeap);
  boardState.sdkVersion = String(next.sdkVersion || next.sdk_version || boardState.sdkVersion);
  boardState.externalPowerPresent = Boolean(next.externalPowerPresent ?? next.external_power_present ?? boardState.externalPowerPresent);
  boardState.secureElementPresent = Boolean(next.secureElementPresent ?? next.secure_element_present ?? boardState.secureElementPresent);
  boardState.pendingPhysicalApproval = Boolean(next.pendingPhysicalApproval ?? next.pending_physical_approval ?? boardState.pendingPhysicalApproval);
  boardState.interlockState = String(next.interlockState || next.interlock_state || boardState.interlockState);
  boardState.hostActionState = String(next.hostActionState || next.host_action_state || boardState.hostActionState);

  const publicKeyPem = next.publicKeyPem || next.public_key_pem || next?.physicalAuth?.publicKeyPem || next?.physicalAuth?.public_key_pem;
  const monotonicCounter = Number(next.monotonicCounter || next.monotonic_counter || next?.physicalAuth?.monotonicCounter || next?.physicalAuth?.monotonic_counter);
  if (publicKeyPem || Number.isFinite(monotonicCounter)) {
    boardState.physicalAuth = {
      ...(boardState.physicalAuth || {}),
      ...(publicKeyPem ? { publicKeyPem: String(publicKeyPem) } : {}),
      ...(Number.isFinite(monotonicCounter) ? { monotonicCounter } : {})
    };
  }
}

function handleSerialFrame(frame: SerialFrame): void {
  const op = String(frame?.op || '').trim();

  switch (op) {
    case 'hello':
    case 'state':
      updateBoardState(frame);
      emitBoardSnapshot();
      sendRegister();
      break;
    case 'heartbeat':
      updateBoardState(frame);
      boardState.cpuUsage = Number(frame.cpuUsage || frame.cpu_usage || boardState.cpuUsage);
      boardState.memoryUsage = Number(frame.memoryUsage || frame.memory_usage || boardState.memoryUsage);
      boardState.freeHeap = Number(frame.freeHeap || frame.free_heap || boardState.freeHeap);
      emitHeartbeat();
      emitBoardSnapshot();
      break;
    case 'telemetry':
      updateBoardState(frame);
      socket?.emit('data', {
        timestamp: frame.timestamp || new Date().toISOString(),
        payload: {
          ...frame.payload,
          transport: 'usb_serial',
          externalPowerPresent: boardState.externalPowerPresent,
          secureElementPresent: boardState.secureElementPresent,
          pendingPhysicalApproval: boardState.pendingPhysicalApproval,
          interlockState: boardState.interlockState,
          hostActionState: boardState.hostActionState,
          systemInfo: boardState.systemInfo,
          physicalAuth: boardState.physicalAuth
        }
      });
      break;
    case 'alert':
      socket?.emit('alert', {
        alert_type: frame.alert_type || frame.alertType || 'board_alert',
        message: frame.message || 'Board alert',
        timestamp: frame.timestamp || new Date().toISOString()
      });
      break;
    case 'ota_status':
      socket?.emit('ota_status', {
        ...frame,
        timestamp: frame.timestamp || new Date().toISOString()
      });
      break;
    case 'physical_confirmation_ack':
      boardState.pendingPhysicalApproval = false;
      boardState.hostActionState = Boolean(frame.confirmed) ? 'running' : 'failed';
      updateBoardState(frame);
      emitBoardSnapshot();
      socket?.emit('physical_confirmation_ack', {
        ...frame,
        confirmationSessionId: frame.confirmationSessionId,
        timestamp: frame.timestamp || Date.now()
      });
      break;
    default:
      log('ignored serial frame', { op });
      break;
  }
}

function scheduleSerialReconnect(): void {
  if (serialReconnectTimer) {
    return;
  }
  serialReconnectTimer = setTimeout(() => {
    serialReconnectTimer = null;
    void openSerial();
  }, SERIAL_REOPEN_DELAY_MS);
}

async function openSerial(): Promise<void> {
  if (!existsSync(SERIAL_DEVICE)) {
    log('serial device not present', { serialDevice: SERIAL_DEVICE });
    scheduleSerialReconnect();
    return;
  }

  try {
    await configureSerialDevice();
  } catch (error: any) {
    log('failed to configure serial device', { message: error?.message || String(error) });
    scheduleSerialReconnect();
    return;
  }

  const readStream = createReadStream(SERIAL_DEVICE, { flags: 'r+' });
  const writeStream = createWriteStream(SERIAL_DEVICE, { flags: 'r+' });
  serialWriter = writeStream;
  serialReader = createInterface({ input: readStream, crlfDelay: Infinity });

  serialReader.on('line', (line) => {
    const trimmed = line.trim();
    if (!trimmed) {
      return;
    }
    try {
      handleSerialFrame(JSON.parse(trimmed));
    } catch (error: any) {
      log('failed to parse serial frame', { line: trimmed, message: error?.message || String(error) });
    }
  });

  readStream.on('error', () => scheduleSerialReconnect());
  writeStream.on('error', () => scheduleSerialReconnect());
  readStream.on('close', () => scheduleSerialReconnect());

  writeSerialFrame({
    op: 'hello',
    deviceId: DEVICE_ID,
    request: 'state'
  });
  log('serial link opened', { serialDevice: SERIAL_DEVICE, serialBaud: SERIAL_BAUD });
}

function connectSocket(): void {
  socket = io(CONTROL_PLANE_URL, {
    path: DEVICE_GATEWAY_PATH,
    transports: ['websocket'],
    reconnection: true,
    reconnectionDelay: 2000,
    reconnectionDelayMax: 8000
  });

  socket.on('connect', () => {
    isRegistered = false;
    sendRegister();
    emitBoardSnapshot();
    log('connected to control plane', { url: CONTROL_PLANE_URL, path: DEVICE_GATEWAY_PATH });
  });

  socket.on('register_success', () => {
    isRegistered = true;
    emitBoardSnapshot();
    emitHeartbeat();
  });

  socket.on('register_error', (payload) => {
    log('registration failed', payload);
  });

  socket.on('command', (payload) => handleSocketCommand(payload));
  socket.on('disconnect', (reason) => {
    isRegistered = false;
    log('control plane disconnected', { reason });
  });
  socket.on('connect_error', (error) => {
    log('control plane connection error', { message: error.message });
  });
}

async function main(): Promise<void> {
  connectSocket();
  ensureHeartbeat();
  await openSerial();
}

process.on('SIGINT', () => process.exit(0));
process.on('SIGTERM', () => process.exit(0));

void main();

import path from 'path';
import fs from 'fs';
import logger from '../utils/logger';

// Type for sql.js database
interface SqlJsDatabase {
  run(sql: string, params?: any[]): void;
  exec(sql: string): void;
  prepare(sql: string): any;
  export(): Uint8Array;
  close(): void;
}

// Type for better-sqlite3 database
type BetterSqliteDatabase = any;

let SqlJs: any = null;
let useSqlJs = false;

/**
 * Database Manager
 * Handles SQLite database operations using sql.js (fallback) or better-sqlite3
 */
export class DatabaseManager {
  private db: BetterSqliteDatabase | SqlJsDatabase | null = null;
  private dbPath: string;
  private saveInterval: NodeJS.Timeout | null = null;

  constructor() {
    const dataDir = process.env.DATA_DIR || path.join(process.cwd(), 'data');
    this.dbPath = path.join(dataDir, 'newsecurity.db');
    this.ensureDataDir(dataDir);
  }

  /**
   * Initialize database - tries sql.js first, falls back to better-sqlite3
   */
  public async initAsync(): Promise<void> {
    // Try sql.js first
    try {
      SqlJs = require('sql.js');
      const initSqlJs = SqlJs;
      const SQL = await initSqlJs();

      // Load existing database or create new one
      let data: Buffer | undefined;
      if (fs.existsSync(this.dbPath)) {
        data = fs.readFileSync(this.dbPath);
      }

      this.db = new SQL.Database(data);
      useSqlJs = true;

      logger.info(`Database opened with sql.js: ${this.dbPath}`);

      // Save to disk every 30 seconds for persistence
      this.saveInterval = setInterval(() => {
        this.save();
      }, 30000);
      if (typeof this.saveInterval.unref === 'function') {
        this.saveInterval.unref();
      }

      this.initSchema();
      return;
    } catch (sqlJsError: any) {
      logger.warn('sql.js not available, trying better-sqlite3', { error: sqlJsError.message });
    }

    // Fall back to better-sqlite3
    try {
      const Database = require('better-sqlite3');
      this.db = new Database(this.dbPath);
      (this.db as BetterSqliteDatabase).pragma('journal_mode = WAL');
      (this.db as BetterSqliteDatabase).pragma('foreign_keys = ON');
      useSqlJs = false;

      logger.info(`Database opened with better-sqlite3: ${this.dbPath} (WAL mode enabled)`);

      this.initSchema();
    } catch (betterError: any) {
      logger.error('Failed to initialize database', { error: betterError.message });
      throw betterError;
    }
  }

  /**
   * Synchronous init for backward compatibility (tries sql.js)
   */
  public init(): void {
    // This is now async - but we need to call initAsync synchronously for compatibility
    // The actual initialization happens in the async version
    // For now, we'll handle this in the initDatabase function
  }

  /**
   * Ensure data directory exists
   */
  private ensureDataDir(dir: string): void {
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
      logger.info(`Created data directory: ${dir}`);
    }
  }

  /**
   * Initialize database schema
   */
  private initSchema(): void {
    if (!this.db) {
      throw new Error('Database not connected');
    }

    try {
      // Sites table
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS sites (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          domain TEXT UNIQUE NOT NULL,
          target TEXT NOT NULL,
          sslEnabled INTEGER DEFAULT 1,
          antiBotEnabled INTEGER DEFAULT 1,
          rateLimitEnabled INTEGER DEFAULT 1,
          rateLimitRequests INTEGER DEFAULT 60,
          concurrencyEnabled INTEGER DEFAULT 1,
          concurrencyMax INTEGER DEFAULT 5,
          tenant_id TEXT,
          createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
          updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Security rules table
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS security_rules (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          siteId INTEGER NOT NULL,
          ruleType TEXT NOT NULL,
          config TEXT NOT NULL,
          enabled INTEGER DEFAULT 1,
          createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (siteId) REFERENCES sites(id) ON DELETE CASCADE
        )
      `);

      // Scan results table
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS scan_results (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          siteId INTEGER,
          scanType TEXT NOT NULL,
          result TEXT NOT NULL,
          recommendations TEXT,
          status TEXT DEFAULT 'pending',
          createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (siteId) REFERENCES sites(id) ON DELETE CASCADE
        )
      `);

      // Backups table
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS backups (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          name TEXT NOT NULL,
          description TEXT,
          data TEXT NOT NULL,
          size INTEGER,
          isAutomatic INTEGER DEFAULT 0,
          createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Monitoring data table (time-series)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS metrics (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          siteId INTEGER NOT NULL,
          metricType TEXT NOT NULL,
          value REAL NOT NULL,
          metadata TEXT,
          timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (siteId) REFERENCES sites(id) ON DELETE CASCADE
        )
      `);

      // Agents table
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS agents (
          id TEXT PRIMARY KEY,
          hostname TEXT NOT NULL,
          platform TEXT,
          arch TEXT,
          version TEXT,
          lastHeartbeat DATETIME,
          status TEXT DEFAULT 'offline',
          createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Users table (for authentication)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS users (
          id TEXT PRIMARY KEY,
          email TEXT UNIQUE NOT NULL,
          username TEXT NOT NULL,
          password_hash TEXT NOT NULL,
          role TEXT DEFAULT 'viewer' CHECK(role IN ('admin', 'tenant', 'viewer')),
          plan TEXT DEFAULT 'starter' CHECK(plan IN ('starter', 'pro', 'ultra')),
          tenant_id TEXT,
          status TEXT DEFAULT 'active' CHECK(status IN ('active', 'suspended', 'pending')),
          last_login DATETIME,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Auto-migrate: add 'plan' column to existing 'users' table if it doesn't have one
      try {
        this.db.exec(`ALTER TABLE users ADD COLUMN plan TEXT DEFAULT 'starter' CHECK(plan IN ('starter', 'pro', 'ultra'))`);
        logger.info('Database migration applied: added plan column to users');
      } catch (e: any) {
        // We expect an error if the column already exists
        if (!(e.message && e.message.includes('duplicate column name'))) {
          logger.warn('Error during database soft migration', { error: e.message });
        }
      }

      // Auto-migrate: add 'tenant_id' column to existing 'sites' table if it doesn't have one
      try {
        this.db.exec(`ALTER TABLE sites ADD COLUMN tenant_id TEXT`);
        logger.info('Database migration applied: added tenant_id column to sites');
      } catch (e: any) {
        if (!(e.message && e.message.includes('duplicate column name'))) {
          logger.warn('Error during database soft migration', { error: e.message });
        }
      }

      // API Keys table (for agent/device authentication)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS api_keys (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          key_hash TEXT UNIQUE NOT NULL,
          user_id TEXT,
          tenant_id TEXT,
          permissions TEXT DEFAULT '["read"]',
          last_used DATETIME,
          expires_at DATETIME,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        )
      `);

      // Devices table (for ESP32 dongles)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS devices (
          id TEXT PRIMARY KEY,
          device_type TEXT DEFAULT 'esp32',
          mac_address TEXT UNIQUE,
          firmware_version TEXT,
          status TEXT DEFAULT 'offline',
          last_seen DATETIME,
          config TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Alerts table (for security alerts)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS alerts (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          type TEXT NOT NULL,
          severity TEXT DEFAULT 'info' CHECK(severity IN ('info', 'warning', 'critical')),
          source TEXT,
          message TEXT NOT NULL,
          details TEXT,
          acknowledged INTEGER DEFAULT 0,
          acknowledged_by TEXT,
          acknowledged_at DATETIME,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Agent registrations table (for probe agent authentication)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS agent_registrations (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          agent_id TEXT NOT NULL UNIQUE,
          hostname TEXT NOT NULL,
          api_key_hash TEXT NOT NULL,
          secret_key TEXT NOT NULL,
          fingerprint TEXT,
          platform TEXT,
          status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'revoked')),
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          last_seen_at DATETIME
        )
      `);

      try {
        this.db.exec(`ALTER TABLE agent_registrations ADD COLUMN tenant_id TEXT`);
        logger.info('Database migration applied: added tenant_id column to agent_registrations');
      } catch (e: any) {
        if (!(e.message && e.message.includes('duplicate column name'))) {
          logger.warn('Error during database soft migration', { error: e.message });
        }
      }

      try {
        this.db.exec(`UPDATE agent_registrations SET tenant_id = 'platform' WHERE tenant_id IS NULL OR tenant_id = ''`);
      } catch (e: any) {
        logger.warn('Error during database tenant backfill for agent_registrations', { error: e.message });
      }

      // System configuration table (for seed version, settings, etc.)
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS system_config (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `);

      // Create indexes
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_sites_domain ON sites(domain)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_scan_results_siteId ON scan_results(siteId)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_metrics_siteId ON metrics(siteId)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_metrics_timestamp ON metrics(timestamp)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_users_email ON users(email)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_users_tenant ON users(tenant_id)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_api_keys_user ON api_keys(user_id)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_alerts_severity ON alerts(severity)`);
      this.db.exec(`CREATE INDEX IF NOT EXISTS idx_alerts_created ON alerts(created_at)`);

      logger.info('Database schema initialized');
    } catch (error: any) {
      logger.error('Failed to initialize database schema', { error: error.message });
      throw error;
    }
  }

  /**
   * Get database instance with sql.js compatible API
   * Returns a wrapped database that supports run(), step(), getAsObject(), free()
   */
  public getDb(): any {
    if (!this.db) {
      throw new Error('Database not connected');
    }

    const db = this.db;
    const isSqlJs = useSqlJs;

    // Return a wrapped database with sql.js-compatible API
    return {
      // Direct database operations
      exec: (sql: string) => db.exec(sql),
      run: (sql: string, params?: any[]) => {
        if (params && params.length > 0) {
          if (isSqlJs) {
            db.run(sql, params);
          } else {
            db.prepare(sql).run(...params);
          }
        } else {
          db.exec(sql);
        }
      },

      // Statement creation with sql.js-compatible API
      prepare: (sql: string) => {
        const stmt = db.prepare(sql);
        let boundParams: any[] = [];
        let hasStepped = false;
        let cachedRow: any = null;

        return {
          // Bind parameters
          bind: (params: any[]) => {
            boundParams = params;
            hasStepped = false;
            cachedRow = null;
          },

          // Step through results (simulated for better-sqlite3)
          step: () => {
            if (!hasStepped) {
              if (isSqlJs) {
                stmt.bind(boundParams);
                hasStepped = stmt.step();
                if (hasStepped) {
                  cachedRow = stmt.getAsObject();
                }
              } else {
                cachedRow = stmt.get(...boundParams);
                hasStepped = true;
              }
            }
            return cachedRow !== undefined && cachedRow !== null;
          },

          // Get current row as object
          getAsObject: () => {
            if (cachedRow === null || cachedRow === undefined) {
              if (isSqlJs) {
                stmt.bind(boundParams);
                stmt.step();
                cachedRow = stmt.getAsObject();
              } else {
                cachedRow = stmt.get(...boundParams);
              }
            }
            // Convert array to object using column names if available
            if (!isSqlJs && Array.isArray(cachedRow)) {
              const columns = stmt.columns ? stmt.columns() : [];
              if (columns.length > 0) {
                const obj: any = {};
                columns.forEach((col: any, i: number) => {
                  obj[col.name] = cachedRow[i];
                });
                return obj;
              }
            }
            return cachedRow;
          },

          // Free statement
          free: () => {
            if (isSqlJs) {
              stmt.free();
            }
          },

          // Also provide direct run/all/get for convenience
          run: (...params: any[]) => {
            if (isSqlJs) {
              stmt.bind(params);
              stmt.step();
              stmt.free();
            } else {
              stmt.run(...params);
            }
          },
          all: (...params: any[]) => {
            if (isSqlJs) {
              const results: any[] = [];
              stmt.bind(params);
              while (stmt.step()) {
                results.push(stmt.getAsObject());
              }
              stmt.free();
              return results;
            } else {
              return stmt.all(...params);
            }
          },
          get: (...params: any[]) => {
            if (isSqlJs) {
              stmt.bind(params);
              if (stmt.step()) {
                const result = stmt.getAsObject();
                stmt.free();
                return result;
              }
              stmt.free();
              return undefined;
            } else {
              return stmt.get(...params);
            }
          }
        };
      }
    };
  }

  /**
   * Execute SQL with parameters (sql.js compatible API)
   */
  public run(sql: string, params?: any[]): void {
    if (!this.db) throw new Error('Database not connected');
    if (params && params.length > 0) {
      if (useSqlJs) {
        this.db.run(sql, params);
      } else {
        this.db.prepare(sql).run(...params);
      }
    } else {
      this.db.exec(sql);
    }
  }

  /**
   * Execute SQL (for DDL statements)
   */
  public exec(sql: string, params?: any[]): void {
    if (!this.db) throw new Error('Database not connected');
    if (params && params.length > 0) {
      if (useSqlJs) {
        this.db.run(sql, params);
      } else {
        this.db.prepare(sql).run(...params);
      }
    } else {
      this.db.exec(sql);
    }
  }

  /**
   * Prepare and run a statement (compatible API with sql.js)
   */
  public prepare(sql: string): {
    run: (...params: any[]) => void;
    all: (...params: any[]) => any[];
    get: (...params: any[]) => any;
    free: () => void;
    bind: (params: any[]) => void;
    step: () => boolean;
    getAsObject: () => any;
  } {
    if (!this.db) throw new Error('Database not connected');

    const stmt = this.db.prepare(sql);
    let boundParams: any[] = [];
    let hasStepped = false;
    let cachedRow: any = null;

    return {
      run: (...params: any[]) => {
        if (useSqlJs) {
          stmt.bind(params);
          stmt.step();
          stmt.free();
        } else {
          stmt.run(...params);
        }
      },
      all: (...params: any[]) => {
        if (useSqlJs) {
          const results: any[] = [];
          stmt.bind(params);
          while (stmt.step()) {
            results.push(stmt.getAsObject());
          }
          stmt.free();
          return results;
        } else {
          return stmt.all(...params);
        }
      },
      get: (...params: any[]) => {
        if (useSqlJs) {
          stmt.bind(params);
          if (stmt.step()) {
            const result = stmt.getAsObject();
            stmt.free();
            return result;
          }
          stmt.free();
          return undefined;
        } else {
          return stmt.get(...params);
        }
      },
      free: () => {
        if (useSqlJs) {
          stmt.free();
        }
      },
      bind: (params: any[]) => {
        boundParams = params;
        hasStepped = false;
        cachedRow = null;
      },
      step: () => {
        if (useSqlJs) {
          if (!hasStepped) {
            stmt.bind(boundParams);
            hasStepped = stmt.step();
            if (hasStepped) {
              cachedRow = stmt.getAsObject();
            }
          }
          return hasStepped;
        } else {
          // better-sqlite3 doesn't need step() - just get the row
          if (!hasStepped) {
            cachedRow = stmt.get(...boundParams);
            hasStepped = true;
          }
          return cachedRow !== undefined && cachedRow !== null;
        }
      },
      getAsObject: () => {
        if (useSqlJs) {
          // Return the cached row or get a new one
          if (cachedRow === null || cachedRow === undefined) {
            stmt.bind(boundParams);
            stmt.step();
            cachedRow = stmt.getAsObject();
          }
          return cachedRow;
        } else {
          // Return the cached row or get a new one
          if (cachedRow === null || cachedRow === undefined) {
            cachedRow = stmt.get(...boundParams);
          }
          // Convert array to object if needed
          if (Array.isArray(cachedRow)) {
            // For SELECT * queries, we need column names
            // This is a simplification - the actual usage may vary
            return cachedRow;
          }
        }
        return cachedRow;
      }
    };
  }

  /**
   * Run a transaction
   */
  public transaction<T>(fn: () => T): T {
    if (!this.db) throw new Error('Database not connected');
    if (useSqlJs) {
      this.exec('BEGIN');
      try {
        const result = fn();
        this.exec('COMMIT');
        return result;
      } catch (error) {
        try {
          this.exec('ROLLBACK');
        } catch {
          // Ignore rollback failure and rethrow original error
        }
        throw error;
      }
    }
    return (this.db as BetterSqliteDatabase).transaction(fn)();
  }

  /**
   * Save database to disk
   */
  public save(): void {
    if (!this.db) return;

    try {
      if (useSqlJs) {
        // sql.js: Export to buffer and write to file
        const data = (this.db as SqlJsDatabase).export();
        const buffer = Buffer.from(data);
        fs.writeFileSync(this.dbPath, buffer);
        logger.debug('Database saved to disk (sql.js)');
      } else {
        // better-sqlite3: Checkpoint to ensure data is written to main database
        (this.db as BetterSqliteDatabase).pragma('wal_checkpoint(TRUNCATE)');
      }
    } catch (error: any) {
      logger.error('Failed to save database', { error: error.message });
    }
  }

  /**
   * Backup database to specified path
   */
  public backup(backupPath: string): void {
    if (!this.db) throw new Error('Database not connected');
    if (useSqlJs) {
      const data = (this.db as SqlJsDatabase).export();
      fs.writeFileSync(backupPath, Buffer.from(data));
    } else {
      (this.db as BetterSqliteDatabase).backup(backupPath);
    }
    logger.info(`Database backed up to: ${backupPath}`);
  }

  /**
   * Close database connection
   */
  public close(): void {
    if (this.db) {
      if (this.saveInterval) {
        clearInterval(this.saveInterval);
        this.saveInterval = null;
      }

      if (useSqlJs) {
        this.save();
        (this.db as SqlJsDatabase).close();
      } else {
        // Close WAL before closing
        (this.db as BetterSqliteDatabase).pragma('wal_checkpoint(TRUNCATE)');
        (this.db as BetterSqliteDatabase).close();
      }
      this.db = null;
      logger.info('Database connection closed');
    }
  }
}

// Singleton instance
let dbManager: DatabaseManager | null = null;

export async function initDatabase(): Promise<DatabaseManager> {
  if (dbManager) return dbManager;

  dbManager = new DatabaseManager();
  await dbManager.initAsync();
  return dbManager;
}

export function getDatabase(): DatabaseManager {
  if (!dbManager) {
    throw new Error('Database not initialized. Call initDatabase() first.');
  }
  return dbManager;
}

export function closeDatabase(): void {
  if (dbManager) {
    dbManager.close();
    dbManager = null;
  }
}

import { PLATFORM_API_CONFIG } from '../../utils/model-access';
import { RuntimeProfile } from '../../config/platform-runtime';
import { artifactStoreService } from '../../services/artifact-store.service';
import { fastpathClientService } from '../../services/fastpath-client.service';
import { jobQueueService } from '../../services/job-queue.service';
import { postgresShadowStoreService } from '../../services/postgres-shadow-store.service';
import { runtimeEmulatorService } from '../../services/runtime-emulator.service';
import redisService from '../../security/redis.service';

export type DependencyStatus = 'healthy' | 'degraded' | 'unhealthy' | 'disabled';

export interface DependencyHealth {
  status: DependencyStatus;
  message: string;
  details?: Record<string, any>;
}

export interface RuntimeHealthSnapshot {
  status: 'healthy' | 'degraded' | 'unhealthy';
  liveness: {
    status: 'alive';
    timestamp: string;
  };
  readiness: {
    status: 'ready' | 'not_ready';
    blockers: string[];
  };
  dependencies: {
    redis: DependencyHealth;
    postgres: DependencyHealth;
    artifactStore: DependencyHealth;
    fastpath: DependencyHealth;
    aiProvider: DependencyHealth;
  };
  runtime: Record<string, any>;
  queueBackend: 'redis' | 'memory';
  agents: number;
  emulator: Record<string, any>;
}

function getAiProviderHealth(profile: RuntimeProfile): DependencyHealth {
  const configuredKey = String(process.env.PLATFORM_API_KEY || '').trim();
  if (!configuredKey) {
    return {
      status: profile === 'prod' ? 'degraded' : 'disabled',
      message: profile === 'prod'
        ? 'Cloud AI provider is not configured.'
        : 'Cloud AI provider is disabled outside production.',
      details: {
        provider: PLATFORM_API_CONFIG.providerId,
        protocol: PLATFORM_API_CONFIG.protocol,
        baseURL: PLATFORM_API_CONFIG.baseURL
      }
    };
  }

  return {
    status: 'healthy',
    message: 'Cloud AI provider configuration is present.',
    details: {
      provider: PLATFORM_API_CONFIG.providerId,
      protocol: PLATFORM_API_CONFIG.protocol,
      baseURL: PLATFORM_API_CONFIG.baseURL
    }
  };
}

export async function buildRuntimeHealthSnapshot(input: {
  runtime: Record<string, any> & { profile: RuntimeProfile; dbMode: string; sqliteFallbackEnabled: boolean; };
  agentCount: number;
}): Promise<RuntimeHealthSnapshot> {
  const timestamp = new Date().toISOString();
  const shadow = postgresShadowStoreService.describe();
  const artifactStore = artifactStoreService.describe();
  const emulator = runtimeEmulatorService.describe();
  const redis = await redisService.healthCheck();
  const fastpathHealthy = await fastpathClientService.health('global').catch(() => false);
  const blockers: string[] = [];

  const dependencies = {
    redis: redis.healthy
      ? {
          status: 'healthy' as const,
          message: 'Redis is connected.',
          details: { latencyMs: redis.latency ?? null }
        }
      : {
          status: redisService.isDisabled() ? 'disabled' as const : 'degraded' as const,
          message: redis.error || 'Redis is unavailable.',
          details: { disabled: redisService.isDisabled() }
        },
    postgres: shadow.enabled
      ? shadow.connected
        ? {
            status: 'healthy' as const,
            message: 'Postgres shadow store is connected.',
            details: shadow
          }
        : {
            status: 'unhealthy' as const,
            message: shadow.lastError || 'Postgres shadow store is unavailable.',
            details: shadow
          }
      : {
          status: 'disabled' as const,
          message: 'Postgres shadow store is disabled.',
          details: shadow
        },
    artifactStore: artifactStore.requestedMode === artifactStore.activeMode
      ? {
          status: 'healthy' as const,
          message: `Artifact store is using ${artifactStore.activeMode}.`,
          details: artifactStore
        }
      : {
          status: 'degraded' as const,
          message: `Artifact store fell back to ${artifactStore.activeMode}.`,
          details: artifactStore
        },
    fastpath: fastpathHealthy
      ? {
          status: 'healthy' as const,
          message: 'Fastpath is reachable.'
        }
      : {
          status: input.runtime.profile === 'prod' ? 'degraded' as const : 'disabled' as const,
          message: input.runtime.profile === 'prod'
            ? 'Fastpath is unavailable; fallback path will be used.'
            : 'Fastpath is disabled or unavailable in the current profile.'
        },
    aiProvider: getAiProviderHealth(input.runtime.profile)
  };

  if (input.runtime.dbMode === 'postgres' && dependencies.postgres.status !== 'healthy') {
    blockers.push('postgres');
  }

  const readiness = {
    status: blockers.length === 0 ? 'ready' as const : 'not_ready' as const,
    blockers
  };

  const degradedDependencies = Object.values(dependencies).filter((dependency) =>
    dependency.status === 'degraded' || dependency.status === 'unhealthy'
  );

  return {
    status: readiness.status === 'not_ready'
      ? 'unhealthy'
      : degradedDependencies.length > 0
        ? 'degraded'
        : 'healthy',
    liveness: {
      status: 'alive',
      timestamp
    },
    readiness,
    dependencies,
    runtime: {
      ...input.runtime,
      dbPrimaryMode: input.runtime.dbMode,
      sqliteFallbackEnabled: input.runtime.sqliteFallbackEnabled,
      shadowStore: shadow
    },
    queueBackend: jobQueueService.backend(),
    agents: input.agentCount,
    emulator
  };
}

import { Response } from 'express';

export interface ApiSuccessEnvelope<T> {
  success: true;
  data: T;
  error: null;
  meta?: Record<string, any>;
}

export interface ApiErrorDetails {
  code: string;
  message: string;
  details?: unknown;
}

export interface ApiErrorEnvelope {
  success: false;
  data: null;
  error: ApiErrorDetails;
  meta?: Record<string, any>;
}

interface ResponseOptions {
  meta?: Record<string, any>;
  legacy?: Record<string, any>;
}

export function sendSuccess<T>(
  res: Response,
  data: T,
  options: ResponseOptions = {},
  statusCode = 200
): Response<ApiSuccessEnvelope<T>> {
  const body: Record<string, any> = {
    success: true,
    data,
    error: null
  };

  if (options.meta) {
    body.meta = options.meta;
  }

  if (options.legacy) {
    Object.assign(body, options.legacy);
  }

  return res.status(statusCode).json(body);
}

export function sendError(
  res: Response,
  statusCode: number,
  error: ApiErrorDetails,
  options: ResponseOptions = {}
): Response<ApiErrorEnvelope> {
  const body: Record<string, any> = {
    success: false,
    data: null,
    error,
    code: error.code,
    message: error.message
  };

  if (options.meta) {
    body.meta = options.meta;
  }

  if (options.legacy) {
    Object.assign(body, options.legacy);
  }

  return res.status(statusCode).json(body);
}

import type { AuthenticatedRequest, AuthenticatedUser } from '../../middleware/auth.middleware';

export const PLATFORM_TENANT_ID = 'platform';

export type TenantSource =
  | 'user'
  | 'request'
  | 'agent'
  | 'device'
  | 'platform';

export interface TenantContext {
  tenantId: string;
  source: TenantSource;
  reason?: string;
}

function readRequestedTenantId(req: AuthenticatedRequest): string | undefined {
  const rawValue =
    req.params?.tenantId ||
    req.query?.tenantId ||
    req.body?.tenantId;

  if (typeof rawValue !== 'string') {
    return undefined;
  }

  const normalized = rawValue.trim();
  return normalized || undefined;
}

export function normalizeTenantId(value?: string | null): string | undefined {
  if (typeof value !== 'string') {
    return undefined;
  }

  const normalized = value.trim();
  return normalized || undefined;
}

export function buildPlatformTenantContext(reason: string): TenantContext {
  return {
    tenantId: PLATFORM_TENANT_ID,
    source: 'platform',
    reason
  };
}

export function resolveUserTenantContext(
  user: AuthenticatedUser | undefined,
  options: {
    requestedTenantId?: string;
    allowAdminPlatformFallback?: boolean;
  } = {}
): TenantContext | null {
  if (!user) {
    return null;
  }

  const requestedTenantId = normalizeTenantId(options.requestedTenantId);
  if (requestedTenantId) {
    return {
      tenantId: requestedTenantId,
      source: 'request'
    };
  }

  const userTenantId = normalizeTenantId(user.tenantId);
  if (userTenantId) {
    return {
      tenantId: userTenantId,
      source: 'user'
    };
  }

  if (user.role === 'admin' && options.allowAdminPlatformFallback) {
    return buildPlatformTenantContext('admin-platform-fallback');
  }

  return null;
}

export function resolveRequestTenantContext(
  req: AuthenticatedRequest,
  options: {
    allowAdminPlatformFallback?: boolean;
  } = {}
): TenantContext | null {
  if (req.tenantContext) {
    return req.tenantContext;
  }

  const context = resolveUserTenantContext(req.user, {
    requestedTenantId: readRequestedTenantId(req),
    allowAdminPlatformFallback: options.allowAdminPlatformFallback
  });

  if (context) {
    req.tenantContext = context;
  }

  return context;
}

export function resolveAgentTenantContext(
  tenantId: string | undefined,
  reason = 'agent-connection'
): TenantContext | null {
  const normalized = normalizeTenantId(tenantId);
  if (!normalized) {
    return null;
  }

  return {
    tenantId: normalized,
    source: 'agent',
    reason
  };
}

export function resolveDeviceTenantContext(explicitTenantId?: string): TenantContext {
  const normalized = normalizeTenantId(explicitTenantId);
  if (normalized) {
    return {
      tenantId: normalized,
      source: 'device'
    };
  }

  return buildPlatformTenantContext('device-platform-scope');
}

