﻿import 'dotenv/config';
import { createServer } from 'http';
import { closeDatabase } from './config/database';
import { getRuntimeDescriptor } from './config/platform-runtime';
import { bootstrapPersistence } from './bootstrap/persistence';
import { createControlPlaneApp } from './bootstrap/control-plane-app';
import { validateRuntimeEnvironment } from './bootstrap/runtime-env';
import logger from './utils/logger';
import { AgentGateway } from './websocket/agent-gateway';
import { DeviceGateway } from './websocket/device-gateway';
import { setAgentGateway } from './api/routes/agents.routes';
import { setDashboardAgentGateway } from './api/routes/dashboard.routes';
import {
  initializeAgentSystem,
  setAgentGateway as setAISystemAgentGateway
} from './api/routes/ai-system.routes';
import {
  getDeviceById,
  executeDeviceCommandInternal,
  setDeviceCommandTransport
} from './api/routes/devices.routes';
import { scannerTaskService } from './services/scanner-task.service';
import { runtimeEmulatorService } from './services/runtime-emulator.service';
import { commandDispatcherService } from './services/command-dispatcher.service';
import { postgresShadowStoreService } from './services/postgres-shadow-store.service';
import { notificationDispatcherService } from './services/notification-dispatcher.service';
import { deviceControlService } from './services/device-control.service';
import { artifactStoreService } from './services/artifact-store.service';
import { jobQueueService } from './services/job-queue.service';
import { dashboardBroadcastService } from './services/dashboard-broadcast.service';

const runtime = getRuntimeDescriptor();
let agentGateway: AgentGateway | null = null;
let deviceGateway: DeviceGateway | null = null;

const app = createControlPlaneApp({
  runtime,
  getAgentCount: () => agentGateway?.getOnlineCount() || 0
});
const httpServer = createServer(app);

function configureRealtimeRuntime(): void {
  if (runtime.gatewayEnabled) {
    agentGateway = new AgentGateway(httpServer);
    deviceGateway = new DeviceGateway(httpServer);
    dashboardBroadcastService.setBroadcaster((event, data) => {
      agentGateway?.broadcastToDashboards(event, data);
    });
    deviceGateway.setDashboardBroadcaster((event, data) => {
      dashboardBroadcastService.broadcast(event, data);
    });
    deviceControlService.setGatewayEmitter((deviceId, command, params) =>
      deviceGateway!.sendCommand(deviceId, command, params)
    );

    setAgentGateway(agentGateway);
    setDashboardAgentGateway(agentGateway);
    setAISystemAgentGateway(agentGateway);
    commandDispatcherService.setAgentGateway(agentGateway);
    commandDispatcherService.setDeviceAdapter({
      getDevice: getDeviceById,
      executeCommand: executeDeviceCommandInternal
    });
    setDeviceCommandTransport((deviceId, command, params) =>
      deviceGateway!.sendCommand(deviceId, command, params)
    );
    scannerTaskService.setBroadcaster((event, data) => {
      dashboardBroadcastService.broadcast(event, data);
    });

    if (runtime.emulatorEnabled) {
      runtimeEmulatorService.start(agentGateway);
    } else {
      runtimeEmulatorService.stop();
    }
    return;
  }

  setAgentGateway(null);
  setDashboardAgentGateway(null);
  setAISystemAgentGateway(null as any);
  commandDispatcherService.setAgentGateway(null);
  commandDispatcherService.setDeviceAdapter(null);
  setDeviceCommandTransport(null);
  deviceControlService.setGatewayEmitter(null);
  dashboardBroadcastService.setBroadcaster(null);
  scannerTaskService.setBroadcaster(() => undefined);
  runtimeEmulatorService.stop();
}

async function start(): Promise<void> {
  const port = Number(process.env.PORT || 8080);

  try {
    const envReport = validateRuntimeEnvironment();
    await bootstrapPersistence();
    configureRealtimeRuntime();

    if (runtime.workerEnabled) {
      await scannerTaskService.startWorker();
    }

    notificationDispatcherService.startWorker();

    if (runtime.schedulerEnabled) {
      postgresShadowStoreService.startResyncLoop();
    }

    if (runtime.apiEnabled) {
      try {
        await initializeAgentSystem();
        logger.info('Multi-Agent Decision System initialized');
      } catch (agentError: any) {
        logger.warn('Multi-Agent System initialization failed, continuing without AI agents', {
          error: agentError.message
        });
      }
    }

    httpServer.listen(port, () => {
      logger.info('AetherGuard Control Platform started', {
        port,
        runtime,
        queueBackend: jobQueueService.backend(),
        artifactStore: artifactStoreService.describe(),
        shadowStore: postgresShadowStoreService.describe(),
        envWarnings: envReport.warnings
      });
    });
  } catch (error: any) {
    logger.error('Failed to start server', { error: error?.message || error });
    process.exit(1);
  }
}

async function shutdown(): Promise<void> {
  logger.info('Shutting down...');

  try {
    scannerTaskService.stopWorker();
    notificationDispatcherService.stopWorker();

    if (agentGateway) {
      agentGateway.close();
      agentGateway = null;
    }
    if (deviceGateway) {
      deviceGateway.close();
      deviceGateway = null;
    }
    dashboardBroadcastService.setBroadcaster(null);

    runtimeEmulatorService.stop();

    await new Promise<void>((resolve, reject) => {
      httpServer.close((error) => {
        if (error) {
          reject(error);
          return;
        }
        resolve();
      });
    }).catch(() => undefined);

    await postgresShadowStoreService.close();
    closeDatabase();

    logger.info('Shutdown complete');
  } catch (error: any) {
    logger.error('Error during shutdown', { error: error?.message || error });
  }

  process.exit(0);
}

process.on('SIGTERM', () => {
  void shutdown();
});
process.on('SIGINT', () => {
  void shutdown();
});

void start();

export default app;
export { agentGateway, start };

import { randomUUID } from 'crypto';
import { NextFunction, Request, Response } from 'express';
import { AuthenticatedRequest, verifyToken } from './auth.middleware';
import { DetectionDecision, detectionPipelineService } from '../services/detection-pipeline.service';
import { fastpathTrafficShadowService } from '../services/fastpath-traffic-shadow.service';
import { PLATFORM_TENANT_ID } from '../core/tenant/tenant-context';
import logger from '../utils/logger';

interface ShadowRequest extends AuthenticatedRequest {
  rawBody?: Buffer;
  detectionDecision?: DetectionDecision;
}

function normalizeHeaderValue(value: unknown): string {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '')).join(', ');
  }
  return String(value ?? '');
}

function normalizeHeaders(headers: Record<string, unknown>): Record<string, string> {
  return Object.entries(headers || {}).reduce<Record<string, string>>((acc, [key, value]) => {
    if (!key) {
      return acc;
    }
    acc[key.toLowerCase()] = normalizeHeaderValue(value);
    return acc;
  }, {});
}

function tokenFromRequest(req: ShadowRequest): string | null {
  const cookieToken = req.cookies?.accessToken;
  if (typeof cookieToken === 'string' && cookieToken.trim()) {
    return cookieToken.trim();
  }

  const authHeader = req.headers.authorization;
  if (typeof authHeader === 'string' && authHeader.startsWith('Bearer ')) {
    const bearer = authHeader.slice('Bearer '.length).trim();
    return bearer || null;
  }

  return null;
}

function resolveTenantId(req: ShadowRequest): string {
  const token = tokenFromRequest(req);
  if (token) {
    const user = verifyToken(token);
    if (user?.tenantId?.trim()) {
      return user.tenantId.trim();
    }
  }

  return String(
    req.tenantContext?.tenantId ||
    req.user?.tenantId ||
    req.headers['x-tenant-id'] ||
    PLATFORM_TENANT_ID
  ).trim() || PLATFORM_TENANT_ID;
}

function resolveRequestBody(req: ShadowRequest): string {
  if (Buffer.isBuffer(req.rawBody)) {
    return Buffer.from(req.rawBody).toString('utf8');
  }
  if (typeof req.body === 'string') {
    return req.body;
  }
  if (Buffer.isBuffer(req.body)) {
    return req.body.toString('utf8');
  }
  if (req.body && typeof req.body === 'object') {
    return JSON.stringify(req.body);
  }
  return '';
}

function safeDecodeTransportValue(value: string): string {
  let decoded = String(value || '');
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const normalized = decoded.replace(/\+/g, '%20');
    try {
      const next = decodeURIComponent(normalized);
      if (next === decoded) {
        break;
      }
      decoded = next;
    } catch {
      decoded = decoded.replace(/\+/g, ' ');
      break;
    }
  }

  return decoded.replace(/\+/g, ' ');
}

function flattenValue(value: unknown): string {
  if (Array.isArray(value)) {
    return value.map((item) => flattenValue(item)).join(', ');
  }
  if (value && typeof value === 'object') {
    return JSON.stringify(value);
  }
  return String(value ?? '');
}

function resolveUrlShape(rawUrl: string): {
  decodedPath: string;
  query: string;
  decodedQuery: string;
  parsedQuery: string;
} {
  try {
    const parsed = new URL(rawUrl || '/', 'http://detector.local');
    const query = parsed.search.startsWith('?') ? parsed.search.slice(1) : '';
    const parsedQuery = Array.from(parsed.searchParams.entries())
      .flatMap(([key, value]) => [`${key}=${value}`, value])
      .join('\n');

    return {
      decodedPath: safeDecodeTransportValue(rawUrl || '/'),
      query,
      decodedQuery: safeDecodeTransportValue(query),
      parsedQuery
    };
  } catch {
    return {
      decodedPath: safeDecodeTransportValue(rawUrl || '/'),
      query: '',
      decodedQuery: '',
      parsedQuery: ''
    };
  }
}

function resolveStructuredBody(body: unknown): string {
  if (!body || typeof body !== 'object' || Buffer.isBuffer(body)) {
    return '';
  }

  return Object.entries(body as Record<string, unknown>)
    .flatMap(([key, value]) => {
      const flattened = flattenValue(value);
      return [`${key}=${flattened}`, flattened];
    })
    .join('\n');
}

function resolveNormalizedBody(req: Request, headers: Record<string, string>, rawBody: string): {
  normalizedBody: string;
  parsedBody: string;
} {
  const contentType = String(headers['content-type'] || '').toLowerCase();
  const normalizedBody = safeDecodeTransportValue(rawBody || '');

  if (contentType.includes('application/x-www-form-urlencoded')) {
    try {
      const parsed = new URLSearchParams(rawBody || '');
      const parsedBody = Array.from(parsed.entries())
        .flatMap(([key, value]) => [`${key}=${value}`, value])
        .join('\n');

      return {
        normalizedBody,
        parsedBody
      };
    } catch {
      return {
        normalizedBody,
        parsedBody: normalizedBody
      };
    }
  }

  if (contentType.includes('application/json') || typeof req.body === 'object') {
    const parsedBody = resolveStructuredBody(req.body) || normalizedBody;
    return {
      normalizedBody,
      parsedBody
    };
  }

  return {
    normalizedBody,
    parsedBody: normalizedBody
  };
}

export async function apiTrafficShadowMiddleware(req: Request, res: Response, next: NextFunction): Promise<void> {
  fastpathTrafficShadowService.submitFromRequest(req);

  if (req.method === 'OPTIONS' || req.path === '/health' || req.path === '/api/health') {
    next();
    return;
  }

  const shadowRequest = req as ShadowRequest;

  try {
    const headers = normalizeHeaders(req.headers as Record<string, unknown>);
    const rawUrl = shadowRequest.originalUrl || shadowRequest.url || '/';
    const rawBody = resolveRequestBody(shadowRequest);
    const urlShape = resolveUrlShape(rawUrl);
    const bodyShape = resolveNormalizedBody(req, headers, rawBody);
    const rawPayload = [
      rawUrl,
      urlShape.decodedPath,
      urlShape.query,
      urlShape.decodedQuery,
      urlShape.parsedQuery,
      rawBody,
      bodyShape.normalizedBody,
      bodyShape.parsedBody
    ].filter(Boolean).join('\n');
    const decision = await detectionPipelineService.evaluateRequest({
      tenantId: resolveTenantId(shadowRequest),
      channel: 'http_api',
      requestId: String(req.headers['x-request-id'] || randomUUID()),
      timestamp: new Date().toISOString(),
      sourceIp: String(shadowRequest.ip || shadowRequest.socket?.remoteAddress || '').trim(),
      method: shadowRequest.method,
      path: rawUrl,
      decodedPath: urlShape.decodedPath,
      query: urlShape.query,
      decodedQuery: urlShape.decodedQuery,
      parsedQuery: urlShape.parsedQuery,
      headers,
      body: rawBody,
      normalizedBody: bodyShape.normalizedBody,
      parsedBody: bodyShape.parsedBody,
      userAgent: headers['user-agent'] || '',
      evidence: '',
      protocol: `HTTP/${shadowRequest.httpVersion || '1.1'}`,
      rawPayload,
      metadata: {
        contentType: headers['content-type'] || '',
        route: shadowRequest.path
      }
    });

    shadowRequest.detectionDecision = decision;

    if (decision.verdict === 'block') {
      res.status(403).json({
        success: false,
        error: {
          code: 'backend.request_blocked_by_detection_pipeline',
          message: 'Request blocked by rule-first detection pipeline',
          decisionSource: decision.decisionSource,
          matchedRuleIds: decision.matchedRuleIds,
          riskScore: decision.riskScore,
          aiVerdict: decision.aiVerdict || null
        }
      });
      return;
    }

    next();
  } catch (error: unknown) {
    logger.warn('HTTP detection pipeline failed, continuing request', {
      path: req.originalUrl || req.url,
      error: error instanceof Error ? error.message : String(error)
    });
    next();
  }
}

export default apiTrafficShadowMiddleware;

﻿/**
 * JWT Authentication Middleware
 *
 * Provides secure authentication for AetherGuard API endpoints
 * SECURITY FIX: Enhanced environment variable validation
 */

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import logger from '../utils/logger';
import redisService from '../security/redis.service';
import EnvValidator from '../security/env-validator.service';
import { resolveRequestTenantContext, TenantContext } from '../core/tenant/tenant-context';

// Validate environment variables at module load
try {
  EnvValidator.require('JWT_SECRET', {
    minLength: 32,
    description: 'JWT signing secret'
  });
} catch (error) {
  // Re-throw with clearer message
  throw new Error('FATAL: JWT_SECRET environment variable is required (minimum 32 characters). Server cannot start without it.');
}

const JWT_SECRET: string = process.env.JWT_SECRET!;
const JWT_EXPIRES_IN = EnvValidator.optional('JWT_EXPIRES_IN', '24h');
const JWT_REFRESH_EXPIRES_IN = EnvValidator.optional('JWT_REFRESH_EXPIRES_IN', '7d');

/**
 * Authenticated user payload stored in JWT
 */
export interface AuthenticatedUser {
    userId: string;
    email: string;
    username: string;
    role: 'admin' | 'tenant' | 'viewer';
    plan?: 'starter' | 'pro' | 'ultra';
    tenantId?: string;
}

/**
 * Extended Express Request with user info
 */
export interface AuthenticatedRequest extends Request {
    user?: AuthenticatedUser;
    tenantContext?: TenantContext;
}

/**
 * Token pair for authentication
 */
export interface TokenPair {
    accessToken: string;
    refreshToken: string;
    expiresIn: number;
}

/**
 * Generate JWT token pair
 * SECURITY FIX: Explicitly specify algorithm for token generation
 */
export function generateTokens(user: AuthenticatedUser): TokenPair {
    const accessToken = jwt.sign(user, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN, algorithm: 'HS256' } as jwt.SignOptions);
    const refreshToken = jwt.sign(
        { userId: user.userId, type: 'refresh' },
        JWT_SECRET,
        { expiresIn: JWT_REFRESH_EXPIRES_IN, algorithm: 'HS256' } as jwt.SignOptions
    );

    // Calculate expiration in seconds
    const decoded = jwt.decode(accessToken) as jwt.JwtPayload;
    const expiresIn = (decoded?.exp || 0) - Math.floor(Date.now() / 1000);

    return { accessToken, refreshToken, expiresIn };
}

/**
 * Verify and decode JWT token
 * SECURITY FIX CVE-2026-001: Now checks Redis blacklist for logged-out tokens
 * SECURITY FIX: Explicitly specify allowed algorithms to prevent algorithm confusion attacks
 */
export function verifyToken(token: string): AuthenticatedUser | null {
    try {
        const decoded = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }) as AuthenticatedUser;
        return decoded;
    } catch (error) {
        return null;
    }
}

/**
 * Async version of verifyToken that checks Redis blacklist
 * SECURITY FIX CVE-2026-001: Check if token is blacklisted before accepting
 * SECURITY FIX: Fail secure when Redis is unavailable - reject tokens if we can't verify blacklist
 * SECURITY FIX: Explicitly specify allowed algorithms to prevent algorithm confusion attacks
 */
export async function verifyTokenAsync(token: string): Promise<AuthenticatedUser | null> {
    let isRedisAvailable = false;

    // First verify JWT is valid
    let decoded: AuthenticatedUser;
    try {
        decoded = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }) as AuthenticatedUser;
    } catch (error) {
        return null;
    }

    // Try to check blacklist - fail secure if Redis unavailable
    try {
        isRedisAvailable = redisService.isAvailable();
    } catch (error) {
        isRedisAvailable = false;
    }

    if (isRedisAvailable) {
        try {
            const isBlacklisted = await redisService.exists(`token:blacklist:${token}`);
            if (isBlacklisted) {
                logger.warn('Attempted use of blacklisted token');
                return null;
            }
        } catch (error) {
            // Redis error during blacklist check - fail secure
            logger.error('Token blacklist check failed due to Redis error, rejecting token for security');
            return null;
        }
    } else {
        // Fail secure by default. Development bypass must be explicitly enabled.
        const allowInsecureBypass =
            process.env.NODE_ENV === 'test' ||
            (process.env.ALLOW_INSECURE_AUTH_WHEN_REDIS_DOWN === 'true' &&
             process.env.NODE_ENV !== 'production');

        if (!allowInsecureBypass) {
            logger.warn('Redis unavailable, rejecting token for security (fail-secure)');
            return null;
        }

        logger.warn('Redis unavailable, allowing token due to ALLOW_INSECURE_AUTH_WHEN_REDIS_DOWN=true');
    }

    return decoded;
}

/**
 * Verify refresh token
 * SECURITY FIX: Explicitly specify allowed algorithms to prevent algorithm confusion attacks
 */
export function verifyRefreshToken(token: string): { userId: string } | null {
    try {
        const decoded = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }) as { userId: string; type: string };
        if (decoded.type !== 'refresh') {
            return null;
        }
        return { userId: decoded.userId };
    } catch (error) {
