/**
 * SECURITY FIX: Cookie configuration for httpOnly tokens
 * SECURITY FIX: Changed sameSite from 'lax' to 'strict' for better security
 */
const COOKIE_MAX_AGE = 24 * 60 * 60 * 1000;
const REFRESH_COOKIE_MAX_AGE = 7 * 24 * 60 * 60 * 1000;

const isHttpsRequest = (req: Request): boolean => {
    const forwardedProto = req.headers['x-forwarded-proto'];
    const proto = Array.isArray(forwardedProto) ? forwardedProto[0] : forwardedProto;
    return req.secure || proto === 'https';
};

export const buildCookieOptions = (req: Request) => ({
    httpOnly: true,
    secure: isHttpsRequest(req),
    sameSite: 'strict' as const,
    path: '/',
    maxAge: COOKIE_MAX_AGE // 24 hours
});

export const buildRefreshCookieOptions = (req: Request) => ({
    ...buildCookieOptions(req),
    maxAge: REFRESH_COOKIE_MAX_AGE // 7 days
});

/**
 * Authentication middleware - requires valid JWT token
 * SECURITY FIX: Now checks httpOnly cookie first, then Authorization header
 * SECURITY FIX CVE-2026-001: Now checks Redis blacklist for logged-out tokens
 */
export async function authenticate(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    // SECURITY FIX: Check httpOnly cookie first
    let token = req.cookies?.accessToken;

    // Fallback to Authorization header for API clients
    if (!token) {
        const authHeader = req.headers.authorization;
        if (authHeader && authHeader.startsWith('Bearer ')) {
            token = authHeader.split(' ')[1];
        }
    }

    if (!token) {
        res.status(401).json({
            error: 'backend.authentication_required',
            code: 'AUTH_TOKEN_MISSING'
        });
        return;
    }

    // SECURITY FIX CVE-2026-001: Use async version with blacklist check
    const user = await verifyTokenAsync(token);

    if (!user) {
        res.status(401).json({
            error: 'backend.invalid_or_expired_token',
            code: 'AUTH_TOKEN_INVALID'
        });
        return;
    }

    req.user = user;
    logger.debug(`Authenticated user: ${user.email}`);
    next();
}

/**
 * Optional authentication - attaches user if token present, continues otherwise
 * SECURITY FIX: Now uses async blacklist check
 */
export async function optionalAuth(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    // Check cookie first, then header
    let token = req.cookies?.accessToken;

    if (!token) {
        const authHeader = req.headers.authorization;
        if (authHeader && authHeader.startsWith('Bearer ')) {
            token = authHeader.split(' ')[1];
        }
    }

    if (token) {
        // SECURITY FIX: Use async version with blacklist check
        const user = await verifyTokenAsync(token);
        if (user) {
            req.user = user;
        }
    }

    next();
}

/**
 * Role-based access control middleware
 */
export function requireRole(...allowedRoles: Array<'admin' | 'tenant' | 'viewer'>) {
    return (req: AuthenticatedRequest, res: Response, next: NextFunction): void => {
        if (!req.user) {
            res.status(401).json({
                error: 'backend.authentication_required',
                code: 'AUTH_REQUIRED'
            });
            return;
        }

        if (!allowedRoles.includes(req.user.role)) {
            logger.warn(`Access denied for user ${req.user.email} (role: ${req.user.role}), required: ${allowedRoles.join('/')}`);
            res.status(403).json({
                error: 'backend.insufficient_permissions',
                code: 'AUTH_FORBIDDEN',
                requiredRoles: allowedRoles
            });
            return;
        }

        next();
    };
}

/**
 * Tenant isolation middleware - ensures users can only access their tenant's resources
 * SECURITY FIX CVE-2026-010: Reject requests without tenantId for non-admin users
 */
export function requireTenantAccess(req: AuthenticatedRequest, res: Response, next: NextFunction): void {
    if (!req.user) {
        res.status(401).json({ error: 'backend.authentication_required' });
        return;
    }

    const context = resolveRequestTenantContext(req, {
        allowAdminPlatformFallback: req.user.role === 'admin'
    });

    if (!context) {
        res.status(403).json({
            error: 'backend.tenant_resolution_required',
            code: 'TENANT_REQUIRED'
        });
        return;
    }

    if (req.user.role !== 'admin' && context.tenantId !== req.user.tenantId) {
        res.status(403).json({
            error: 'backend.cannot_access_resources_from_another_tenant',
            code: 'TENANT_MISMATCH'
        });
        return;
    }

    if (!req.body) req.body = {};
    if (!req.body.tenantId) {
        req.body.tenantId = context.tenantId;
    }

    next();
}

/**
 * SECURITY FIX CVE-2026-011 & CVE-2026-102: Constant-time string comparison
 * Fixed to prevent timing attacks on string length
 */
function constantTimeCompare(a: string, b: string): boolean {
    // SECURITY FIX CVE-2026-102: Early return is safe when lengths differ
    // Attackers can already tell the length difference from response time
    if (a.length !== b.length) {
        return false;
    }

    // Use crypto.timingSafeEqual for actual comparison
    return crypto.timingSafeEqual(
        Buffer.from(a, 'utf8'),
        Buffer.from(b, 'utf8')
    );
}

/**
 * API Key authentication for agent/device communication
 * SECURITY FIX CVE-2026-011: Use constant-time comparison
 * SECURITY FIX CVE-2026-012: Add tenant isolation for API keys
 */
export function authenticateApiKey(req: AuthenticatedRequest, res: Response, next: NextFunction): void {
    const apiKey = req.headers['x-api-key'] as string;

    if (!apiKey) {
        res.status(401).json({
            error: 'backend.api_key_required',
            code: 'API_KEY_MISSING'
        });
        return;
    }

    // SECURITY FIX: No default API keys allowed
    const validApiKeys = process.env.VALID_API_KEYS?.split(',').filter(k => k.trim());

    if (!validApiKeys || validApiKeys.length === 0) {
        logger.error('No valid API keys configured in VALID_API_KEYS environment variable');
        res.status(500).json({
            error: 'backend.server_configuration_error',
            code: 'API_KEYS_NOT_CONFIGURED'
        });
        return;
    }

    // SECURITY FIX CVE-2026-011: Use constant-time comparison to prevent timing attacks
    const isValidKey = validApiKeys.some(validKey => constantTimeCompare(apiKey, validKey.trim()));

    if (!isValidKey) {
        logger.warn('Invalid API key attempt', { ip: req.ip });
        res.status(401).json({
            error: 'backend.invalid_api_key',
            code: 'API_KEY_INVALID'
        });
        return;
    }

    // SECURITY FIX CVE-2026-012: Extract tenant ID from API key pattern or use default
    // Format: key_tenantId_suffix or use API_KEY_TENANT_ID env var
    const apiKeyTenantId = extractTenantIdFromApiKey(apiKey);

    // Attach a system user for API key requests with tenant isolation
    req.user = {
        userId: 'api-key-user',
        email: 'api@AetherGuard.local',
        username: 'API Client',
        role: 'tenant',
        plan: 'ultra',
        tenantId: apiKeyTenantId
    };

    next();
}

/**
 * SECURITY FIX CVE-2026-012: Extract tenant ID from API key or environment
 */
function extractTenantIdFromApiKey(apiKey: string): string {
    // Check if there's a configured tenant ID for API keys
    const configuredTenantId = process.env.API_KEY_TENANT_ID;
    if (configuredTenantId) {
        return configuredTenantId;
    }

    // Try to extract tenant ID from API key pattern (e.g., "key_tenant123_suffix")
    // Default pattern: the API key may contain tenant info after a delimiter
    const parts = apiKey.split('_');
    if (parts.length >= 2) {
        // Use second part as tenant ID if it looks like a valid ID
        const potentialTenantId = parts[1];
        if (potentialTenantId && potentialTenantId.length >= 8) {
            return potentialTenantId;
        }
    }

    // Fallback to a default tenant ID
    return 'default-tenant';
}

/**
 * Combined auth - accepts either JWT or API key
 */
export async function authenticateAny(req: AuthenticatedRequest, res: Response, next: NextFunction): Promise<void> {
    const authHeader = req.headers.authorization;
    const apiKey = req.headers['x-api-key'] as string;

    if (authHeader && authHeader.startsWith('Bearer ')) {
        return authenticate(req, res, next);
    }

    if (apiKey) {
        return authenticateApiKey(req, res, next);
    }

    res.status(401).json({
        error: 'backend.authentication_required_jwt_or_api_key',
        code: 'AUTH_REQUIRED'
    });
}

// Compatibility export for agent-only routes.
export const authenticateAgent = authenticateApiKey;

/**
 * Request timing middleware interface
 */
export interface TimedRequest extends Request {
  startTime?: number;
}

/**
 * Request timing middleware
 * Tracks request processing time and emits events for monitoring
 */
export function requestTimingMiddleware(
  req: TimedRequest,
  res: Response,
  next: NextFunction
): void {
  req.startTime = Date.now();

  // Listen for response finish event
  res.on('finish', () => {
    const duration = Date.now() - (req.startTime || 0);
    // Emit timing event for monitoring (will be picked up by simulation service)
    if (req.startTime) {
      req.emit('requestTiming', { duration, path: req.path });
    }
  });

  next();
}

/**
 * 路径验证中间件
 * 防止路径遍历攻击 (Path Traversal)
 */

import { Request, Response, NextFunction } from 'express';
import path from 'path';
import fs from 'fs';
import logger from '../utils/logger';

/**
 * 路径遍历防护选项
 */
export interface PathValidationOptions {
    /** 允许的根目录 */
    baseDir: string;
    /** 是否允许访问子目录 */
    allowSubdirectories?: boolean;
    /** 允许的扩展名列表 (可选) */
    allowedExtensions?: string[];
    /** 是否规范化路径 */
    normalize?: boolean;
    /** 参数名 (从 req.query 或 req.body 中获取) */
    paramName?: string;
    /** 是否必须存在 */
    mustExist?: boolean;
}

/**
 * 解析并验证路径
 */
export function resolveAndValidatePath(
    requestedPath: string,
    options: PathValidationOptions
): { valid: boolean; resolvedPath?: string; error?: string } {
    const {
        baseDir,
        allowSubdirectories = true,
        allowedExtensions,
        normalize = true,
        mustExist = false
    } = options;

    // 基础验证
    if (!requestedPath || typeof requestedPath !== 'string') {
        return { valid: false, error: 'backend.path_is_required' };
    }

    // 长度限制
    if (requestedPath.length > 4096) {
        return { valid: false, error: 'backend.path_too_long' };
    }

    // 检查路径遍历攻击特征
    const traversalPatterns = [
        /\.\.[\\\/]/,           // ../ 或 ..\
        /[\\\/]\.\.[\\\/]/,      // /../
        /%2e%2e[\\\/]/i,         // URL编码的 ../
        /%252e%252e[\\\/]/i,     // 双重URL编码
        /\x2e\x2e[\\\/]/,        // 十六进制编码
        /\.\.\.+/                // 多个点
    ];

    for (const pattern of traversalPatterns) {
        if (pattern.test(requestedPath)) {
            logger.warn(`Path traversal attempt detected: ${requestedPath}`);
            return { valid: false, error: 'backend.invalid_path_characters_detected' };
        }
    }

    // 规范化路径
    let resolvedPath: string;
    if (normalize) {
        // 先规范化，再解析为绝对路径
        const normalizedPath = path.normalize(requestedPath).replace(/\\/g, '/');
        resolvedPath = path.resolve(baseDir, normalizedPath);
    } else {
        resolvedPath = path.resolve(baseDir, requestedPath);
    }

    // 规范化基础目录
    const resolvedBase = path.resolve(baseDir);

    // 安全检查: 确保解析后的路径在允许目录内
    if (!resolvedPath.startsWith(resolvedBase)) {
        logger.warn(`Path traversal attempt: ${requestedPath} resolved to ${resolvedPath}, outside base ${resolvedBase}`);
        return { valid: false, error: 'backend.access_denied_path_outside_allowed_directory' };
    }

    // 子目录检查
    if (!allowSubdirectories) {
        const relativePath = path.relative(resolvedBase, resolvedPath);
        if (relativePath.includes(path.sep) || relativePath.includes('/')) {
            return { valid: false, error: 'backend.subdirectories_not_allowed' };
        }
    }

    // 扩展名检查
    if (allowedExtensions && allowedExtensions.length > 0) {
        const ext = path.extname(resolvedPath).toLowerCase();
        if (!allowedExtensions.includes(ext)) {
            return { valid: false, error: `File extension not allowed. Allowed: ${allowedExtensions.join(', ')}` };
        }
    }

    // 文件必须存在
    if (mustExist) {
        if (!fs.existsSync(resolvedPath)) {
            return { valid: false, error: 'backend.file_not_found' };
        }
    }

    return { valid: true, resolvedPath };
}

/**
 * Express 中间件 - 验证路径参数
 */
export function validatePath(options: PathValidationOptions) {
    const { paramName = 'path', mustExist = false } = options;

    return (req: Request, res: Response, next: NextFunction) => {
        // 从 query 或 body 获取路径
        const requestedPath = req.query[paramName] || req.body?.[paramName];

        if (!requestedPath || typeof requestedPath !== 'string') {
            return res.status(400).json({
                success: false,
                error: 'backend.path_parameter_is_required',
                code: 'MISSING_PATH'
            });
        }

        const result = resolveAndValidatePath(requestedPath, {
            ...options,
            mustExist
        });

        if (!result.valid) {
            logger.warn(`Path validation failed: ${result.error}`, {
                path: requestedPath,
                ip: req.ip
            });

            return res.status(403).json({
                success: false,
                error: result.error,
                code: 'PATH_VALIDATION_FAILED'
            });
        }

        // 将验证后的路径附加到请求对象
        (req as any).validatedPath = result.resolvedPath;
        (req as any).validatedPathInfo = {
            original: requestedPath,
            resolved: result.resolvedPath
        };

        next();
    };
}

/**
 * 便捷方法 - 验证文件路径
 */
export function validateFilePath(baseDir: string, options: Partial<PathValidationOptions> = {}) {
    return validatePath({
        baseDir,
        allowedExtensions: options.allowedExtensions,
        mustExist: options.mustExist ?? true,
        paramName: options.paramName || 'path'
    });
}

export default {
    resolveAndValidatePath,
    validatePath,
    validateFilePath
};

import { Response, NextFunction } from 'express';
import { AuthenticatedRequest } from './auth.middleware';
import { getDatabase } from '../config/database';
import logger from '../utils/logger';

export const PLAN_LIMITS = {
    starter: { sites: 1, agents: 1 },
    pro: { sites: 5, agents: 5 },
    ultra: { sites: -1, agents: -1 } // -1 means unlimited
};

type PlanType = keyof typeof PLAN_LIMITS;

export function requirePlanQuota(resourceType: 'site' | 'agent') {
    return (req: AuthenticatedRequest, res: Response, next: NextFunction): void => {
        if (!req.user) {
            res.status(401).json({ error: 'backend.authentication_required' });
            return;
        }

        // Admins automatically bypass plan constraints
        if (req.user.role === 'admin') {
            next();
            return;
        }

        const plan = (req.user.plan || 'starter') as PlanType;
        const limits = PLAN_LIMITS[plan] || PLAN_LIMITS.starter;

        // Unlimited threshold
        if (resourceType === 'site' && limits.sites === -1) {
            next();
            return;
        }
        if (resourceType === 'agent' && limits.agents === -1) {
            next();
            return;
        }

        try {
            const db = getDatabase();
            const tenantId = req.user.tenantId;

            if (resourceType === 'site') {
                const row = db.prepare('SELECT COUNT(*) as count FROM sites WHERE tenant_id = ?').get(tenantId) as { count: number };
                if (row.count >= limits.sites) {
                    res.status(403).json({
                        error: `Plan quota exceeded. Your ${plan} plan allows up to ${limits.sites} site(s). Please upgrade to add more.`,
                        code: 'PLAN_QUOTA_EXCEEDED',
                        plan
                    });
                    return;
                }
            } else if (resourceType === 'agent') {
                // Count how many codes have been issued (active + used) to prevent hoarding constraints
                const row = db.prepare(`
                    SELECT COUNT(*) as count FROM agent_onboarding_codes 
                    WHERE tenant_id = ? AND status IN ('active', 'used')
                `).get(tenantId) as { count: number };

                if (row.count >= limits.agents) {
                    res.status(403).json({
                        error: `Plan quota exceeded. Your ${plan} plan allows up to ${limits.agents} agent(s). Please upgrade to add more.`,
                        code: 'PLAN_QUOTA_EXCEEDED',
                        plan
                    });
                    return;
                }
            }

            next();
        } catch (error: any) {
            logger.error('Quota checking failed', { error: error.message });
            res.status(500).json({ error: 'backend.failed_to_verify_plan_quotas', code: 'INTERNAL_ERROR' });
        }
    };
}

/**
 * Rate Limiting Middleware
 *
 * SECURITY FIX for RISK-001: IP Spoofing Bypass
 *
 * Provides multi-dimensional rate limiting for API endpoints
 */

import { Request, Response, NextFunction } from 'express';
import enhancedRateLimiter from '../security/enhanced-rate-limiter.service';
import {
  apiRateLimitEngineService,
  hashRateLimitFingerprint
} from '../services/api-rate-limit-engine.service';
import logger from '../utils/logger';

export interface RateLimitMiddlewareOptions {
  maxRequests?: number;
  windowMs?: number;
  skipSuccessfulRequests?: boolean;
  skipFailedRequests?: boolean;
  keyGenerator?: (req: Request) => string;
  handler?: (req: Request, res: Response) => void;
}

/**
 * Default rate limit handler
 */
function defaultHandler(req: Request, res: Response): void {
  res.status(429).json({
    error: 'backend.too_many_requests',
    code: 'RATE_LIMIT_EXCEEDED',
    retryAfter: 60, // seconds
  });
}

/**
 * Create rate limit middleware
 */
export function rateLimit(options: RateLimitMiddlewareOptions = {}) {
  const {
    maxRequests = 100,
    windowMs = 60000,
    keyGenerator,
    handler = defaultHandler,
  } = options;

  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const identifier = keyGenerator
        ? keyGenerator(req)
        : getDefaultKey(req);
      const ip = getClientIP(req);
      const sessionId = String((req as any).sessionID || req.headers['x-session-id'] || '');
      const forwardedFor = String(req.headers['x-forwarded-for'] || '').trim();
      const realIp = String(req.headers['x-real-ip'] || '').trim();
      const endpoint = `${req.method}:${req.path}`;
      const fingerprint = hashRateLimitFingerprint(buildRequestFingerprint(req, ip));

      if (isApiRateLimitEngineEnabled()) {
        const engineResult = await apiRateLimitEngineService.check({
          identifier,
          ip,
          endpoint,
          maxRequests,
          windowMs,
          fingerprint,
          forwardedFor,
          realIp,
          sessionId,
          protocol: 'http'
        });

        if (engineResult) {
          res.setHeader('X-RateLimit-Limit', maxRequests.toString());
          res.setHeader('X-RateLimit-Remaining', engineResult.remaining.toString());
          res.setHeader('X-RateLimit-Reset', Math.floor(engineResult.resetAtMs / 1000).toString());

          if (!engineResult.allowed) {
            if (isRapidIpRotation(engineResult.reason)) {
              logger.error('IP spoofing detected, blocking request', {
                identifier,
                ip,
                reason: engineResult.reason,
                riskFlags: engineResult.riskFlags
              });

              res.status(429).json({
                error: 'backend.request_blocked_suspicious_activity_detected',
                code: 'IP_SPOOFING_DETECTED',
              });
              return;
            }

            const retryAfter = Math.ceil((engineResult.resetAtMs - Date.now()) / 1000);
            res.setHeader('Retry-After', Math.max(retryAfter, 1).toString());
            return handler(req, res);
          }

          next();
          return;
        }
      }

      const spoofingCheck = await enhancedRateLimiter.detectIPSpoofing({
        identifier,
        ip,
      });

      if (spoofingCheck.suspicious) {
        logger.error('IP spoofing detected, blocking request', {
          identifier,
          ip,
          reason: spoofingCheck.reason,
        });

        res.status(429).json({
          error: 'backend.request_blocked_suspicious_activity_detected',
          code: 'IP_SPOOFING_DETECTED',
        });
        return;
      }
      const result = await enhancedRateLimiter.checkRateLimit({
        identifier,
        ip,
        endpoint,
        config: {
          maxRequests,
          windowMs,
        },
      });

      res.setHeader('X-RateLimit-Limit', result.limit.toString());
      res.setHeader('X-RateLimit-Remaining', result.remaining.toString());
      res.setHeader('X-RateLimit-Reset', Math.floor(result.resetTime.getTime() / 1000).toString());

      if (!result.allowed) {
        logger.warn('Rate limit exceeded', {
          identifier,
          ip,
          endpoint: req.path,
          reason: result.reason,
        });

        const retryAfter = Math.ceil((result.resetTime.getTime() - Date.now()) / 1000);
        res.setHeader('Retry-After', retryAfter.toString());

        return handler(req, res);
      }

      next();
    } catch (error) {
      logger.error('Rate limit middleware error', { error });
      // SECURITY FIX: Fail closed - reject request if rate limiter fails
      // This prevents attackers from bypassing rate limits by causing Redis failures
      res.status(503).json({
        error: 'backend.service_temporarily_unavailable',
        code: 'RATE_LIMIT_CHECK_FAILED',
        retryAfter: 5,
      });
    }
  };
}

function buildRequestFingerprint(req: Request, ip: string): string {
  const forwardedFor = String(req.headers['x-forwarded-for'] || '').trim();
  const realIp = String(req.headers['x-real-ip'] || '').trim();
  const userAgent = String(req.headers['user-agent'] || '').trim();
  const acceptLanguage = String(req.headers['accept-language'] || '').trim();
  return [ip, forwardedFor, realIp, userAgent, acceptLanguage].join('|');
}

/**
 * Get default key for rate limiting
 * Priority: user ID > session ID > IP
 */
function getDefaultKey(req: Request): string {
  const user = (req as any).user;
  if (user?.userId) {
    return `user:${user.userId}`;
  }

  const sessionID = (req as any).sessionID || req.headers['x-session-id'];
  if (sessionID) {
    return `session:${sessionID}`;
  }

  return `ip:${getClientIP(req)}`;
}

/**
 * Get client IP address with proxy support
 */
function getClientIP(req: Request): string {
  const trustProxy = process.env.TRUST_PROXY === 'true';
  if (trustProxy) {
    const forwardedFor = req.headers['x-forwarded-for'] as string;
    if (forwardedFor) {
      return forwardedFor.split(',')[0].trim();
    }
    const realIp = req.headers['x-real-ip'] as string;
    if (realIp) {
      return realIp.trim();
    }
  }
  return (
    req.socket.remoteAddress ||
    (req.connection as any)?.socket?.remoteAddress ||
    req.connection?.remoteAddress ||
    'unknown'
  ).trim();
}

function isApiRateLimitEngineEnabled(): boolean {
  const raw = String(process.env.API_RATE_LIMIT_ENGINE || '').trim().toLowerCase();
  return raw === 'redis-lua' || raw === 'true' || raw === '1';
}

function isRapidIpRotation(reason?: string): boolean {
  return String(reason || '').toLowerCase().includes('rapid ip rotation');
}

/**
 * Pre-configured rate limiters for different use cases
