type GatewayEmitter = (deviceId: string, command: string, params?: Record<string, any>) => Promise<boolean> | boolean;

function parseJson<T>(value: any, fallback: T): T {
  if (!value || typeof value !== 'string') {
    return fallback;
  }
  try {
    return JSON.parse(value) as T;
  } catch {
    return fallback;
  }
}

function stableJsonStringify(value: unknown): string {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => stableJsonStringify(item)).join(',')}]`;
  }

  const entries = Object.entries(value as Record<string, unknown>).sort(([left], [right]) => left.localeCompare(right));
  return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${stableJsonStringify(item)}`).join(',')}}`;
}

function hashPayload(value: Record<string, any>): string {
  return createHash('sha256').update(stableJsonStringify(value)).digest('hex');
}

function buildPhysicalConfirmationMessage(input: {
  deviceId: string;
  confirmationSessionId: string;
  commandType: string;
  payloadHash: string;
  monotonicCounter: number;
  timestamp: number;
}): string {
  return [
    input.deviceId,
    input.confirmationSessionId,
    input.commandType,
    input.payloadHash,
    String(input.monotonicCounter),
    String(input.timestamp)
  ].join('\n');
}

function verifySignature(publicKeyPem: string, message: string, signature: string): boolean {
  const encodings: Array<BufferEncoding | 'base64url'> = ['base64', 'hex', 'base64url'];
  return encodings.some((encoding) => {
    try {
      return createVerify('SHA256').update(message).end().verify(publicKeyPem, signature, encoding as any);
    } catch {
      return false;
    }
  });
}

class DeviceControlService {
  private schemaReady = false;
  private gatewayEmitter: GatewayEmitter | null = null;

  setGatewayEmitter(emitter: GatewayEmitter | null): void {
    this.gatewayEmitter = emitter;
  }

  prepare(): void {
    if (this.schemaReady) {
      return;
    }

    const db = getDatabase();
    db.exec(`
      CREATE TABLE IF NOT EXISTS device_firmware (
        id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        file_name TEXT NOT NULL,
        version TEXT NOT NULL,
        channel TEXT NOT NULL,
        artifact_ref TEXT NOT NULL,
        artifact_location TEXT NOT NULL,
        size_bytes INTEGER NOT NULL DEFAULT 0,
        notes TEXT,
        created_by TEXT NOT NULL,
        created_at TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_device_firmware_channel ON device_firmware(tenant_id, channel, created_at DESC);

      CREATE TABLE IF NOT EXISTS device_ota_jobs (
        id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        device_id TEXT NOT NULL,
        firmware_id TEXT NOT NULL,
        status TEXT NOT NULL,
        requested_by TEXT NOT NULL,
        result_json TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_device_ota_jobs_device ON device_ota_jobs(device_id, created_at DESC);

      CREATE TABLE IF NOT EXISTS device_confirmation_sessions (
        id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        device_id TEXT NOT NULL,
        command_type TEXT NOT NULL,
        payload_json TEXT,
        status TEXT NOT NULL,
        requested_by TEXT NOT NULL,
        result_json TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        confirmed_at TEXT
      );
      CREATE INDEX IF NOT EXISTS idx_device_confirmation_device ON device_confirmation_sessions(device_id, created_at DESC);
    `);

    this.schemaReady = true;
  }

  private assertPrepared(): void {
    if (this.schemaReady) {
      return;
    }

    if (process.env.NODE_ENV === 'test') {
      this.prepare();
      return;
    }

    throw new Error('Device control schema not initialized. Call deviceControlService.prepare() during bootstrap.');
  }

  async uploadFirmware(input: {
    tenantId: string;
    fileName: string;
    version: string;
    channel: string;
    contentBase64: string;
    notes?: string;
    actorId: string;
    actorEmail?: string;
    actorIp?: string;
  }): Promise<DeviceFirmwareRecord> {
    this.assertPrepared();
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const buffer = Buffer.from(input.contentBase64, 'base64');
    const artifact = await artifactStoreService.writeBinary(
      'devices/firmware',
      `${input.channel}/${input.version}-${input.fileName}`,
      buffer,
      'application/octet-stream'
    );

    const row = {
      id,
      tenant_id: input.tenantId,
      file_name: input.fileName,
      version: input.version,
      channel: input.channel,
      artifact_ref: artifact.artifactRef,
      artifact_location: artifact.location,
      size_bytes: buffer.length,
      notes: input.notes || null,
      created_by: input.actorEmail || input.actorId,
      created_at: createdAt
    };

    getDatabase().prepare(`
      INSERT INTO device_firmware (
        id, tenant_id, file_name, version, channel, artifact_ref, artifact_location, size_bytes, notes, created_by, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      row.id,
      row.tenant_id,
      row.file_name,
      row.version,
      row.channel,
      row.artifact_ref,
      row.artifact_location,
      row.size_bytes,
      row.notes,
      row.created_by,
      row.created_at
    );

    await auditLogger.log({
      tenantId: input.tenantId,
      eventType: 'device_firmware_uploaded',
      category: 'system',
      severity: 'info',
      actor: { type: 'user', id: input.actorId, email: input.actorEmail, ip: input.actorIp },
      action: 'upload_device_firmware',
      target: { type: 'server', id },
      details: {
        fileName: input.fileName,
        version: input.version,
        channel: input.channel,
        sizeBytes: buffer.length,
        artifactRef: artifact.artifactRef
      },
      status: 'success'
    });

    return this.mapFirmwareRow(row);
  }

  async triggerOta(input: {
    tenantId: string;
    deviceId: string;
    firmwareId: string;
    actorId: string;
    actorEmail?: string;
    actorIp?: string;
  }): Promise<DeviceOtaJobRecord> {
    this.assertPrepared();
    const firmware = this.getFirmware(input.firmwareId);
    if (!firmware) {
      throw new Error('backend.firmware_not_found');
    }
    if (!this.gatewayEmitter) {
      throw new Error('backend.device_gateway_unavailable');
    }

    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const payload = {
      otaJobId: id,
      firmwareId: firmware.id,
      version: firmware.version,
      channel: firmware.channel,
      artifactRef: firmware.artifactRef,
      artifactLocation: firmware.artifactLocation,
      fileName: firmware.fileName
    };

    const accepted = await this.gatewayEmitter(input.deviceId, 'ota_update', payload);
    const row = {
      id,
      tenant_id: input.tenantId,
      device_id: input.deviceId,
      firmware_id: input.firmwareId,
      status: accepted ? 'queued' : 'failed',
      requested_by: input.actorEmail || input.actorId,
      result_json: JSON.stringify({
        accepted,
        payload,
        message: accepted ? 'OTA command dispatched.' : 'Device gateway rejected OTA command.'
      }),
      created_at: createdAt,
      updated_at: createdAt
    };

    getDatabase().prepare(`
      INSERT INTO device_ota_jobs (
        id, tenant_id, device_id, firmware_id, status, requested_by, result_json, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      row.id,
      row.tenant_id,
      row.device_id,
      row.firmware_id,
      row.status,
      row.requested_by,
      row.result_json,
      row.created_at,
      row.updated_at
    );

    await auditLogger.log({
      tenantId: input.tenantId,
      eventType: 'device_ota_dispatched',
      category: 'command',
      severity: accepted ? 'warning' : 'critical',
      actor: { type: 'user', id: input.actorId, email: input.actorEmail, ip: input.actorIp },
      action: 'dispatch_device_ota',
      target: { type: 'server', id: input.deviceId },
      details: {
        otaJobId: id,
        firmwareId: firmware.id,
        version: firmware.version,
        accepted
      },
      status: accepted ? 'success' : 'failure'
    });

    return this.mapOtaRow(row);
  }

  async createPhysicalConfirmation(input: {
    tenantId: string;
    deviceId: string;
    commandType: string;
    payload?: Record<string, any>;
    actorId: string;
    actorEmail?: string;
    actorIp?: string;
  }): Promise<DeviceConfirmationSessionRecord> {
    this.assertPrepared();
    if (!this.gatewayEmitter) {
      throw new Error('backend.device_gateway_unavailable');
    }

    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const payload = input.payload || {};
    const payloadHash = hashPayload(payload);
    const accepted = await this.gatewayEmitter(input.deviceId, 'physical_confirmation_required', {
      confirmationSessionId: id,
      commandType: input.commandType,
      payload,
      payloadHash,
      requestedAt: createdAt,
      prompt: `Press the board confirm key to authorize ${input.commandType}`
    });

    const row = {
      id,
      tenant_id: input.tenantId,
      device_id: input.deviceId,
      command_type: input.commandType,
      payload_json: JSON.stringify(payload),
      status: accepted ? 'pending_physical_confirmation' : 'failed',
      requested_by: input.actorEmail || input.actorId,
      result_json: JSON.stringify({
        accepted
      }),
      created_at: createdAt,
      updated_at: createdAt,
      confirmed_at: null
    };

    getDatabase().prepare(`
      INSERT INTO device_confirmation_sessions (
        id, tenant_id, device_id, command_type, payload_json, status, requested_by, result_json, created_at, updated_at, confirmed_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      row.id,
      row.tenant_id,
      row.device_id,
      row.command_type,
      row.payload_json,
      row.status,
      row.requested_by,
      row.result_json,
      row.created_at,
      row.updated_at,
      row.confirmed_at
    );

    patchDeviceRuntime(input.deviceId, {
      pendingPhysicalApproval: accepted,
      hostActionState: accepted ? 'awaiting_confirmation' : 'failed'
    });

    return this.mapConfirmationRow(row);
  }

  async handleOtaStatus(deviceId: string, payload: Record<string, any>): Promise<void> {
    this.assertPrepared();
    const otaJobId = String(payload?.otaJobId || '').trim();
    if (!otaJobId) {
      return;
    }

    const existing = getDatabase().prepare(`
      SELECT *
      FROM device_ota_jobs
      WHERE id = ? AND device_id = ?
      LIMIT 1
    `).get(otaJobId, deviceId) as any;

    if (!existing) {
      return;
    }

    const nextStatus = String(payload?.status || 'unknown');
    const updatedAt = new Date().toISOString();
    const nextResult = {
      ...parseJson(existing.result_json, {}),
      lastUpdate: payload
    };

    getDatabase().prepare(`
      UPDATE device_ota_jobs
      SET status = ?, result_json = ?, updated_at = ?
      WHERE id = ? AND device_id = ?
    `).run(nextStatus, JSON.stringify(nextResult), updatedAt, otaJobId, deviceId);

    patchDeviceRuntime(deviceId, {
      hostActionState: nextStatus === 'installed' ? 'completed' : nextStatus === 'failed' ? 'failed' : 'running'
    });
  }

  async handlePhysicalConfirmationAck(deviceId: string, payload: Record<string, any>): Promise<void> {
    this.assertPrepared();
    const confirmationSessionId = String(payload?.confirmationSessionId || '').trim();
    if (!confirmationSessionId) {
      return;
    }

    const existing = getDatabase().prepare(`
      SELECT *
      FROM device_confirmation_sessions
      WHERE id = ? AND device_id = ?
      LIMIT 1
    `).get(confirmationSessionId, deviceId) as any;

    if (!existing) {
      return;
    }

    const device = getDeviceById(deviceId);
    const confirmed = Boolean(payload?.confirmed);
    const sessionPayload = parseJson(existing.payload_json, {});
    const payloadHash = hashPayload(sessionPayload);
    const publicKeyPem = device?.physicalAuth?.publicKeyPem;
    const monotonicCounter = Number(payload?.monotonicCounter);
    const timestamp = Number(payload?.timestamp);
    const signature = String(payload?.signature || '').trim();
    const priorCounter = Number(device?.physicalAuth?.monotonicCounter || 0);
    const timestampFresh = Number.isFinite(timestamp) && Math.abs(Date.now() - timestamp) <= 5 * 60 * 1000;
    const counterValid = Number.isFinite(monotonicCounter) && monotonicCounter > priorCounter;

    let verificationReason: string | null = null;
    if (confirmed) {
      if (!publicKeyPem) {
        verificationReason = 'missing_device_public_key';
      } else if (!timestampFresh) {
        verificationReason = 'stale_or_missing_timestamp';
      } else if (!counterValid) {
        verificationReason = 'invalid_monotonic_counter';
      } else if (!signature) {
        verificationReason = 'missing_signature';
      } else {
        const message = buildPhysicalConfirmationMessage({
          deviceId,
          confirmationSessionId,
          commandType: existing.command_type,
          payloadHash,
          monotonicCounter,
          timestamp
        });
        if (!verifySignature(publicKeyPem, message, signature)) {
          verificationReason = 'signature_verification_failed';
        }
      }
    }

    const verified = confirmed && !verificationReason;
    const confirmedAt = verified ? new Date().toISOString() : null;
    const dispatchResult = verified
      ? await commandDispatcherService.dispatchDeviceCommand({
          deviceId,
          commandType: existing.command_type,
          payload: sessionPayload,
          actor: {
            tenantId: existing.tenant_id,
            userId: 'physical-confirmation-gateway',
            email: existing.requested_by,
            ip: 'device-gateway'
          },
          approved: true
        })
      : null;

    const result = {
      ack: payload,
      payloadHash,
      verified,
      verificationReason,
      dispatchResult
    };

    getDatabase().prepare(`
      UPDATE device_confirmation_sessions
      SET status = ?, result_json = ?, updated_at = ?, confirmed_at = ?
      WHERE id = ? AND device_id = ?
    `).run(
      verified ? 'confirmed' : 'rejected',
      JSON.stringify(result),
      new Date().toISOString(),
      confirmedAt,
      confirmationSessionId,
      deviceId
    );

    patchDeviceRuntime(deviceId, {
      pendingPhysicalApproval: false,
      hostActionState: verified
        ? (dispatchResult?.success ? (dispatchResult.status === 'completed' ? 'completed' : 'running') : 'failed')
        : 'failed',
      physicalAuth: verified
        ? {
            monotonicCounter,
            lastConfirmedAt: confirmedAt || undefined
          }
        : undefined
    });

    if (verificationReason) {
      logger.warn('Physical confirmation rejected', {
        deviceId,
        confirmationSessionId,
        verificationReason
      });
    }
  }

  getLatestConfirmationSession(deviceId: string): DeviceConfirmationSessionRecord | null {
    this.assertPrepared();
    const row = getDatabase().prepare(`
      SELECT *
      FROM device_confirmation_sessions
      WHERE device_id = ?
      ORDER BY created_at DESC
      LIMIT 1
    `).get(deviceId) as any;
    return row ? this.mapConfirmationRow(row) : null;
  }

  getFirmware(id: string): DeviceFirmwareRecord | null {
    this.assertPrepared();
    const row = getDatabase().prepare(`
      SELECT *
      FROM device_firmware
      WHERE id = ?
      LIMIT 1
    `).get(id) as any;
    return row ? this.mapFirmwareRow(row) : null;
  }

  private mapFirmwareRow(row: any): DeviceFirmwareRecord {
    return {
      id: row.id,
      tenantId: row.tenant_id,
      fileName: row.file_name,
      version: row.version,
      channel: row.channel,
      artifactRef: row.artifact_ref,
      artifactLocation: row.artifact_location,
      sizeBytes: Number(row.size_bytes || 0),
      notes: row.notes || undefined,
      createdBy: row.created_by,
      createdAt: row.created_at
    };
  }

  private mapOtaRow(row: any): DeviceOtaJobRecord {
    return {
      id: row.id,
      tenantId: row.tenant_id,
      deviceId: row.device_id,
      firmwareId: row.firmware_id,
      status: row.status,
      requestedBy: row.requested_by,
      result: parseJson(row.result_json, {}),
      createdAt: row.created_at,
      updatedAt: row.updated_at
    };
  }

  private mapConfirmationRow(row: any): DeviceConfirmationSessionRecord {
    return {
      id: row.id,
      tenantId: row.tenant_id,
      deviceId: row.device_id,
      commandType: row.command_type,
      payload: parseJson(row.payload_json, {}),
      status: row.status,
      requestedBy: row.requested_by,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      confirmedAt: row.confirmed_at || undefined,
      result: parseJson(row.result_json, {})
    };
  }
}

