import { getDatabase } from '../config/database';
import logger from '../utils/logger';
import { platformConfigService } from './platform-config.service';
import { securityOperationsService } from './security-operations.service';
import { protocolModuleRegistryService } from './protocol-module-registry.service';
import type {
  AgentDeploymentClass,
  AgentNodeKind,
  AgentRuntimeMode,
  AgentRuntimePolicy,
  EdgeFinopsStats,
  ProtocolEvaluateResponse,
  ProtocolModulePolicyEnvelope,
  ProtocolModuleStatsEnvelope,
} from '../types/edge-auto';
import {
  cloneJson,
  DEFAULT_AGENT_RUNTIME_POLICY,
  DEFAULT_EDGE_AUTO_PLATFORM_SETTINGS,
  DEFAULT_EDGE_FINOPS_STATS,
} from '../types/edge-auto';

function parseJson<T>(value: any, fallback: T): T {
  if (!value || typeof value !== 'string') {
    return cloneJson(fallback);
  }
  try {
    return JSON.parse(value) as T;
  } catch {
    return cloneJson(fallback);
  }
}

function clampNumber(value: any, fallback: number, min: number, max: number): number {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return fallback;
  }
  return Math.min(Math.max(numeric, min), max);
}

function normalizeRuntimeMode(value: any, fallback: AgentRuntimeMode = 'normal'): AgentRuntimeMode {
  return value === 'read_only_bypass' ? 'read_only_bypass' : fallback;
}

function normalizeNodeKind(value: any, fallback: AgentNodeKind = 'cloud'): AgentNodeKind {
  return value === 'edge' || value === 'vehicle' ? value : fallback;
}

function normalizeDeploymentClass(value: any, fallback: AgentDeploymentClass = 'standard'): AgentDeploymentClass {
  return value === 'edge' || value === 'vehicle' ? value : fallback;
}

function normalizeRuntimePolicy(raw: any, fallback: AgentRuntimePolicy = DEFAULT_AGENT_RUNTIME_POLICY): AgentRuntimePolicy {
  return {
    cpuCeilingPct: clampNumber(raw?.cpuCeilingPct, fallback.cpuCeilingPct, 1, 100),
    sampleIntervalSec: clampNumber(raw?.sampleIntervalSec, fallback.sampleIntervalSec, 1, 60),
    breachWindowSec: clampNumber(raw?.breachWindowSec, fallback.breachWindowSec, 1, 3600),
    recoveryWindowSec: clampNumber(raw?.recoveryWindowSec, fallback.recoveryWindowSec, 1, 86400),
    autoReadOnlyBypass: typeof raw?.autoReadOnlyBypass === 'boolean' ? raw.autoReadOnlyBypass : fallback.autoReadOnlyBypass,
  };
}

function architectureOf(agent: any): string {
  const direct = String(
    agent?.architecture
      || agent?.status?.architecture
      || agent?.registration?.architecture
      || agent?.registration?.arch
      || agent?.arch
      || '',
  ).trim();
  if (direct) {
    return direct;
  }
  const platform = String(agent?.platform || '').toLowerCase();
  if (platform.includes('arm64') || platform.includes('aarch64')) {
    return 'aarch64';
  }
  if (platform.includes('x64') || platform.includes('amd64')) {
    return 'x86_64';
  }
  return 'unknown';
}

function deploymentClassOf(agent: any): AgentDeploymentClass {
  return normalizeDeploymentClass(
    agent?.deploymentClass
      || agent?.status?.deploymentClass
      || agent?.registration?.deploymentClass
      || (agent?.status?.nodeKind === 'vehicle' ? 'vehicle' : agent?.status?.nodeKind === 'edge' ? 'edge' : 'standard'),
  );
}

function nodeKindOf(agent: any): AgentNodeKind {
  return normalizeNodeKind(
    agent?.nodeKind
      || agent?.status?.nodeKind
      || agent?.registration?.nodeKind
      || (deploymentClassOf(agent) === 'vehicle' ? 'vehicle' : deploymentClassOf(agent) === 'edge' ? 'edge' : 'cloud'),
  );
}

