  prepare(): void {
    if (this.schemaReady) {
      return;
    }

    const db = getDatabase();
    db.exec(`
      CREATE TABLE IF NOT EXISTS agent_runtime_policies (
        tenant_id TEXT NOT NULL,
        agent_id TEXT NOT NULL,
        policy_json TEXT NOT NULL DEFAULT '{}',
        runtime_mode TEXT NOT NULL DEFAULT 'normal',
        updated_by TEXT,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (tenant_id, agent_id)
      );

      CREATE TABLE IF NOT EXISTS agent_protocol_policies (
        tenant_id TEXT NOT NULL,
        agent_id TEXT NOT NULL,
        policy_json TEXT NOT NULL DEFAULT '{}',
        updated_by TEXT,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (tenant_id, agent_id)
      );

      CREATE TABLE IF NOT EXISTS edge_usage_rollups (
        tenant_id TEXT NOT NULL,
        agent_id TEXT NOT NULL,
        node_kind TEXT NOT NULL DEFAULT 'cloud',
        architecture TEXT,
        deployment_class TEXT NOT NULL DEFAULT 'standard',
        protocol_stats_json TEXT NOT NULL DEFAULT '{}',
        finops_stats_json TEXT NOT NULL DEFAULT '{}',
        updated_at TEXT NOT NULL,
        PRIMARY KEY (tenant_id, agent_id)
      );
    `);

    const migrations = [
      `ALTER TABLE agent_runtime_policies ADD COLUMN runtime_mode TEXT NOT NULL DEFAULT 'normal'`,
      `ALTER TABLE edge_usage_rollups ADD COLUMN architecture TEXT`,
      `ALTER TABLE edge_usage_rollups ADD COLUMN deployment_class TEXT NOT NULL DEFAULT 'standard'`,
    ];

    for (const migration of migrations) {
      try {
        db.exec(migration);
      } catch (error: any) {
        if (!String(error?.message || '').includes('duplicate column name')) {
          throw error;
        }
      }
    }

    this.schemaReady = true;
  }

  private assertPrepared(): void {
    if (this.schemaReady) {
      return;
    }

    if (process.env.NODE_ENV === 'test') {
      this.prepare();
      return;
    }

    throw new Error('Edge/Auto schema not initialized. Call edgeAutoService.prepare() during bootstrap.');
  }

  private async getDefaults(tenantId: string) {
    const config = await platformConfigService.getConfig(tenantId);
    return config.edgeAuto || cloneJson(DEFAULT_EDGE_AUTO_PLATFORM_SETTINGS);
  }

  async getRuntimePolicy(tenantId: string, agentId: string): Promise<AgentRuntimePolicy> {
    this.assertPrepared();
    const defaults = await this.getDefaults(tenantId);
    const row = getDatabase().prepare(`
      SELECT policy_json
      FROM agent_runtime_policies
      WHERE tenant_id = ? AND agent_id = ?
      LIMIT 1
    `).get(tenantId, agentId) as any;

    return normalizeRuntimePolicy(parseJson(row?.policy_json, defaults.runtimeDefaults), defaults.runtimeDefaults);
  }

  async getRuntimeMode(tenantId: string, agentId: string): Promise<AgentRuntimeMode> {
    this.assertPrepared();
    const row = getDatabase().prepare(`
      SELECT runtime_mode
      FROM agent_runtime_policies
      WHERE tenant_id = ? AND agent_id = ?
      LIMIT 1
    `).get(tenantId, agentId) as any;

    return normalizeRuntimeMode(row?.runtime_mode, 'normal');
  }

  async saveRuntimePolicy(
    tenantId: string,
    agentId: string,
    rawPolicy: any,
    actorId = 'system',
  ): Promise<AgentRuntimePolicy> {
    this.assertPrepared();
    const current = await this.getRuntimePolicy(tenantId, agentId);
    const currentMode = await this.getRuntimeMode(tenantId, agentId);
    const next = normalizeRuntimePolicy(rawPolicy, current);
    const updatedAt = new Date().toISOString();
    getDatabase().prepare(`
      INSERT INTO agent_runtime_policies (
        tenant_id, agent_id, policy_json, runtime_mode, updated_by, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT(tenant_id, agent_id) DO UPDATE SET
        policy_json = excluded.policy_json,
        runtime_mode = COALESCE(agent_runtime_policies.runtime_mode, excluded.runtime_mode),
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at
    `).run(tenantId, agentId, JSON.stringify(next), currentMode, actorId, updatedAt);
    return next;
  }

  async upsertRuntimeState(
    tenantId: string,
    agentId: string,
    input: {
      runtimeMode?: AgentRuntimeMode;
      runtimePolicy?: AgentRuntimePolicy;
      actorId?: string;
    },
  ): Promise<void> {
    this.assertPrepared();
    const defaults = await this.getDefaults(tenantId);
    const currentPolicy = await this.getRuntimePolicy(tenantId, agentId);
    const currentMode = await this.getRuntimeMode(tenantId, agentId);
    const nextPolicy = normalizeRuntimePolicy(input.runtimePolicy, currentPolicy || defaults.runtimeDefaults);
    const nextMode = normalizeRuntimeMode(input.runtimeMode, currentMode);
    getDatabase().prepare(`
      INSERT INTO agent_runtime_policies (
        tenant_id, agent_id, policy_json, runtime_mode, updated_by, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT(tenant_id, agent_id) DO UPDATE SET
        policy_json = excluded.policy_json,
        runtime_mode = excluded.runtime_mode,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at
    `).run(
      tenantId,
      agentId,
      JSON.stringify(nextPolicy),
      nextMode,
      input.actorId || 'agent-runtime',
      new Date().toISOString(),
    );
  }

  async clearRuntimeBypass(tenantId: string, agentId: string, actorId = 'system'): Promise<AgentRuntimeMode> {
    await this.upsertRuntimeState(tenantId, agentId, {
      runtimeMode: 'normal',
      actorId,
    });
    return 'normal';
  }

  async getProtocolPolicy(tenantId: string, agentId: string): Promise<ProtocolModulePolicyEnvelope> {
    this.assertPrepared();
    const defaults = await this.getDefaults(tenantId);
    const row = getDatabase().prepare(`
      SELECT policy_json
      FROM agent_protocol_policies
      WHERE tenant_id = ? AND agent_id = ?
      LIMIT 1
    `).get(tenantId, agentId) as any;

    return protocolModuleRegistryService.normalizePolicyEnvelope(
      parseJson(row?.policy_json, defaults.protocolDefaults),
      defaults.protocolDefaults,
    );
  }

  async saveProtocolPolicy(
    tenantId: string,
    agentId: string,
    rawPolicy: any,
    actorId = 'system',
  ): Promise<ProtocolModulePolicyEnvelope> {
    this.assertPrepared();
    const current = await this.getProtocolPolicy(tenantId, agentId);
    const next = protocolModuleRegistryService.normalizePolicyEnvelope(rawPolicy, current);
    getDatabase().prepare(`
      INSERT INTO agent_protocol_policies (
        tenant_id, agent_id, policy_json, updated_by, updated_at
      ) VALUES (?, ?, ?, ?, ?)
      ON CONFLICT(tenant_id, agent_id) DO UPDATE SET
        policy_json = excluded.policy_json,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at
    `).run(tenantId, agentId, JSON.stringify(next), actorId, new Date().toISOString());
    return next;
  }

  async getUsageSnapshot(tenantId: string, agentId: string): Promise<{
    protocolStats: ProtocolModuleStatsEnvelope;
    finopsStats: EdgeFinopsStats;
    nodeKind: AgentNodeKind;
    architecture: string;
    deploymentClass: AgentDeploymentClass;
  }> {
    this.assertPrepared();
    const row = getDatabase().prepare(`
      SELECT *
      FROM edge_usage_rollups
      WHERE tenant_id = ? AND agent_id = ?
      LIMIT 1
    `).get(tenantId, agentId) as any;

    return {
      protocolStats: protocolModuleRegistryService.normalizeStatsEnvelope(parseJson(row?.protocol_stats_json, protocolModuleRegistryService.emptyStatsEnvelope())),
      finopsStats: protocolModuleRegistryService.normalizeFinopsStats(parseJson(row?.finops_stats_json, DEFAULT_EDGE_FINOPS_STATS)),
      nodeKind: normalizeNodeKind(row?.node_kind, 'cloud'),
      architecture: String(row?.architecture || 'unknown'),
      deploymentClass: normalizeDeploymentClass(row?.deployment_class, 'standard'),
    };
  }

  async upsertUsageSnapshot(
    tenantId: string,
    agentId: string,
    input: {
      nodeKind?: AgentNodeKind;
      architecture?: string;
      deploymentClass?: AgentDeploymentClass;
      protocolStats?: ProtocolModuleStatsEnvelope;
      finopsStats?: EdgeFinopsStats;
    },
  ): Promise<void> {
    this.assertPrepared();
    const current = await this.getUsageSnapshot(tenantId, agentId);
    const nextProtocolStats = protocolModuleRegistryService.normalizeStatsEnvelope(input.protocolStats, current.protocolStats);
    const nextFinopsStats = protocolModuleRegistryService.normalizeFinopsStats(input.finopsStats, current.finopsStats);
    getDatabase().prepare(`
      INSERT INTO edge_usage_rollups (
        tenant_id, agent_id, node_kind, architecture, deployment_class, protocol_stats_json, finops_stats_json, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(tenant_id, agent_id) DO UPDATE SET
        node_kind = excluded.node_kind,
        architecture = excluded.architecture,
        deployment_class = excluded.deployment_class,
        protocol_stats_json = excluded.protocol_stats_json,
        finops_stats_json = excluded.finops_stats_json,
        updated_at = excluded.updated_at
    `).run(
      tenantId,
      agentId,
      normalizeNodeKind(input.nodeKind, current.nodeKind),
      String(input.architecture || current.architecture || 'unknown'),
      normalizeDeploymentClass(input.deploymentClass, current.deploymentClass),
      JSON.stringify(nextProtocolStats),
      JSON.stringify(nextFinopsStats),
      new Date().toISOString(),
    );
  }

  async syncAgentTelemetry(tenantId: string, agentId: string, heartbeat: any): Promise<void> {
    this.assertPrepared();
    await this.upsertRuntimeState(tenantId, agentId, {
      runtimeMode: normalizeRuntimeMode(heartbeat?.runtimeMode, 'normal'),
      runtimePolicy: heartbeat?.runtimePolicy,
      actorId: 'agent-heartbeat',
    });
    await this.upsertUsageSnapshot(tenantId, agentId, {
      nodeKind: normalizeNodeKind(heartbeat?.nodeKind, 'cloud'),
      architecture: heartbeat?.architecture || heartbeat?.arch || heartbeat?.registration?.arch,
      deploymentClass: normalizeDeploymentClass(heartbeat?.deploymentClass, 'standard'),
      protocolStats: heartbeat?.protocolStats,
      finopsStats: heartbeat?.finopsStats,
    });
  }

  async recordProtocolObservation(input: ProtocolObservationInput): Promise<void> {
    this.assertPrepared();
    const snapshot = await this.getUsageSnapshot(input.tenantId, input.agentId);
    const moduleId = protocolModuleRegistryService.getModuleIdForProtocol(input.protocol);
    const applied = protocolModuleRegistryService.applyObservation(
      moduleId,
      snapshot.protocolStats,
      snapshot.finopsStats,
      {
        response: input.response,
        channel: input.channel,
        sourceRef: input.sourceRef,
        metadata: input.metadata,
        timestamp: new Date().toISOString(),
      },
    );

    for (const translated of applied.translatedFindings) {
      securityOperationsService.syncSignalFinding({
        tenantId: input.tenantId,
        active: true,
        sourceType: 'protocol-observer',
        sourceRef: input.agentId,
        target: input.sourceRef || input.agentId,
        category: translated.category,
        severity: translated.severity,
        title: translated.title,
        description: translated.description,
        evidence: {
          protocol: input.protocol,
          channel: input.channel,
          metadata: input.metadata || {},
          findings: input.response?.findings || [],
        },
        remediation: translated.remediationTitle ? {
          title: translated.remediationTitle,
          owner: translated.remediationOwner || 'operations',
          priority: translated.remediationPriority || 'medium',
          suggestedSteps: translated.remediationSteps || [],
        } : undefined,
        fingerprint: `agent:${input.agentId}:${translated.fingerprint}`,
        createAlert: Boolean(translated.createAlert),
        alertType: translated.alertType || 'security',
      });
    }

    await this.upsertUsageSnapshot(input.tenantId, input.agentId, {
      protocolStats: applied.protocolStats,
      finopsStats: applied.finopsStats,
    });
  }

  async enrichAgent(tenantId: string, agent: any, devices: Array<{ deviceId: string; connectedAgents?: string[] }>): Promise<any> {
    const linkedDeviceIds = devices
      .filter((device) => Array.isArray(device.connectedAgents) && device.connectedAgents.includes(agent.agentId))
      .map((device) => device.deviceId);
    const [runtimePolicy, runtimeMode, protocolPolicy, usage] = await Promise.all([
      this.getRuntimePolicy(tenantId, agent.agentId),
      this.getRuntimeMode(tenantId, agent.agentId),
      this.getProtocolPolicy(tenantId, agent.agentId),
      this.getUsageSnapshot(tenantId, agent.agentId),
    ]);

    return {
      ...agent,
      nodeKind: nodeKindOf(agent),
      architecture: architectureOf(agent),
      deploymentClass: deploymentClassOf(agent),
      linkedDeviceIds,
      runtimePolicy,
      runtimeMode: normalizeRuntimeMode(agent?.status?.runtimeMode || runtimeMode, runtimeMode),
      protocolPolicy,
      protocolStats: protocolModuleRegistryService.normalizeStatsEnvelope(agent?.status?.protocolStats || usage.protocolStats, usage.protocolStats),
      finopsStats: protocolModuleRegistryService.normalizeFinopsStats(agent?.status?.finopsStats || usage.finopsStats, usage.finopsStats),
    };
  }

  async getDashboardSummary(tenantId: string, agents: any[] = []): Promise<Record<string, any>> {
    this.assertPrepared();
    const rows = getDatabase().prepare(`
      SELECT *
      FROM edge_usage_rollups
      WHERE tenant_id = ?
      ORDER BY updated_at DESC
    `).all(tenantId) as any[];

    const rollups = rows.map((row) => ({
      nodeKind: normalizeNodeKind(row.node_kind, 'cloud'),
      architecture: String(row.architecture || 'unknown'),
      deploymentClass: normalizeDeploymentClass(row.deployment_class, 'standard'),
      protocolStats: protocolModuleRegistryService.normalizeStatsEnvelope(parseJson(row.protocol_stats_json, protocolModuleRegistryService.emptyStatsEnvelope())),
      finopsStats: protocolModuleRegistryService.normalizeFinopsStats(parseJson(row.finops_stats_json, DEFAULT_EDGE_FINOPS_STATS)),
    }));

    const liveAgents = Array.isArray(agents) && agents.length > 0 ? agents : [];
    const totalNodes = liveAgents.length > 0 ? liveAgents.length : rollups.length;
    const vehicleNodes = (liveAgents.length > 0 ? liveAgents : rollups).filter((item: any) => nodeKindOf(item) === 'vehicle' || item.nodeKind === 'vehicle').length;
    const edgeNodes = (liveAgents.length > 0 ? liveAgents : rollups).filter((item: any) => nodeKindOf(item) === 'edge' || item.nodeKind === 'edge').length;
    const cloudNodes = Math.max(0, totalNodes - vehicleNodes - edgeNodes);
    const arm64Nodes = (liveAgents.length > 0 ? liveAgents : rollups).filter((item: any) =>
      String(item.architecture || architectureOf(item)).toLowerCase().includes('arm64')
      || String(item.architecture || architectureOf(item)).toLowerCase().includes('aarch64'),
    ).length;
    const bypassRows = getDatabase().prepare(`
      SELECT COUNT(*) AS count
      FROM agent_runtime_policies
      WHERE tenant_id = ? AND runtime_mode = 'read_only_bypass'
    `).get(tenantId) as any;

    const totals = rollups.reduce(
      (acc, rollup) => {
        acc.savedBytes += rollup.finopsStats.savedBytes;
        acc.savedMessages += rollup.finopsStats.savedMessages;
        acc.protocolEvaluations += rollup.protocolStats.totalEvaluations;
        acc.protocolAnomalies += Object.values(rollup.protocolStats.modules || {}).reduce((sum: number, item: any) => sum + Number(item?.findings || 0), 0);
        return acc;
      },
      { savedBytes: 0, savedMessages: 0, protocolEvaluations: 0, protocolAnomalies: 0 },
    );

    const moduleSummaries: Record<string, any> = {};
    for (const rollup of rollups) {
      const next = protocolModuleRegistryService.summarizeModules(rollup.protocolStats, rollup.finopsStats);
      for (const [moduleId, summary] of Object.entries(next)) {
        if (!moduleSummaries[moduleId]) {
          moduleSummaries[moduleId] = summary;
          continue;
        }
        moduleSummaries[moduleId] = {
          ...summary,
          evaluations: Number(moduleSummaries[moduleId].evaluations || 0) + Number((summary as any).evaluations || 0),
          findings: Number(moduleSummaries[moduleId].findings || 0) + Number((summary as any).findings || 0),
          counters: {
            ...(moduleSummaries[moduleId].counters || {}),
            ...Object.entries((summary as any).counters || {}).reduce<Record<string, number>>((acc, [key, value]) => {
              acc[key] = Number(moduleSummaries[moduleId].counters?.[key] || 0) + Number(value || 0);
              return acc;
            }, {}),
          },
          savedBytes: Number(moduleSummaries[moduleId].savedBytes || 0) + Number((summary as any).savedBytes || 0),
          savedMessages: Number(moduleSummaries[moduleId].savedMessages || 0) + Number((summary as any).savedMessages || 0),
          estimatedSavedMb: Number(((Number(moduleSummaries[moduleId].savedBytes || 0) + Number((summary as any).savedBytes || 0)) / (1024 * 1024)).toFixed(3)),
          lastEventAt: moduleSummaries[moduleId].lastEventAt || (summary as any).lastEventAt,
          lastFindingAt: moduleSummaries[moduleId].lastFindingAt || (summary as any).lastFindingAt,
        } as any;
      }
    }

    return {
      totalNodes,
      vehicleNodes,
      edgeNodes,
      cloudNodes,
      arm64Nodes,
      readOnlyBypassNodes: Number(bypassRows?.count || 0),
      mqttSavedBytes: Number(moduleSummaries.mqtt?.savedBytes || 0),
      mqttSavedMessages: Number(moduleSummaries.mqtt?.savedMessages || 0),
      mqttSavedMb: Number(moduleSummaries.mqtt?.estimatedSavedMb || 0),
      protocolEvaluations: totals.protocolEvaluations,
      protocolAnomalies: totals.protocolAnomalies,
      modules: moduleSummaries,
      updatedAt: new Date().toISOString(),
    };
  }
}

export const edgeAutoService = new EdgeAutoService();

import http from 'http';
import https from 'https';
import axios, { AxiosInstance } from 'axios';
import { platformConfigService } from './platform-config.service';
import logger from '../utils/logger';
import {
  HttpTrafficEvaluateRequest,
  HttpTrafficEvaluateResponse,
  HttpTrafficThreat
} from './http-traffic-evaluator.service';
import type {
  ProtocolEvaluateRequest,
  ProtocolEvaluateResponse,
  ProtocolFinding,
} from '../types/edge-auto';

export interface FastpathCheckRequest {
  tenantId?: string;
  key: string;
  windowMs: number;
  limit: number;
  sourceIp?: string;
  sessionId?: string;
  headers?: Record<string, any>;
  protocol?: string;
}

export interface FastpathCheckResponse {
  allowed: boolean;
  remaining: number;
  resetAt: string;
  resetAtMs: number;
  decisionSource: string;
  riskFlags: string[];
}

export interface FastpathRuntimeSettings {
  tenantId: string;
  enabled: boolean;
  baseUrl: string;
  transport: 'tcp' | 'unix';
  socketPath: string | null;
  timeoutMs: number;
  fallbackEnabled: boolean;
  trafficShadowEnabled: boolean;
  trafficShadowSampleRatePct: number;
  trafficMaxBodyBytes: number;
}

export type { ProtocolEvaluateRequest, ProtocolEvaluateResponse, ProtocolFinding };

function normalizeTransport(value: unknown): FastpathRuntimeSettings['transport'] {
  return String(value || '').trim().toLowerCase() === 'unix' ? 'unix' : 'tcp';
}

class FastpathClientService {
  private readonly clients = new Map<string, AxiosInstance>();
  private readonly httpAgent = new http.Agent({
    keepAlive: true,
    maxSockets: 512,
    maxFreeSockets: 64
  });
  private readonly httpsAgent = new https.Agent({
    keepAlive: true,
    maxSockets: 512,
    maxFreeSockets: 64
  });

  async getRuntimeSettings(tenantId = 'global'): Promise<FastpathRuntimeSettings> {
    const config = await platformConfigService.getConfig(tenantId);
    const baseUrl = String(process.env.FASTPATH_URL || config.fastpath.baseUrl || 'http://fastpath:8081').trim();
    const socketPath = String(process.env.FASTPATH_SOCKET_PATH || config.fastpath.socketPath || '').trim() || null;
    const requestedTransport = normalizeTransport(process.env.FASTPATH_TRANSPORT || config.fastpath.transport);
    const transport = requestedTransport === 'unix' && socketPath ? 'unix' : 'tcp';
    const timeoutMs = Number(process.env.FASTPATH_TIMEOUT_MS || config.fastpath.timeoutMs || 1500);

    return {
      tenantId,
      enabled: config.fastpath.enabled,
      baseUrl,
      transport,
      socketPath,
      timeoutMs: Number.isFinite(timeoutMs) ? Math.max(timeoutMs, 100) : config.fastpath.timeoutMs,
      fallbackEnabled: config.fastpath.fallbackEnabled,
      trafficShadowEnabled: config.fastpath.trafficShadowEnabled,
      trafficShadowSampleRatePct: config.fastpath.trafficShadowSampleRatePct,
      trafficMaxBodyBytes: config.fastpath.trafficMaxBodyBytes
    };
  }

  async health(tenantId = 'global'): Promise<boolean> {
    const runtime = await this.getRuntimeSettings(tenantId);
    if (!runtime.enabled) {
      return false;
    }

    try {
      const client = this.getClient(runtime);
      const response = await client.get('/healthz');
      return response.status < 400;
    } catch {
      return false;
    }
  }

  async checkRate(input: FastpathCheckRequest): Promise<FastpathCheckResponse | null> {
    return this.check('/v1/rate/check', input);
  }

  async checkSocket(input: FastpathCheckRequest): Promise<FastpathCheckResponse | null> {
    return this.check('/v1/socket/check', input);
  }

  async flush(tenantId = 'global'): Promise<Record<string, any> | null> {
    const runtime = await this.getRuntimeSettings(tenantId);
    if (!runtime.enabled) {
      return null;
    }

    try {
      const response = await this.getClient(runtime).post('/v1/batch/flush', { tenantId });
      return response.data;
    } catch (error: any) {
      logger.warn('Fastpath flush unavailable', {
        tenantId,
        error: error?.message
      });
      return null;
    }
  }

  async evaluateHttpTraffic(input: HttpTrafficEvaluateRequest): Promise<HttpTrafficEvaluateResponse | null> {
    const tenantId = input.tenantId || 'global';
    const result = await this.postRaw(tenantId, '/v1/traffic/http/evaluate', input as unknown as Record<string, any>);
    if (!result) {
      return null;
    }

    if (result.status >= 400) {
      logger.warn('Fastpath HTTP traffic evaluation returned non-success status', {
        tenantId,
        requestId: input.requestId,
        status: result.status
      });
      return null;
    }

    const threats = Array.isArray(result.data?.threats)
      ? result.data.threats.map((threat: any): HttpTrafficThreat => ({
          type: String(threat?.type || 'unknown'),
          severity: ['low', 'medium', 'high', 'critical'].includes(String(threat?.severity || ''))
            ? threat.severity
            : 'medium',
          description: String(threat?.description || '')
        }))
      : [];

    return {
      protocol: 'http',
      verdict: result.data?.verdict === 'block' ? 'block' : 'allow',
      matchedRule: result.data?.matchedRule ? String(result.data.matchedRule) : null,
      threats,
      truncated: Boolean(result.data?.truncated ?? input.truncated),
      decisionSource: String(result.data?.decisionSource || 'rust-fastpath-traffic-http'),
      processingTimeMicros: Number(result.data?.processingTimeMicros || 0)
    };
  }

  async evaluateProtocol(input: ProtocolEvaluateRequest): Promise<ProtocolEvaluateResponse | null> {
    const tenantId = input.tenantId || 'global';
    const result = await this.postRaw(tenantId, '/v1/traffic/protocol/evaluate', input as unknown as Record<string, any>);
    if (!result || result.status >= 400) {
      return null;
    }

    return {
      protocol: result.data?.protocol || input.protocol,
      verdict: result.data?.verdict || 'allow',
      action: result.data?.action || 'inspect',
      matchedRule: typeof result.data?.matchedRule === 'string' ? result.data.matchedRule : null,
      findings: Array.isArray(result.data?.findings) ? result.data.findings : [],
      decisionSource: String(result.data?.decisionSource || 'rust-fastpath-protocol'),
      processingTimeMicros: Number(result.data?.processingTimeMicros || 0),
      costMetrics: result.data?.costMetrics && typeof result.data.costMetrics === 'object' ? result.data.costMetrics : {}
    } as ProtocolEvaluateResponse;
  }

  async postRaw(
    tenantId: string,
    path: string,
    payload: Record<string, any>
  ): Promise<{ status: number; data: any } | null> {
    const runtime = await this.getRuntimeSettings(tenantId);
    if (!runtime.enabled) {
      return null;
    }

    try {
      const response = await this.getClient(runtime).post(path, payload);
      return {
        status: response.status,
        data: response.data
      };
    } catch (error: any) {
      if (!runtime.fallbackEnabled) {
        throw error;
      }
      logger.warn('Fastpath raw request unavailable', {
        tenantId,
        path,
        error: error?.message
      });
      return null;
    }
  }

  private async check(path: string, input: FastpathCheckRequest): Promise<FastpathCheckResponse | null> {
    const tenantId = input.tenantId || 'global';
    const runtime = await this.getRuntimeSettings(tenantId);
    if (!runtime.enabled) {
      return null;
    }

    try {
      const response = await this.getClient(runtime).post(path, {
        tenantId,
        key: input.key,
        windowMs: input.windowMs,
        limit: input.limit,
        sourceIp: input.sourceIp,
        sessionId: input.sessionId,
        headers: input.headers || {},
        protocol: input.protocol || 'http'
      });

      if (response.status >= 400) {
        throw new Error(`fastpath status ${response.status}`);
      }

      const resetAtMs = Number(response.data?.resetAtMs || 0) || (Date.now() + input.windowMs);
      const resetAt = String(response.data?.resetAt || new Date(resetAtMs).toISOString());

      return {
        allowed: Boolean(response.data?.allowed),
        remaining: Number(response.data?.remaining || 0),
        resetAt,
        resetAtMs,
        decisionSource: String(response.data?.decisionSource || 'fastpath'),
        riskFlags: Array.isArray(response.data?.riskFlags) ? response.data.riskFlags : []
      };
    } catch (error: any) {
      if (!runtime.fallbackEnabled) {
        throw error;
      }
      logger.warn('Fastpath unavailable, falling back to local limiter', {
        tenantId,
        path,
        error: error?.message
      });
      return null;
    }
  }

  private getClient(runtime: FastpathRuntimeSettings): AxiosInstance {
    const key = [
      runtime.transport,
      runtime.transport === 'unix' ? runtime.socketPath || 'missing-socket' : runtime.baseUrl,
      runtime.timeoutMs
    ].join('|');

    const existing = this.clients.get(key);
    if (existing) {
      return existing;
    }

    const client = axios.create({
      baseURL: runtime.transport === 'unix' ? 'http://unix' : runtime.baseUrl,
      timeout: runtime.timeoutMs,
      socketPath: runtime.transport === 'unix' ? runtime.socketPath || undefined : undefined,
      httpAgent: this.httpAgent,
      httpsAgent: this.httpsAgent,
      validateStatus: () => true
    });

    this.clients.set(key, client);
    return client;
  }
}

