interface ProtocolShadowTask {
  tenantId: string;
  protocol: string;
  requestId: string;
  url: string;
  protocolRequest: ProtocolEvaluateRequest;
  baseline: ProtocolEvaluateResponse;
}

interface FastpathShadowWorkerConfig {
  concurrency: number;
  maxQueueSize: number;
}

const DEFAULT_WORKER_CONFIG: FastpathShadowWorkerConfig = {
  concurrency: 2,
  maxQueueSize: 512
};

function normalizeHeaderValue(value: unknown): string {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '')).join(', ');
  }
  return String(value ?? '');
}

function normalizeHeaders(headers: Record<string, unknown>): Record<string, string> {
  return Object.entries(headers || {}).reduce<Record<string, string>>((acc, [key, value]) => {
    if (!key) {
      return acc;
    }
    acc[key.toLowerCase()] = normalizeHeaderValue(value);
    return acc;
  }, {});
}

function normalizeHttpVersion(version: string): string {
  const trimmed = String(version || '').trim();
  if (!trimmed) {
    return 'HTTP/1.1';
  }
  if (/^HTTP\//i.test(trimmed)) {
    return trimmed.toUpperCase();
  }
  return `HTTP/${trimmed}`;
}

function isTextualContentType(contentType: string): boolean {
  const normalized = contentType.toLowerCase();
  return (
    normalized.includes('application/json') ||
    normalized.includes('application/x-www-form-urlencoded') ||
    normalized.startsWith('text/')
  );
}

function isSkippedRequest(req: Request, contentType: string): boolean {
  if (req.method === 'OPTIONS') {
    return true;
  }

  const path = req.path || req.originalUrl || '';
  if (path === '/health' || path === '/api/health') {
    return true;
  }

  const normalized = contentType.toLowerCase();
  return normalized.startsWith('multipart/') || normalized.includes('application/octet-stream');
}

function resolveSourceIp(req: Request): string {
  return String(
    req.ip ||
    req.socket?.remoteAddress ||
    (req.connection as any)?.remoteAddress ||
    ''
  ).trim();
}

function fallbackBodyBytes(req: Request): Buffer {
  if (Buffer.isBuffer((req as any).rawBody)) {
    return Buffer.from((req as any).rawBody);
  }

  if (typeof req.body === 'string') {
    return Buffer.from(req.body, 'utf8');
  }

  if (req.body && typeof req.body === 'object' && !Buffer.isBuffer(req.body)) {
    return Buffer.from(JSON.stringify(req.body), 'utf8');
  }

  return Buffer.alloc(0);
}

function buildSnapshot(req: Request): PendingHttpSnapshot | null {
  const contentType = String(req.headers['content-type'] || '').trim();
  if (isSkippedRequest(req, contentType)) {
    return null;
  }

  if (contentType && !isTextualContentType(contentType)) {
    return {
      tenantId: (req as any).user?.tenantId || 'global',
      requestId: String(req.headers['x-request-id'] || randomUUID()),
      method: req.method,
      url: req.originalUrl || req.url || '/',
      httpVersion: normalizeHttpVersion(req.httpVersion),
      headers: normalizeHeaders(req.headers as Record<string, unknown>),
      rawBody: Buffer.alloc(0),
      sourceIp: resolveSourceIp(req),
      contentType
    };
  }

  return {
    tenantId: (req as any).user?.tenantId || 'global',
    requestId: String(req.headers['x-request-id'] || randomUUID()),
    method: req.method,
    url: req.originalUrl || req.url || '/',
    httpVersion: normalizeHttpVersion(req.httpVersion),
    headers: normalizeHeaders(req.headers as Record<string, unknown>),
    rawBody: fallbackBodyBytes(req),
    sourceIp: resolveSourceIp(req),
    contentType
  };
}

function toHttpProtocolFindingSignatures(findings: ProtocolFinding[]): string[] {
  return Array.from(
    new Set((findings || []).map((finding) => `${String(finding?.code || 'unknown')}:${String(finding?.severity || 'medium')}`))
  ).sort();
}

function buildHttpShadowTask(snapshot: PendingHttpSnapshot, maxBodyBytes: number): ProtocolShadowTask {
  const rawBody = snapshot.rawBody.subarray(0, maxBodyBytes);
  const truncated = snapshot.rawBody.length > rawBody.length;
  const httpRequest: HttpTrafficEvaluateRequest = {
    tenantId: snapshot.tenantId,
    requestId: snapshot.requestId,
    method: snapshot.method,
    url: snapshot.url,
    httpVersion: snapshot.httpVersion,
    headers: snapshot.headers,
    bodyBase64: rawBody.toString('base64'),
    sourceIp: snapshot.sourceIp,
    truncated
  };
  const baseline = httpTrafficEvaluatorService.evaluateBaseline(httpRequest);

  return {
    tenantId: snapshot.tenantId,
    protocol: 'http',
    requestId: snapshot.requestId,
    url: snapshot.url,
    protocolRequest: {
      tenantId: snapshot.tenantId,
      requestId: snapshot.requestId,
      protocol: 'http',
      direction: 'ingress',
      sourceRef: snapshot.sourceIp,
      channel: snapshot.url,
      headers: snapshot.headers,
      metadata: {
        method: snapshot.method,
        url: snapshot.url,
        httpVersion: snapshot.httpVersion,
        sourceIp: snapshot.sourceIp,
        contentType: snapshot.contentType
      },
      payloadBase64: httpRequest.bodyBase64,
      truncated,
      timestamp: new Date().toISOString()
    },
    baseline: {
      protocol: 'http',
      verdict: baseline.verdict === 'block' ? 'block' : 'allow',
      action: baseline.verdict === 'block' ? 'block' : 'inspect',
      matchedRule: baseline.matchedRule,
      findings: baseline.threats.map((threat) => ({
        code: threat.type,
        severity: threat.severity,
        message: threat.description
      })),
      decisionSource: baseline.decisionSource,
      processingTimeMicros: baseline.processingTimeMicros,
      costMetrics: {}
    }
  };
}

class FastpathTrafficShadowService {
  private readonly queue: ProtocolShadowTask[] = [];
  private readonly workerConfig: FastpathShadowWorkerConfig = { ...DEFAULT_WORKER_CONFIG };
  private activeWorkers = 0;
  private pendingSubmissions = 0;
  private idleResolvers: Array<() => void> = [];

  submitFromRequest(req: Request): void {
    const snapshot = buildSnapshot(req);
    if (!snapshot) {
      return;
    }

    this.pendingSubmissions += 1;
    void this.maybeQueueSnapshot(snapshot).finally(() => {
      this.pendingSubmissions = Math.max(0, this.pendingSubmissions - 1);
      this.resolveIdle();
    });
  }

  resetForTests(): void {
    this.queue.length = 0;
    this.activeWorkers = 0;
    this.pendingSubmissions = 0;
    this.workerConfig.concurrency = DEFAULT_WORKER_CONFIG.concurrency;
    this.workerConfig.maxQueueSize = DEFAULT_WORKER_CONFIG.maxQueueSize;
    this.resolveIdle();
  }

  setWorkerConfigForTests(config: Partial<FastpathShadowWorkerConfig>): void {
    if (typeof config.concurrency === 'number') {
      this.workerConfig.concurrency = Math.max(0, Math.floor(config.concurrency));
    }
    if (typeof config.maxQueueSize === 'number') {
      this.workerConfig.maxQueueSize = Math.max(1, Math.floor(config.maxQueueSize));
    }
  }

  async awaitIdleForTests(): Promise<void> {
    if (this.queue.length === 0 && this.activeWorkers === 0 && this.pendingSubmissions === 0) {
      return;
    }

    await new Promise<void>((resolve) => {
      this.idleResolvers.push(resolve);
    });
  }

  private async maybeQueueSnapshot(snapshot: PendingHttpSnapshot): Promise<void> {
    try {
      const config = await platformConfigService.getConfig(snapshot.tenantId);
      if (!config.fastpath.enabled || !config.fastpath.trafficShadowEnabled) {
        return;
      }

      const sampleRatePct = Math.max(0, Math.min(100, Number(config.fastpath.trafficShadowSampleRatePct || 0)));
      if (sampleRatePct <= 0) {
        return;
      }

      const sampleBucket = hashTrafficSampleKey({
        tenantId: snapshot.tenantId,
        requestId: snapshot.requestId,
        method: snapshot.method,
        url: snapshot.url
      });
      if (sampleBucket >= sampleRatePct) {
        return;
      }

      const maxBodyBytes = Math.max(0, Number(config.fastpath.trafficMaxBodyBytes || 65536));
      this.enqueue(buildHttpShadowTask(snapshot, maxBodyBytes));
    } catch (error: any) {
      logger.warn('fastpath_traffic_shadow_error', {
        tenantId: snapshot.tenantId,
        requestId: snapshot.requestId,
        url: snapshot.url,
        error: error?.message || 'shadow_config_error'
      });
    }
  }

  private enqueue(task: ProtocolShadowTask): void {
    if (this.queue.length >= this.workerConfig.maxQueueSize) {
      logger.warn('fastpath_traffic_shadow_dropped', {
        tenantId: task.tenantId,
        requestId: task.requestId,
        url: task.url,
        protocol: task.protocol,
        queueDepth: this.queue.length,
        maxQueueSize: this.workerConfig.maxQueueSize
      });
      return;
    }

    this.queue.push(task);
    this.drain();
  }

  private drain(): void {
    while (this.activeWorkers < this.workerConfig.concurrency && this.queue.length > 0) {
      const task = this.queue.shift();
      if (!task) {
        break;
      }

      this.activeWorkers += 1;
      void this.processTask(task).finally(() => {
        this.activeWorkers = Math.max(0, this.activeWorkers - 1);
        this.drain();
        this.resolveIdle();
      });
    }

    this.resolveIdle();
  }

  private async processTask(task: ProtocolShadowTask): Promise<void> {
    const fastpath = await fastpathClientService.evaluateProtocol(task.protocolRequest);

    if (!fastpath) {
      logger.warn('fastpath_traffic_shadow_error', {
        tenantId: task.tenantId,
        requestId: task.requestId,
        url: task.url,
        protocol: task.protocol,
        error: 'fastpath_unavailable'
      });
      return;
    }

    const baselineFindings = toHttpProtocolFindingSignatures(task.baseline.findings);
    const fastpathFindings = toHttpProtocolFindingSignatures(fastpath.findings);
    const mismatch =
      task.baseline.verdict !== fastpath.verdict ||
      baselineFindings.join('|') !== fastpathFindings.join('|');

    if (mismatch) {
      logger.warn('fastpath_traffic_shadow_mismatch', {
        tenantId: task.tenantId,
        requestId: task.requestId,
        url: task.url,
        protocol: task.protocol,
        baselineVerdict: task.baseline.verdict,
        fastpathVerdict: fastpath.verdict,
        baselineMatchedRule: task.baseline.matchedRule,
        fastpathMatchedRule: fastpath.matchedRule,
        baselineFindings,
        fastpathFindings,
        truncated: Boolean(task.protocolRequest.truncated)
      });
    }
  }

  private resolveIdle(): void {
    if (this.queue.length > 0 || this.activeWorkers > 0 || this.pendingSubmissions > 0) {
      return;
    }

    while (this.idleResolvers.length > 0) {
      const resolve = this.idleResolvers.shift();
      resolve?.();
    }
  }
}

export const fastpathTrafficShadowService = new FastpathTrafficShadowService();

import { Buffer } from 'buffer';
import { createHash } from 'crypto';
import { ProtocolParser, ThreatIndicator } from '../traffic-interceptor/processing/protocol-parser';

export type HttpTrafficVerdict = 'allow' | 'block';

export interface HttpTrafficEvaluateRequest {
  tenantId: string;
  requestId: string;
  method: string;
  url: string;
  httpVersion: string;
  headers: Record<string, string>;
  bodyBase64: string;
  sourceIp?: string;
  truncated: boolean;
}

export interface HttpTrafficThreat {
  type: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
}

export interface HttpTrafficEvaluateResponse {
  protocol: 'http';
  verdict: HttpTrafficVerdict;
  matchedRule: string | null;
  threats: HttpTrafficThreat[];
  truncated: boolean;
  decisionSource: string;
  processingTimeMicros: number;
}

export interface HttpTrafficBenchmarkFixture {
  name: string;
  request: HttpTrafficEvaluateRequest;
  expectedVerdict: HttpTrafficVerdict;
  expectsCriticalBlock: boolean;
}

const protocolParser = new ProtocolParser();

const GENERIC_CRITICAL_PATTERNS: Array<{ pattern: RegExp; type: string }> = [
  { pattern: /'\s*or\s+'1'\s*=\s*'1/gi, type: 'sql_injection' },
  { pattern: /;\s*drop\s+table/gi, type: 'sql_injection' },
  { pattern: /<script[\s\S]*?>[\s\S]*?<\/script>/gi, type: 'xss' },
  { pattern: /\.\.\/\.\.\/\.\.\/etc\/passwd/gi, type: 'path_traversal' }
];

function normalizeHttpVersion(version: string): string {
  const trimmed = String(version || '').trim();
  if (!trimmed) {
    return 'HTTP/1.1';
  }
  if (/^HTTP\//i.test(trimmed)) {
    return trimmed.toUpperCase();
  }
  return `HTTP/${trimmed}`;
}

function decodeBody(bodyBase64: string): Buffer {
  if (!bodyBase64) {
    return Buffer.alloc(0);
  }
  try {
    return Buffer.from(bodyBase64, 'base64');
  } catch {
    return Buffer.alloc(0);
  }
}

function normalizeHeaders(headers: Record<string, unknown>): Record<string, string> {
  return Object.entries(headers || {}).reduce<Record<string, string>>((acc, [key, value]) => {
    if (!key) {
      return acc;
    }

    if (Array.isArray(value)) {
      acc[key.toLowerCase()] = value.map((item) => String(item ?? '')).join(', ');
      return acc;
    }

    acc[key.toLowerCase()] = String(value ?? '');
    return acc;
  }, {});
}

function buildRawHttpPayload(input: HttpTrafficEvaluateRequest): Buffer {
  const body = decodeBody(input.bodyBase64);
  const startLine = `${String(input.method || '').trim()} ${String(input.url || '').trim()} ${normalizeHttpVersion(input.httpVersion)}\r\n`;
  const headerLines = Object.entries(normalizeHeaders(input.headers || {}))
    .map(([key, value]) => `${key}: ${value}`)
    .join('\r\n');
  const headerBlock = headerLines ? `${startLine}${headerLines}\r\n\r\n` : `${startLine}\r\n`;
  return Buffer.concat([Buffer.from(headerBlock, 'utf8'), body]);
}

function mapThreat(threat: ThreatIndicator): HttpTrafficThreat {
  return {
    type: threat.type,
    severity: threat.severity,
    description: threat.description
  };
}

function dedupeThreats(threats: HttpTrafficThreat[]): HttpTrafficThreat[] {
  const seen = new Set<string>();
  return threats.filter((threat) => {
    const key = `${threat.type}|${threat.severity}|${threat.description}`;
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function detectGenericCriticalThreats(content: string): HttpTrafficThreat[] {
  const threats: HttpTrafficThreat[] = [];
  for (const { pattern, type } of GENERIC_CRITICAL_PATTERNS) {
    if (pattern.test(content)) {
      threats.push({
        type,
        severity: 'critical',
        description: `Critical threat detected: ${type}`
      });
    }
  }
  return threats;
}

function detectHeaderInjection(headers: Record<string, string>): HttpTrafficThreat[] {
  return Object.entries(headers).flatMap(([key, value]) => {
    if (!value.includes('\r\n') && !value.includes('\n')) {
      return [];
    }

    return [{
      type: 'header_injection',
      severity: 'high' as const,
      description: `Header injection in ${key}`
    }];
  });
}

function buildFixtureRequest(
  name: string,
  partial: Partial<HttpTrafficEvaluateRequest> & {
    expectedVerdict?: HttpTrafficVerdict;
    expectsCriticalBlock?: boolean;
  }
): HttpTrafficBenchmarkFixture {
  const body = partial.bodyBase64
    ? partial.bodyBase64
    : Buffer.from(String((partial as any).bodyText || ''), 'utf8').toString('base64');
  const request: HttpTrafficEvaluateRequest = {
    tenantId: 'global',
    requestId: `fixture:${name}`,
    method: partial.method || 'GET',
    url: partial.url || '/',
    httpVersion: partial.httpVersion || 'HTTP/1.1',
    headers: normalizeHeaders(partial.headers || { host: 'example.test' }),
    bodyBase64: body,
    sourceIp: partial.sourceIp || '127.0.0.1',
    truncated: Boolean(partial.truncated)
  };

  const expectedVerdict = partial.expectedVerdict || 'allow';

  return {
    name,
    request,
    expectedVerdict,
    expectsCriticalBlock: partial.expectsCriticalBlock ?? expectedVerdict === 'block'
  };
}

