      host: 'example.test',
      'content-type': 'application/json'
    },
    bodyBase64: ''
  }),
  buildFixtureRequest('truncated-long-body', {
    method: 'POST',
    url: '/upload',
    headers: {
      host: 'example.test',
      'content-type': 'text/plain'
    },
    bodyBase64: Buffer.from('A'.repeat(65536), 'utf8').toString('base64'),
    truncated: true
  })
];

export function normalizeThreatSignatures(threats: HttpTrafficThreat[]): string[] {
  return Array.from(new Set(threats.map((threat) => `${threat.type}:${threat.severity}`))).sort();
}

export function hashTrafficSampleKey(input: Pick<HttpTrafficEvaluateRequest, 'tenantId' | 'requestId' | 'url' | 'method'>): number {
  const hash = createHash('sha1')
    .update(`${input.tenantId}|${input.requestId}|${input.method}|${input.url}`)
    .digest();
  return hash.readUInt32BE(0) % 100;
}

class HttpTrafficEvaluatorService {
  evaluateBaseline(input: HttpTrafficEvaluateRequest): HttpTrafficEvaluateResponse {
    const startedAt = process.hrtime.bigint();
    const payload = buildRawHttpPayload(input);
    const payloadString = payload.toString('utf8');
    const httpResult = protocolParser.parseHTTP(payload);
    const httpThreats = httpResult.threats.map(mapThreat);
    const headerThreats = detectHeaderInjection(normalizeHeaders(input.headers || {}));
    const genericThreats = detectGenericCriticalThreats(payloadString);
    const threats = dedupeThreats([...httpThreats, ...headerThreats, ...genericThreats]);

    let verdict: HttpTrafficVerdict = 'allow';
    let matchedRule: string | null = null;

    const criticalHttpThreat = httpThreats.find((threat) => threat.severity === 'critical');
    if (criticalHttpThreat) {
      verdict = 'block';
      matchedRule = `fast_path:${criticalHttpThreat.type}`;
    } else if (genericThreats.some((threat) => threat.severity === 'critical')) {
      verdict = 'block';
      matchedRule = 'fast_path:critical_threat';
    }

    return {
      protocol: 'http',
      verdict,
      matchedRule,
      threats,
      truncated: Boolean(input.truncated),
      decisionSource: 'typescript-http-baseline',
      processingTimeMicros: Number((process.hrtime.bigint() - startedAt) / 1000n)
    };
  }
}

export const httpTrafficEvaluatorService = new HttpTrafficEvaluatorService();

﻿/**
 * Investigation Service
 *
 * Handles persistence and retrieval of investigation data.
 */

import Database, { Database as SqlJsDatabase } from 'better-sqlite3';
import {
  BugReport,
  InvestigationContext,
  InvestigationResult
} from '../ai-agents/investigation/types';
import { getDatabase, initDatabase } from '../config/database';
import logger from '../utils/logger';

export interface InvestigationRecord {
  investigationId: string;
  bugReportId: string;
  bugReport: BugReport;
  context: InvestigationContext;
  result?: InvestigationResult;
  createdAt: Date;
  status: 'in_progress' | 'completed' | 'failed';
}

type RawRow = Record<string, unknown>;

export class InvestigationService {
  private initialized = false;
  private initPromise: Promise<void> | null = null;

  private async ensureInitialized(): Promise<void> {
    if (this.initialized) {
      return;
    }

    if (!this.initPromise) {
      this.initPromise = this.initialize();
    }

    await this.initPromise;
  }

  private async initialize(): Promise<void> {
    await initDatabase();
    const db = this.getDb();

    db.run(`
      CREATE TABLE IF NOT EXISTS investigations (
        investigation_id TEXT PRIMARY KEY,
        bug_report_id TEXT NOT NULL,
        bug_report TEXT NOT NULL,
        context TEXT NOT NULL,
        result TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        status TEXT NOT NULL,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    db.run(`
      CREATE INDEX IF NOT EXISTS idx_investigations_created_at
      ON investigations(created_at)
    `);

    db.run(`
      CREATE INDEX IF NOT EXISTS idx_investigations_status
      ON investigations(status)
    `);

    this.persist();
    this.initialized = true;
    logger.info('InvestigationService storage initialized');
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private getDb(): any {
    return getDatabase().getDb();
  }

  private persist(): void {
    getDatabase().save();
  }

  /**
   * Save investigation to database
   */
  public async saveInvestigation(data: InvestigationRecord): Promise<void> {
    await this.ensureInitialized();
    const db = this.getDb();

    db.run(
      `
      INSERT OR REPLACE INTO investigations
      (investigation_id, bug_report_id, bug_report, context, result, created_at, status, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
      `,
      [
        data.investigationId,
        data.bugReportId,
        JSON.stringify(data.bugReport),
        JSON.stringify(data.context),
        data.result ? JSON.stringify(data.result) : null,
        data.createdAt.toISOString(),
        data.status
      ]
    );

    this.persist();
    logger.info(`[InvestigationService] Saved investigation ${data.investigationId}`);
  }

  /**
   * Get investigation by ID
   */
  public async getInvestigation(investigationId: string): Promise<InvestigationRecord | null> {
    await this.ensureInitialized();
    const db = this.getDb();
    const stmt = db.prepare('SELECT * FROM investigations WHERE investigation_id = ? LIMIT 1');

    stmt.bind([investigationId]);
    const row = stmt.step() ? (stmt.getAsObject() as RawRow) : null;
    stmt.free();

    return row ? this.deserializeRow(row) : null;
  }

  /**
   * Get investigation history
   */
  public async getInvestigationHistory(options: {
    limit?: number;
    offset?: number;
    severity?: string;
    category?: string;
  }): Promise<{ investigations: InvestigationRecord[]; total: number }> {
    await this.ensureInitialized();
    const db = this.getDb();
    const stmt = db.prepare('SELECT * FROM investigations ORDER BY created_at DESC');

    const rows: InvestigationRecord[] = [];
    while (stmt.step()) {
      rows.push(this.deserializeRow(stmt.getAsObject() as RawRow));
    }
    stmt.free();

    let filtered = rows;
    if (options.severity) {
      filtered = filtered.filter(r => r.bugReport.severity === options.severity);
    }
    if (options.category) {
      filtered = filtered.filter(r => r.bugReport.category === options.category);
    }

    const total = filtered.length;
    const offset = Math.max(0, options.offset || 0);
    const limit = Math.max(1, options.limit || 50);
    const investigations = filtered.slice(offset, offset + limit);

    return { investigations, total };
  }

  /**
   * Delete investigation
   */
  public async deleteInvestigation(investigationId: string): Promise<void> {
    await this.ensureInitialized();
    const db = this.getDb();

    db.run('DELETE FROM investigations WHERE investigation_id = ?', [investigationId]);
    this.persist();
    logger.info(`[InvestigationService] Deleted investigation ${investigationId}`);
  }

  /**
   * Update investigation status
   */
  public async updateInvestigationStatus(
    investigationId: string,
    status: 'in_progress' | 'completed' | 'failed'
  ): Promise<void> {
    await this.ensureInitialized();
    const db = this.getDb();

    db.run(
      `
      UPDATE investigations
      SET status = ?, updated_at = datetime('now')
      WHERE investigation_id = ?
      `,
      [status, investigationId]
    );

    this.persist();
  }

  /**
   * Deserialize database row to InvestigationRecord
   */
  private deserializeRow(row: RawRow): InvestigationRecord {
    const bugReport = this.parseJson<BugReport>(row.bug_report);
    const context = this.parseJson<InvestigationContext>(row.context);
    const result = this.parseJson<InvestigationResult | undefined>(row.result);

    return {
      investigationId: String(row.investigation_id || ''),
      bugReportId: String(row.bug_report_id || bugReport?.id || ''),
      bugReport,
      context,
      result,
      createdAt: new Date(String(row.created_at || new Date().toISOString())),
      status: this.parseStatus(row.status)
    };
  }

  private parseStatus(status: unknown): 'in_progress' | 'completed' | 'failed' {
    if (status === 'in_progress' || status === 'completed' || status === 'failed') {
      return status;
    }
    return 'in_progress';
  }

  private parseJson<T>(value: unknown): T {
    if (typeof value !== 'string' || value.length === 0) {
      return {} as T;
    }

    try {
      return JSON.parse(value) as T;
    } catch {
      return {} as T;
    }
  }

  /**
   * Flush pending changes; database lifecycle is owned by global DatabaseManager.
   */
  public close(): void {
    if (!this.initialized) {
      return;
    }
    this.persist();
  }
}

import redisService from '../security/redis.service';
import logger from '../utils/logger';

type QueueName = 'scanner-runs';

class JobQueueService {
  private memoryQueues = new Map<QueueName, string[]>();

  private getMemoryQueue(queue: QueueName): string[] {
    const existing = this.memoryQueues.get(queue);
    if (existing) {
      return existing;
    }
    const next: string[] = [];
    this.memoryQueues.set(queue, next);
    return next;
  }

  async enqueue(queue: QueueName, jobId: string): Promise<void> {
    const normalizedId = String(jobId || '').trim();
    if (!normalizedId) {
      return;
    }

    if (redisService.isAvailable()) {
      try {
        const client = redisService.getClient();
        const queueKey = `job-queue:${queue}`;
        const memberKey = `job-queue:${queue}:members`;
        const added = await client.sadd(memberKey, normalizedId);
        if (added === 1) {
          await client.rpush(queueKey, normalizedId);
        }
        return;
      } catch (error: any) {
        logger.warn('Redis queue enqueue failed, falling back to memory queue', {
          queue,
          jobId: normalizedId,
          error: error?.message
        });
      }
    }

    const rows = this.getMemoryQueue(queue);
    if (!rows.includes(normalizedId)) {
      rows.push(normalizedId);
    }
  }

  async drain(queue: QueueName, limit = 100): Promise<string[]> {
    const safeLimit = Math.max(1, Math.min(limit, 500));

    if (redisService.isAvailable()) {
      try {
        const client = redisService.getClient();
        const queueKey = `job-queue:${queue}`;
        const memberKey = `job-queue:${queue}:members`;
        const drained: string[] = [];

        for (let index = 0; index < safeLimit; index += 1) {
          const next = await client.lpop(queueKey);
          if (!next) {
            break;
          }
          await client.srem(memberKey, next);
          drained.push(next);
        }

        if (drained.length > 0) {
          return drained;
        }
      } catch (error: any) {
        logger.warn('Redis queue drain failed, falling back to memory queue', {
          queue,
          error: error?.message
        });
      }
    }

    const rows = this.getMemoryQueue(queue);
    return rows.splice(0, safeLimit);
  }

  async remove(queue: QueueName, jobId: string): Promise<void> {
    const normalizedId = String(jobId || '').trim();
    if (!normalizedId) {
      return;
    }

    if (redisService.isAvailable()) {
      try {
        const client = redisService.getClient();
        const queueKey = `job-queue:${queue}`;
        const memberKey = `job-queue:${queue}:members`;
        await client.lrem(queueKey, 0, normalizedId);
        await client.srem(memberKey, normalizedId);
      } catch (error: any) {
        logger.warn('Redis queue remove failed, falling back to memory queue', {
          queue,
          jobId: normalizedId,
          error: error?.message
        });
      }
    }

    const rows = this.getMemoryQueue(queue);
    const filtered = rows.filter((item) => item !== normalizedId);
    this.memoryQueues.set(queue, filtered);
  }

  async size(queue: QueueName): Promise<number> {
    if (redisService.isAvailable()) {
      try {
        const client = redisService.getClient();
        const size = await client.llen(`job-queue:${queue}`);
        return Number(size || 0);
      } catch (error: any) {
        logger.warn('Redis queue size failed, falling back to memory queue', {
          queue,
          error: error?.message
        });
      }
    }

    return this.getMemoryQueue(queue).length;
  }

  backend(): 'redis' | 'memory' {
    return redisService.isAvailable() ? 'redis' : 'memory';
  }
}

export const jobQueueService = new JobQueueService();

import axios from 'axios';
import nodemailer from 'nodemailer';
import auditLogger from '../security/audit-logger.service';
import logger from '../utils/logger';
import type { AlertRecord } from './security-operations.service';
import {
  NotificationChannelConfig,
  NotificationDeliveryRecord,
  SeverityLevel,
  isSeverityAtLeast,
  platformConfigService
} from './platform-config.service';

function normalizeSeverity(value: AlertRecord['severity'] | SeverityLevel): SeverityLevel {
  const normalized = String(value || 'medium').toLowerCase();
  if (normalized === 'critical' || normalized === 'high' || normalized === 'medium' || normalized === 'low') {
    return normalized;
  }
  return 'medium';
}

function buildNotificationPayload(alert: AlertRecord, severity: SeverityLevel) {
  return {
    alertId: alert.id,
    title: alert.title,
    message: alert.message,
    severity,
    type: alert.type,
    source: alert.source,
    status: alert.status,
    timestamp: alert.timestamp,
    fingerprint: String(alert.metadata?.fingerprint || alert.findingId || alert.id),
    metadata: alert.metadata || {}
  };
}

function dedupeKeyFor(alert: AlertRecord, channel: NotificationChannelConfig, severity: SeverityLevel): string {
  const fingerprint = String(alert.metadata?.fingerprint || alert.findingId || alert.id || alert.title);
  return `${fingerprint}|${channel.id}|${severity}`;
}

class NotificationDispatcherService {
  private queueTimer: NodeJS.Timeout | null = null;
  private drainScheduled = false;
  private inFlight = new Set<string>();

  startWorker(intervalMs = 5000): void {
    if (this.queueTimer) {
      return;
    }
    this.queueTimer = setInterval(() => {
      void this.processDueDeliveries();
    }, intervalMs);
    this.queueTimer.unref?.();
    this.scheduleDrain();
  }

  stopWorker(): void {
    if (this.queueTimer) {
      clearInterval(this.queueTimer);
      this.queueTimer = null;
    }
  }

  async dispatchAlert(tenantId: string, alert: AlertRecord): Promise<NotificationDeliveryRecord[]> {
    return this.enqueueAlert(tenantId, alert);
  }

  async enqueueAlert(tenantId: string, alert: AlertRecord): Promise<NotificationDeliveryRecord[]> {
    try {
      const config = await platformConfigService.getConfig(tenantId);
      if (!config.notifications.enabled) {
        return [];
      }

      const severity = normalizeSeverity(alert.severity);
      const channels = config.notifications.channels.filter((channel) =>
        channel.enabled && isSeverityAtLeast(severity, channel.minimumSeverity)
      );

      const dedupeWindowStart = new Date(Date.now() - config.notifications.dedupeWindowSeconds * 1000).toISOString();
      const payload = buildNotificationPayload(alert, severity);
      const deliveries: NotificationDeliveryRecord[] = [];

      for (const channel of channels) {
        const dedupeKey = dedupeKeyFor(alert, channel, severity);
        const existing = await platformConfigService.findNotificationDeliveryByDedupe(tenantId, dedupeKey, dedupeWindowStart);
        if (existing) {
          deliveries.push(await platformConfigService.createNotificationDelivery({
            tenantId,
            alertId: alert.id,
            channelId: channel.id,
            channelType: channel.type,
            channelLabel: channel.name,
            status: 'skipped',
            severity,
            target: channel.target,
            payload,
            response: {
              dedupedAgainst: existing.id
            },
            error: 'notification_deduped',
            attemptCount: 0,
            dedupeKey,
            terminalAt: new Date().toISOString()
          }));
          continue;
        }

        deliveries.push(await platformConfigService.createNotificationDelivery({
          tenantId,
          alertId: alert.id,
          channelId: channel.id,
          channelType: channel.type,
          channelLabel: channel.name,
          status: 'queued',
          severity,
          target: channel.target,
          payload,
          response: {},
          attemptCount: 0,
          dedupeKey,
          nextAttemptAt: new Date().toISOString()
        }));
      }

      this.scheduleDrain();
      return deliveries;
    } catch (error: any) {
      logger.warn('Notification enqueue skipped', {
        tenantId,
        alertId: alert.id,
        error: error?.message || 'unknown error'
      });
      return [];
    }
  }

  async testChannel(
    tenantId: string,
    channelId: string,
    actor: { id: string; email?: string; ip?: string }
  ): Promise<NotificationDeliveryRecord> {
    const config = await platformConfigService.getConfig(tenantId);
    const channel = config.notifications.channels.find((item) => item.id === channelId);

    if (!channel) {
      throw new Error('backend.notification_channel_not_found');
    }

    const alert: AlertRecord = {
      id: `test-${Date.now()}`,
      title: 'Test notification',
      message: 'This is a control-plane test notification from AetherGuard.',
      severity: 'High',
      type: 'system',
      source: 'config.notifications.test',
      time: 'Just now',
      status: 'open',
      timestamp: new Date().toISOString(),
      metadata: {
        test: true,
        fingerprint: `test:${channelId}:${Date.now()}`
      }
    };

    const delivery = await platformConfigService.createNotificationDelivery({
      tenantId,
      alertId: alert.id,
      channelId: channel.id,
      channelType: channel.type,
      channelLabel: channel.name,
      status: 'queued',
      severity: 'high',
      target: channel.target,
      payload: buildNotificationPayload(alert, 'high'),
      response: {},
      attemptCount: 0,
      dedupeKey: dedupeKeyFor(alert, channel, 'high'),
      nextAttemptAt: new Date().toISOString()
    });

    const processed = await this.processDelivery(delivery);

    await auditLogger.log({
      tenantId,
      eventType: 'notification_channel_tested',
      category: 'system',
      severity: processed.status === 'sent' ? 'info' : 'warning',
      actor: { type: 'user', id: actor.id, email: actor.email, ip: actor.ip },
      action: 'test_notification_channel',
      target: { type: 'server', id: channelId },
      details: {
        channelType: channel.type,
        channelName: channel.name,
        deliveryId: processed.id,
        status: processed.status
      },
      status: processed.status === 'sent' ? 'success' : 'failure'
    });

    return processed;
  }

  private scheduleDrain(): void {
    if (this.drainScheduled) {
      return;
    }
    this.drainScheduled = true;
    setTimeout(() => {
      this.drainScheduled = false;
      void this.processDueDeliveries();
    }, 25).unref?.();
  }

  private async processDueDeliveries(limit = 25): Promise<void> {
    const due = await platformConfigService.listDueNotificationDeliveries(limit);
    for (const delivery of due) {
      if (this.inFlight.has(delivery.id)) {
        continue;
      }
      this.inFlight.add(delivery.id);
      try {
        await this.processDelivery(delivery);
      } finally {
        this.inFlight.delete(delivery.id);
      }
    }
  }

  private async processDelivery(delivery: NotificationDeliveryRecord): Promise<NotificationDeliveryRecord> {
    const config = await platformConfigService.getConfig(delivery.tenantId);
    const channel = config.notifications.channels.find((item) => item.id === delivery.channelId);
    if (!config.notifications.enabled || !channel || !channel.enabled) {
      return (await platformConfigService.updateNotificationDelivery(delivery.tenantId, delivery.id, {
        status: 'skipped',
        error: !config.notifications.enabled ? 'notifications_disabled' : 'notification_channel_disabled',
        terminalAt: new Date().toISOString(),
        nextAttemptAt: null as any
      })) || delivery;
    }

    const attemptCount = delivery.attemptCount + 1;
    await platformConfigService.updateNotificationDelivery(delivery.tenantId, delivery.id, {
      status: 'sending',
      attemptCount,
      error: undefined,
      nextAttemptAt: null as any
    });

    try {
      const response = await this.send(channel, delivery.payload);
      const sent = await platformConfigService.updateNotificationDelivery(delivery.tenantId, delivery.id, {
        status: 'sent',
        response,
        attemptCount,
        terminalAt: new Date().toISOString(),
        nextAttemptAt: null as any
      });

      await auditLogger.log({
        tenantId: delivery.tenantId,
        eventType: 'notification_sent',
        category: 'system',
        severity: 'info',
        actor: { type: 'system', id: 'notification-dispatcher' },
        action: 'dispatch_notification',
        target: { type: 'server', id: channel.id },
        details: {
          channelType: channel.type,
          channelName: channel.name,
          deliveryId: delivery.id,
          alertId: delivery.alertId || null,
          attemptCount
        },
        status: 'success'
      });

      return sent || delivery;
    } catch (error: any) {
      const retryDelay = config.notifications.retryDelaysSeconds[attemptCount - 1];
      const terminal = !Number.isFinite(retryDelay as number);
      const nextAttemptAt = terminal ? null : new Date(Date.now() + Number(retryDelay) * 1000).toISOString();

      const failed = await platformConfigService.updateNotificationDelivery(delivery.tenantId, delivery.id, {
        status: terminal ? 'failed' : 'retrying',
        error: error?.message || 'notification delivery failed',
        response: {
          name: error?.name || 'Error'
        },
        attemptCount,
        nextAttemptAt: nextAttemptAt as any,
        terminalAt: terminal ? new Date().toISOString() : null as any
      });

      await auditLogger.log({
        tenantId: delivery.tenantId,
        eventType: terminal ? 'notification_failed' : 'notification_retry_scheduled',
        category: 'system',
        severity: terminal ? 'warning' : 'info',
        actor: { type: 'system', id: 'notification-dispatcher' },
        action: 'dispatch_notification',
        target: { type: 'server', id: channel.id },
        details: {
          channelType: channel.type,
          channelName: channel.name,
          deliveryId: delivery.id,
          alertId: delivery.alertId || null,
          attemptCount,
          nextAttemptAt,
          error: error?.message || 'notification delivery failed'
        },
        status: terminal ? 'failure' : 'success'
      });

      return failed || delivery;
    }
  }

  private async send(channel: NotificationChannelConfig, payload: Record<string, any>): Promise<Record<string, any>> {
    if (channel.type === 'email' || channel.type === 'smtp') {
      return this.sendSmtp(channel, payload);
    }
    return this.sendWebhook(channel, payload);
  }

  private async sendWebhook(channel: NotificationChannelConfig, payload: Record<string, any>): Promise<Record<string, any>> {
    if (!channel.target) {
      throw new Error('backend.notification_target_required');
    }

    const response = await axios.post(channel.target, payload, {
      timeout: 10000,
      headers: {
        'Content-Type': 'application/json',
        ...channel.headers
      },
      validateStatus: () => true
    });

    if (response.status >= 400) {
      throw new Error(`Webhook delivery failed with status ${response.status}`);
    }

    return {
      status: response.status,
      body: typeof response.data === 'string' ? response.data.slice(0, 500) : response.data
    };
  }

  private async sendSmtp(channel: NotificationChannelConfig, payload: Record<string, any>): Promise<Record<string, any>> {
    if (!channel.smtp.host || !channel.smtp.from || !channel.target) {
      throw new Error('backend.smtp_configuration_incomplete');
    }

    const transporter = nodemailer.createTransport({
      host: channel.smtp.host,
      port: channel.smtp.port,
      secure: channel.smtp.secure,
      auth: channel.smtp.username
        ? {
            user: channel.smtp.username,
            pass: channel.smtp.password
          }
        : undefined
    });

    const info = await transporter.sendMail({
      from: channel.smtp.from,
      to: channel.target,
      subject: `[AetherGuard][${String(payload.severity || 'medium').toUpperCase()}] ${payload.title}`,
      text: [
        `Alert ID: ${payload.alertId}`,
        `Severity: ${payload.severity}`,
        `Source: ${payload.source}`,
        `Type: ${payload.type}`,
        '',
        payload.message
      ].join('\n')
    });

    return {
      messageId: info.messageId,
      accepted: info.accepted,
      rejected: info.rejected
    };
  }
}

