import type {
  EdgeAutoDashboardModuleSummary,
  EdgeAutoModuleKind,
  EdgeAutoModuleManifest,
  EdgeFinopsModuleStats,
  EdgeFinopsStats,
  ProtocolFindingSignal,
  ProtocolModuleManifest,
  ProtocolModulePolicyEnvelope,
  ProtocolModuleStats,
  ProtocolModuleStatsEnvelope,
  ProtocolObservationContext,
} from '../types/edge-auto';
import {
  BUILTIN_EDGE_AUTO_MODULE_MANIFESTS,
  cloneJson,
  DEFAULT_AGENT_PROTOCOL_POLICY,
  DEFAULT_AGENT_PROTOCOL_STATS,
  DEFAULT_EDGE_FINOPS_STATS,
  estimatedSavedMb,
  toLegacyProtocolPolicy,
  toLegacyProtocolStats,
} from '../types/edge-auto';

function clampNumber(value: any, fallback: number, min: number, max: number): number {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return fallback;
  }
  return Math.min(Math.max(numeric, min), max);
}

function uniqueStrings(value: unknown, fallback: string[] = []): string[] {
  if (!Array.isArray(value)) {
    return [...fallback];
  }
  return value
    .map((item) => String(item || '').trim())
    .filter((item, index, list) => item && list.indexOf(item) === index);
}

function ensureRecord(value: unknown): Record<string, any> {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? { ...(value as Record<string, any>) }
    : {};
}

function emptyModuleFinops(raw?: Partial<EdgeFinopsModuleStats> | null): EdgeFinopsModuleStats {
  const savedBytes = Math.max(0, Number(raw?.savedBytes || 0));
  const savedMessages = Math.max(0, Number(raw?.savedMessages || 0));
  return {
    savedBytes,
    savedMessages,
    estimatedSavedMb: estimatedSavedMb(savedBytes),
  };
}

interface ProtocolModuleAdapter {
  manifest: ProtocolModuleManifest;
  defaultPolicy(): Record<string, any>;
  emptyStats(): ProtocolModuleStats;
  normalizePolicy(raw: any, fallback?: Record<string, any>): Record<string, any>;
  reduceStats(current: ProtocolModuleStats, context: ProtocolObservationContext): ProtocolModuleStats;
  finopsDelta(context: ProtocolObservationContext): EdgeFinopsModuleStats;
  translateFindings(context: ProtocolObservationContext & { moduleStats: ProtocolModuleStats }): ProtocolFindingSignal[];
}

function emptyModuleStats(seed?: Partial<ProtocolModuleStats>): ProtocolModuleStats {
  return {
    evaluations: Math.max(0, Number(seed?.evaluations || 0)),
    findings: Math.max(0, Number(seed?.findings || 0)),
    counters: ensureRecord(seed?.counters),
    findingsByCode: ensureRecord(seed?.findingsByCode),
    lastEventAt: typeof seed?.lastEventAt === 'string' ? seed.lastEventAt : null,
    lastFindingAt: typeof seed?.lastFindingAt === 'string' ? seed.lastFindingAt : null,
  };
}

const HTTP_PROTOCOL_ADAPTER: ProtocolModuleAdapter = {
  manifest: BUILTIN_EDGE_AUTO_MODULE_MANIFESTS.find((item) => item.kind === 'protocol' && item.moduleId === 'http') as ProtocolModuleManifest,
  defaultPolicy: () => ({}),
  emptyStats: () => emptyModuleStats({
    counters: {
      blockedRequests: 0,
    },
  }),
  normalizePolicy: () => ({}),
  reduceStats: (current, context) => {
    const next = emptyModuleStats(current);
    next.evaluations += 1;
    next.lastEventAt = context.timestamp || new Date().toISOString();
    if (Array.isArray(context.response?.findings) && context.response?.findings.length > 0) {
      next.findings += context.response.findings.length;
      next.lastFindingAt = next.lastEventAt;
      for (const finding of context.response.findings) {
        next.findingsByCode[finding.code] = Number(next.findingsByCode[finding.code] || 0) + 1;
      }
    }
    if (context.response?.verdict === 'block') {
      next.counters.blockedRequests = Number(next.counters.blockedRequests || 0) + 1;
    }
    return next;
  },
  finopsDelta: () => emptyModuleFinops(),
  translateFindings: () => [],
};

const MQTT_PROTOCOL_ADAPTER: ProtocolModuleAdapter = {
  manifest: BUILTIN_EDGE_AUTO_MODULE_MANIFESTS.find((item) => item.kind === 'protocol' && item.moduleId === 'mqtt') as ProtocolModuleManifest,
  defaultPolicy: () => cloneJson(DEFAULT_AGENT_PROTOCOL_POLICY.modules.mqtt),
  emptyStats: () => emptyModuleStats({
    counters: {
      messages: 0,
      suppressedMessages: 0,
      blockedMessages: 0,
      savedBytes: 0,
    },
  }),
  normalizePolicy: (raw, fallback = DEFAULT_AGENT_PROTOCOL_POLICY.modules.mqtt) => ({
    relayEnabled: typeof raw?.relayEnabled === 'boolean' ? raw.relayEnabled : Boolean(raw?.mqttRelayEnabled ?? fallback.relayEnabled),
    suppressHighFrequency: typeof raw?.suppressHighFrequency === 'boolean'
      ? raw.suppressHighFrequency
      : Boolean(raw?.mqttSuppressHighFrequency ?? fallback.suppressHighFrequency),
    heartbeatTopics: uniqueStrings(raw?.heartbeatTopics ?? raw?.mqttHeartbeatTopics, fallback.heartbeatTopics),
    heartbeatMinIntervalMs: clampNumber(
      raw?.heartbeatMinIntervalMs ?? raw?.mqttHeartbeatMinIntervalMs,
      Number(fallback.heartbeatMinIntervalMs || 1000),
      100,
      60000,
    ),
  }),
  reduceStats: (current, context) => {
    const next = emptyModuleStats(current);
    next.evaluations += 1;
    next.counters.messages = Number(next.counters.messages || 0) + 1;
    next.lastEventAt = context.timestamp || new Date().toISOString();
    if (context.response?.action === 'suppress') {
      next.counters.suppressedMessages = Number(next.counters.suppressedMessages || 0) + Number(context.response.costMetrics?.suppressedMessages || 0);
      next.counters.savedBytes = Number(next.counters.savedBytes || 0) + Number(context.response.costMetrics?.savedBytes || 0);
    }
    if (context.response?.action === 'block') {
      next.counters.blockedMessages = Number(next.counters.blockedMessages || 0) + 1;
    }
    if (Array.isArray(context.response?.findings) && context.response.findings.length > 0) {
      next.findings += context.response.findings.length;
      next.lastFindingAt = next.lastEventAt;
      for (const finding of context.response.findings) {
        next.findingsByCode[finding.code] = Number(next.findingsByCode[finding.code] || 0) + 1;
      }
    }
    return next;
  },
  finopsDelta: (context) => emptyModuleFinops({
    savedBytes: Number(context.response?.costMetrics?.savedBytes || 0),
    savedMessages: Number(context.response?.costMetrics?.suppressedMessages || 0),
  }),
  translateFindings: () => [],
};

const ROS2_PROTOCOL_ADAPTER: ProtocolModuleAdapter = {
  manifest: BUILTIN_EDGE_AUTO_MODULE_MANIFESTS.find((item) => item.kind === 'protocol' && item.moduleId === 'ros2_cyberrt') as ProtocolModuleManifest,
  defaultPolicy: () => cloneJson(DEFAULT_AGENT_PROTOCOL_POLICY.modules.ros2_cyberrt),
  emptyStats: () => emptyModuleStats({
    counters: {
      events: 0,
      unauthorizedRpcFindings: 0,
    },
  }),
  normalizePolicy: (raw, fallback = DEFAULT_AGENT_PROTOCOL_POLICY.modules.ros2_cyberrt) => ({
    observerEnabled: typeof raw?.observerEnabled === 'boolean' ? raw.observerEnabled : Boolean(raw?.ros2ObserverEnabled ?? fallback.observerEnabled),
    allowlist: uniqueStrings(raw?.allowlist ?? raw?.ros2Allowlist, fallback.allowlist),
  }),
  reduceStats: (current, context) => {
    const next = emptyModuleStats(current);
    next.evaluations += 1;
    next.counters.events = Number(next.counters.events || 0) + 1;
    next.lastEventAt = context.timestamp || new Date().toISOString();
    if (Array.isArray(context.response?.findings) && context.response.findings.length > 0) {
      next.findings += context.response.findings.length;
      next.lastFindingAt = next.lastEventAt;
      for (const finding of context.response.findings) {
        next.findingsByCode[finding.code] = Number(next.findingsByCode[finding.code] || 0) + 1;
        if (finding.code === 'unauthorized_vehicle_rpc') {
          next.counters.unauthorizedRpcFindings = Number(next.counters.unauthorizedRpcFindings || 0) + 1;
        }
      }
    }
    return next;
  },
  finopsDelta: () => emptyModuleFinops(),
  translateFindings: (context) => {
    if (!Array.isArray(context.response?.findings) || !context.response.findings.some((finding) => finding.code === 'unauthorized_vehicle_rpc')) {
      return [];
    }
    return [
      {
        code: 'unauthorized_vehicle_rpc',
        severity: 'high',
        title: 'Unauthorized vehicle RPC observed',
        description: 'ROS2 / Cyber RT observer detected a vehicle RPC outside the configured allowlist.',
        category: 'vehicle-rpc',
        fingerprint: `ros2:${String(context.channel || 'unknown')}:unauthorized_vehicle_rpc`,
        createAlert: true,
        alertType: 'security',
        remediationTitle: 'Restrict ROS2 / Cyber RT RPC exposure',
        remediationOwner: 'vehicle-security',
        remediationPriority: 'high',
        remediationSteps: [
          'Review the per-node allowlist configured for this ROS2 / Cyber RT observer.',
          'Identify the process or app issuing the RPC and remove unintended access.',
          'Keep the observer enabled until the unexpected publisher is fully isolated.',
        ],
      },
    ];
  },
};

class ProtocolModuleRegistryService {
  private readonly manifests = cloneJson(BUILTIN_EDGE_AUTO_MODULE_MANIFESTS);
  private readonly protocolAdapters = new Map<string, ProtocolModuleAdapter>([
    ['http', HTTP_PROTOCOL_ADAPTER],
    ['mqtt', MQTT_PROTOCOL_ADAPTER],
    ['ros2_cyberrt', ROS2_PROTOCOL_ADAPTER],
  ]);

  listManifests(kind?: EdgeAutoModuleKind): EdgeAutoModuleManifest[] {
    return this.manifests
      .filter((item) => !kind || item.kind === kind)
      .map((item) => cloneJson(item));
  }

  listProtocolManifests(): ProtocolModuleManifest[] {
    return this.listManifests('protocol') as ProtocolModuleManifest[];
  }

  getProtocolAdapter(moduleId: string): ProtocolModuleAdapter | undefined {
    return this.protocolAdapters.get(moduleId);
  }

  getModuleIdForProtocol(protocol: string): string {
    const normalized = String(protocol || '').trim().toLowerCase();
    return this.protocolAdapters.has(normalized) ? normalized : normalized;
  }

  defaultProtocolPolicyEnvelope(): ProtocolModulePolicyEnvelope {
    return cloneJson(DEFAULT_AGENT_PROTOCOL_POLICY);
  }

  normalizePolicyEnvelope(raw: any, fallback: ProtocolModulePolicyEnvelope = DEFAULT_AGENT_PROTOCOL_POLICY): ProtocolModulePolicyEnvelope {
    const fallbackEnvelope = cloneJson(fallback);
    const rawModules = ensureRecord(raw?.modules);
    const modules: Record<string, Record<string, any>> = {};

    for (const manifest of this.listProtocolManifests()) {
      const adapter = this.getProtocolAdapter(manifest.moduleId);
      if (!adapter) {
        continue;
      }
      const source = ensureRecord(rawModules[manifest.moduleId]);
      modules[manifest.moduleId] = adapter.normalizePolicy(
        Object.keys(source).length > 0 ? source : raw,
        ensureRecord(fallbackEnvelope.modules?.[manifest.moduleId]),
      );
    }

    for (const [moduleId, value] of Object.entries(rawModules)) {
      if (!(moduleId in modules)) {
        modules[moduleId] = ensureRecord(value);
      }
    }

    const envelope: ProtocolModulePolicyEnvelope = {
      modules,
      legacy: toLegacyProtocolPolicy({ modules }),
    };

    return envelope;
  }

  emptyStatsEnvelope(): ProtocolModuleStatsEnvelope {
    return cloneJson(DEFAULT_AGENT_PROTOCOL_STATS);
  }

  normalizeStatsEnvelope(raw: any, fallback: ProtocolModuleStatsEnvelope = DEFAULT_AGENT_PROTOCOL_STATS): ProtocolModuleStatsEnvelope {
    const fallbackEnvelope = cloneJson(fallback);
    const rawModules = ensureRecord(raw?.modules);
    const modules: Record<string, ProtocolModuleStats> = {};

    for (const manifest of this.listProtocolManifests()) {
      const adapter = this.getProtocolAdapter(manifest.moduleId);
      const base = ensureRecord(rawModules[manifest.moduleId]);
      modules[manifest.moduleId] = adapter
        ? emptyModuleStats({
            ...(fallbackEnvelope.modules?.[manifest.moduleId] || adapter.emptyStats()),
            ...base,
          })
        : emptyModuleStats(base);
    }

    for (const [moduleId, value] of Object.entries(rawModules)) {
      if (!(moduleId in modules)) {
        modules[moduleId] = emptyModuleStats(value as Partial<ProtocolModuleStats>);
      }
    }

    const envelope: ProtocolModuleStatsEnvelope = {
      totalEvaluations: Math.max(0, Number(raw?.totalEvaluations ?? (fallbackEnvelope.totalEvaluations || 0))),
      protocolErrors: Math.max(0, Number(raw?.protocolErrors ?? (fallbackEnvelope.protocolErrors || 0))),
      modules,
    };
    envelope.legacy = toLegacyProtocolStats(envelope);
    return envelope;
  }

  normalizeFinopsStats(raw: any, fallback: EdgeFinopsStats = DEFAULT_EDGE_FINOPS_STATS): EdgeFinopsStats {
    const fallbackValue = cloneJson(fallback);
    const rawModules = ensureRecord(raw?.modules);
    const modules: Record<string, EdgeFinopsModuleStats> = {};

    for (const manifest of this.listProtocolManifests()) {
      modules[manifest.moduleId] = emptyModuleFinops({
        ...(fallbackValue.modules?.[manifest.moduleId] || {}),
        ...(ensureRecord(rawModules[manifest.moduleId]) || {}),
      });
    }

    for (const [moduleId, value] of Object.entries(rawModules)) {
      if (!(moduleId in modules)) {
        modules[moduleId] = emptyModuleFinops(value as Partial<EdgeFinopsModuleStats>);
      }
    }

    const savedBytes = Math.max(0, Number(raw?.savedBytes ?? (fallbackValue.savedBytes || 0)));
    const savedMessages = Math.max(0, Number(raw?.savedMessages ?? (fallbackValue.savedMessages || 0)));
    const computedSavedBytes = Object.values(modules).reduce((sum, item) => sum + item.savedBytes, 0);
    const computedSavedMessages = Object.values(modules).reduce((sum, item) => sum + item.savedMessages, 0);

    return {
      savedBytes: savedBytes || computedSavedBytes,
      savedMessages: savedMessages || computedSavedMessages,
      estimatedSavedMb: estimatedSavedMb(savedBytes || computedSavedBytes),
      modules,
    };
  }

  applyObservation(
    moduleId: string,
    stats: ProtocolModuleStatsEnvelope,
    finops: EdgeFinopsStats,
    context: ProtocolObservationContext,
  ): {
    protocolStats: ProtocolModuleStatsEnvelope;
    finopsStats: EdgeFinopsStats;
    translatedFindings: ProtocolFindingSignal[];
  } {
    const normalizedStats = this.normalizeStatsEnvelope(stats);
    const normalizedFinops = this.normalizeFinopsStats(finops);
    const adapter = this.getProtocolAdapter(moduleId);

    normalizedStats.totalEvaluations += 1;
    if (!context.response) {
      normalizedStats.protocolErrors += 1;
      return {
        protocolStats: this.normalizeStatsEnvelope(normalizedStats),
        finopsStats: normalizedFinops,
        translatedFindings: [],
      };
    }

    const currentModuleStats = adapter
      ? normalizedStats.modules[moduleId] || adapter.emptyStats()
      : emptyModuleStats(normalizedStats.modules[moduleId]);
    const nextModuleStats = adapter
      ? adapter.reduceStats(currentModuleStats, context)
      : emptyModuleStats({
          ...currentModuleStats,
          evaluations: Number(currentModuleStats.evaluations || 0) + 1,
          lastEventAt: context.timestamp || new Date().toISOString(),
        });

    normalizedStats.modules[moduleId] = nextModuleStats;

    const finopsDelta = adapter ? adapter.finopsDelta(context) : emptyModuleFinops();
    const currentModuleFinops = normalizedFinops.modules[moduleId] || emptyModuleFinops();
    normalizedFinops.modules[moduleId] = emptyModuleFinops({
      savedBytes: currentModuleFinops.savedBytes + finopsDelta.savedBytes,
      savedMessages: currentModuleFinops.savedMessages + finopsDelta.savedMessages,
    });
    normalizedFinops.savedBytes = Object.values(normalizedFinops.modules).reduce((sum, item) => sum + item.savedBytes, 0);
    normalizedFinops.savedMessages = Object.values(normalizedFinops.modules).reduce((sum, item) => sum + item.savedMessages, 0);
    normalizedFinops.estimatedSavedMb = estimatedSavedMb(normalizedFinops.savedBytes);

    return {
      protocolStats: this.normalizeStatsEnvelope(normalizedStats),
      finopsStats: this.normalizeFinopsStats(normalizedFinops),
      translatedFindings: adapter ? adapter.translateFindings({ ...context, moduleStats: nextModuleStats }) : [],
    };
  }

  summarizeModules(
    stats: ProtocolModuleStatsEnvelope,
    finops: EdgeFinopsStats,
  ): Record<string, EdgeAutoDashboardModuleSummary> {
    const normalizedStats = this.normalizeStatsEnvelope(stats);
    const normalizedFinops = this.normalizeFinopsStats(finops);
    const summaries: Record<string, EdgeAutoDashboardModuleSummary> = {};

    for (const manifest of this.listProtocolManifests()) {
      const moduleStats = normalizedStats.modules[manifest.moduleId] || emptyModuleStats();
      const moduleFinops = normalizedFinops.modules[manifest.moduleId] || emptyModuleFinops();
      summaries[manifest.moduleId] = {
        moduleId: manifest.moduleId,
        evaluations: Number(moduleStats.evaluations || 0),
        findings: Number(moduleStats.findings || 0),
        counters: Object.entries(moduleStats.counters || {}).reduce<Record<string, number>>((acc, [key, value]) => {
          acc[key] = Number(value || 0);
          return acc;
        }, {}),
        savedBytes: Number(moduleFinops.savedBytes || 0),
        savedMessages: Number(moduleFinops.savedMessages || 0),
        estimatedSavedMb: Number(moduleFinops.estimatedSavedMb || 0),
        lastEventAt: moduleStats.lastEventAt || null,
        lastFindingAt: moduleStats.lastFindingAt || null,
      };
    }

    return summaries;
  }
}

