  private async runTask(taskId: string): Promise<void> {
    const task = this.getTask(taskId);
    if (!task || this.cancelled.has(taskId)) {
      return;
    }

    task.status = 'running';
    task.phase = 'normalizing';
    task.progress = 5;
    task.startedAt = this.nowISO();
    task.error = undefined;
    this.upsertTask(task, 'scanner:task:started', { phase: task.phase, progress: task.progress });

    const profile = this.getProfile(task.profileId) || this.deriveProfile({
      tenantId: task.tenantId,
      createdBy: task.createdBy,
      targets: task.targets,
      enginePolicy: task.enginePolicy
    }, this.listRunTargets(task.id));
    const runTargets = this.listRunTargets(task.id);
    const resolvedTargets: ResolvedScanTarget[] = [];

    try {
      const normalizeStage = this.beginStage(task, 'normalizing', 5, 'Validating scan request');
      this.finishStage(task, normalizeStage, `Prepared ${runTargets.length} targets`);

      this.ensureNotCancelled(task);

      const resolutionStage = this.beginStage(task, 'asset-resolution', 10, 'Resolving targets');
      for (let index = 0; index < runTargets.length; index += 1) {
        this.ensureNotCancelled(task);
        const resolved = await this.resolveTarget(task, runTargets[index]);
        if (resolved) {
          resolvedTargets.push(resolved);
        }
        const progress = 10 + Math.floor(((index + 1) / Math.max(1, runTargets.length)) * 20);
        this.updateStageProgress(task, resolutionStage, progress, `Resolved ${index + 1}/${runTargets.length} targets`);
      }
      this.finishStage(task, resolutionStage, `Resolved ${resolvedTargets.length} executable targets`, {
        resolvedTargets: resolvedTargets.length,
        skippedTargets: runTargets.length - resolvedTargets.length
      });

      const webTargets = resolvedTargets.filter((target) => target.urls.length > 0 || target.hosts.length > 0);
      if (webTargets.length > 0) {
        const webStage = this.beginStage(task, 'web-scan', 35, 'Running web, TLS and service probes');
        for (let index = 0; index < webTargets.length; index += 1) {
          await this.scanResolvedTarget(task, webTargets[index], profile);
          const progress = 35 + Math.floor(((index + 1) / Math.max(1, webTargets.length)) * 35);
          this.updateStageProgress(task, webStage, progress, `Scanned ${index + 1}/${webTargets.length} network targets`);
        }
        this.finishStage(task, webStage, 'Completed network-facing scan stages');
      } else {
        this.skipStage(task, 'web-scan', 35, 'No web, domain or address targets were provided');
      }

      const hostTargets = resolvedTargets.filter((target) => target.supportsHostBaseline);
      if (hostTargets.length > 0) {
        const hostStage = this.beginStage(task, 'host-scan', 72, 'Running local host baseline');
        for (let index = 0; index < hostTargets.length; index += 1) {
          await this.runHostBaseline(task, hostTargets[index]);
          const progress = 72 + Math.floor(((index + 1) / Math.max(1, hostTargets.length)) * 10);
          this.updateStageProgress(task, hostStage, progress, `Completed ${index + 1}/${hostTargets.length} host targets`);
        }
        this.finishStage(task, hostStage, 'Completed local host posture checks');
      } else {
        this.skipStage(task, 'host-scan', 72, 'No locally executable host targets were available');
      }

      if ((profile.engines || []).includes('nuclei') && resolvedTargets.some((target) => target.urls.length > 0)) {
        const nucleiStage = this.beginStage(task, 'nuclei-scan', 84, 'Running template validation');
        await this.runNuclei(task, resolvedTargets);
        this.updateStageProgress(task, nucleiStage, 92, 'Template validation complete');
        this.finishStage(task, nucleiStage, 'Completed nuclei validation');
      } else {
        task.summary.nuclei = 'skipped';
        this.skipStage(task, 'nuclei-scan', 84, 'No URL targets available for nuclei validation');
      }

      const correlationStage = this.beginStage(task, 'correlation', 94, 'Correlating findings with alerts and actions');
      this.finalizeSummary(task);
      const correlated = this.getTaskRelatedArtifacts(task);
      this.updateStageProgress(task, correlationStage, 97, `Linked ${correlated.relatedAlerts.length} alerts and ${correlated.relatedActions.length} actions`);
      this.finishStage(task, correlationStage, 'Correlation complete', {
        alerts: correlated.relatedAlerts.length,
        actions: correlated.relatedActions.length
      });

      const finalStage = this.beginStage(task, 'finalizing', 98, 'Writing final summary');
      this.finalizeSummary(task);
      task.phase = 'done';
      task.progress = 100;
      task.status = 'completed';
      task.completedAt = this.nowISO();
      this.updateStageProgress(task, finalStage, 100, 'Run finalized');
      this.finishStage(task, finalStage, 'Scan run completed successfully');
      this.upsertTask(task, 'scanner:task:completed', { phase: task.phase, progress: task.progress, summary: task.summary });
    } catch (error: any) {
      if (error instanceof ScanCancelledError) {
        task.status = 'cancelled';
        task.phase = 'done';
        task.progress = 100;
        task.completedAt = this.nowISO();
        this.upsertTask(task, 'scanner:task:cancelled', { phase: task.phase, progress: task.progress });
        return;
      }

      task.status = 'failed';
      task.phase = 'done';
      task.progress = 100;
      task.error = error?.message || 'Scan execution failed';
      task.completedAt = this.nowISO();
      this.upsertTask(task, 'scanner:task:failed', { phase: task.phase, progress: task.progress, error: task.error });
    } finally {
      this.cancelled.delete(task.id);
    }
  }
}

export const scannerTaskService = new ScannerTaskService();

import { randomUUID } from 'crypto';
import { getDatabase } from '../config/database';
import { postgresShadowStoreService } from './postgres-shadow-store.service';
import { notificationDispatcherService } from './notification-dispatcher.service';

type Severity = 'critical' | 'high' | 'medium' | 'low';
type FindingStatus = 'open' | 'acknowledged' | 'investigating' | 'resolved' | 'suppressed' | 'ignored';
type AlertStatus = 'open' | 'acknowledged' | 'investigating' | 'resolved' | 'suppressed';
type ActionStatus = 'pending' | 'queued' | 'running' | 'completed' | 'failed' | 'rolled_back';
type AssetType = 'url' | 'site' | 'domain' | 'host' | 'ip' | 'device' | 'agent' | 'service';
type ValidationVerdict = 'blocked' | 'alerted' | 'missed' | 'false_positive' | 'timeout';

export interface AssetSummary {
  assetId: string;
  tenantId: string;
  assetType: AssetType;
  externalRef: string;
  displayName: string;
  primaryAddress?: string;
  status: string;
  riskScore: number;
  findingsOpen: number;
  alertsOpen: number;
  metadata: Record<string, any>;
  lastSeenAt?: string;
}

export interface FindingRecord {
  findingId: string;
  tenantId: string;
  assetId?: string;
  sourceType: string;
  sourceRef: string;
  target: string;
  category: string;
  severity: Severity;
  status: FindingStatus;
  title: string;
  description: string;
  evidence: Record<string, any>;
  remediation: Record<string, any>;
  fingerprint: string;
  occurrenceCount: number;
  firstSeenAt: string;
  lastSeenAt: string;
}

export interface AlertRecord {
  id: string;
  title: string;
  message: string;
  severity: 'Critical' | 'High' | 'Medium' | 'Low';
  type: 'security' | 'performance' | 'system';
  source: string;
  time: string;
  status: AlertStatus;
  timestamp: string;
  assetId?: string;
  findingId?: string;
  investigationId?: string;
  metadata?: Record<string, any>;
}

export interface ActionRunRecord {
  actionId: string;
  tenantId: string;
  assetId?: string;
  findingId?: string;
  alertId?: string;
  title: string;
  status: ActionStatus;
  operator: string;
  rollbackNotes: string;
  runLog: Record<string, any>[];
  createdAt: string;
  updatedAt: string;
}

export interface ValidationRunRecord {
  validationRunId: string;
  tenantId: string;
  attackId: string;
  attackName: string;
  category: string;
  severity: Severity;
  verdict: ValidationVerdict;
  detected: boolean;
  blocked: boolean;
  responseTime: number;
  startedAt: string;
  completedAt: string;
  result: Record<string, any>;
}

const severityWeight: Record<Severity, number> = {
  critical: 100,
  high: 75,
  medium: 45,
  low: 20
};

class SecurityOperationsService {
  private schemaReady = false;

  prepare(): void {
    if (this.schemaReady) {
      return;
    }

    const db = getDatabase();
    db.exec(`
      CREATE TABLE IF NOT EXISTS sec_assets (
        asset_id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        asset_key TEXT NOT NULL UNIQUE,
        asset_type TEXT NOT NULL,
        external_ref TEXT NOT NULL,
        display_name TEXT NOT NULL,
        primary_address TEXT,
        status TEXT NOT NULL,
        risk_score INTEGER NOT NULL DEFAULT 0,
        findings_open INTEGER NOT NULL DEFAULT 0,
        alerts_open INTEGER NOT NULL DEFAULT 0,
        metadata_json TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        last_seen_at TEXT
      );

      CREATE TABLE IF NOT EXISTS sec_findings (
        finding_id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        fingerprint TEXT NOT NULL UNIQUE,
        asset_id TEXT,
        source_type TEXT NOT NULL,
        source_ref TEXT NOT NULL,
        target TEXT NOT NULL,
        category TEXT NOT NULL,
        severity TEXT NOT NULL,
        status TEXT NOT NULL,
        title TEXT NOT NULL,
        description TEXT NOT NULL,
        evidence_json TEXT,
        remediation_json TEXT,
        first_seen_at TEXT NOT NULL,
        last_seen_at TEXT NOT NULL,
        occurrence_count INTEGER NOT NULL DEFAULT 1,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS sec_alerts (
        alert_id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        finding_id TEXT,
        asset_id TEXT,
        source_type TEXT NOT NULL,
        source_ref TEXT NOT NULL,
        title TEXT NOT NULL,
        message TEXT NOT NULL,
        severity TEXT NOT NULL,
        alert_type TEXT NOT NULL,
        status TEXT NOT NULL,
        investigation_id TEXT,
        metadata_json TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS sec_actions (
        action_id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        asset_id TEXT,
        finding_id TEXT,
        alert_id TEXT,
        title TEXT NOT NULL,
        status TEXT NOT NULL,
        operator TEXT NOT NULL,
        rollback_notes TEXT,
        run_log_json TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS sec_validations (
        validation_run_id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        attack_id TEXT NOT NULL,
        attack_name TEXT NOT NULL,
        category TEXT NOT NULL,
        severity TEXT NOT NULL,
        verdict TEXT NOT NULL,
        detected INTEGER NOT NULL,
        blocked INTEGER NOT NULL,
        response_time INTEGER NOT NULL,
        result_json TEXT,
        started_at TEXT NOT NULL,
        completed_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS sec_traffic_sessions (
        session_id TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        source_ip TEXT NOT NULL,
        dest_ip TEXT NOT NULL,
        source_port INTEGER NOT NULL,
        dest_port INTEGER NOT NULL,
        protocol TEXT NOT NULL,
        state TEXT NOT NULL,
        packet_count INTEGER NOT NULL,
        byte_count INTEGER NOT NULL,
        start_time TEXT NOT NULL,
        last_activity TEXT NOT NULL,
        source_asset_id TEXT,
        dest_asset_id TEXT,
        metadata_json TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_sec_assets_tenant ON sec_assets(tenant_id, asset_type);
      CREATE INDEX IF NOT EXISTS idx_sec_findings_tenant ON sec_findings(tenant_id, status, severity);
      CREATE INDEX IF NOT EXISTS idx_sec_findings_source ON sec_findings(source_type, source_ref);
      CREATE INDEX IF NOT EXISTS idx_sec_alerts_tenant ON sec_alerts(tenant_id, status, severity);
      CREATE INDEX IF NOT EXISTS idx_sec_actions_tenant ON sec_actions(tenant_id, status);
      CREATE INDEX IF NOT EXISTS idx_sec_validations_tenant ON sec_validations(tenant_id, completed_at);
      CREATE INDEX IF NOT EXISTS idx_sec_sessions_tenant ON sec_traffic_sessions(tenant_id, last_activity);
    `);

    this.schemaReady = true;
  }

  private assertPrepared(): void {
    if (this.schemaReady) {
      return;
    }

    if (process.env.NODE_ENV === 'test') {
      this.prepare();
      return;
    }

    throw new Error('Security operations schema not initialized. Call securityOperationsService.prepare() during bootstrap.');
  }

  private now(): string {
    return new Date().toISOString();
  }

  private shadowUpsert(table: Parameters<typeof postgresShadowStoreService.upsert>[0], row: Record<string, any> | null | undefined): void {
    if (!row) {
      return;
    }
    void postgresShadowStoreService.upsert(table, row);
  }

  private shadowGet(table: Parameters<typeof postgresShadowStoreService.upsert>[0], sql: string, ...params: any[]): void {
    const db = getDatabase();
    const row = db.prepare(sql).get(...params) as Record<string, any> | undefined;
    this.shadowUpsert(table, row);
  }

  private parseJson<T>(value: any, fallback: T): T {
    if (!value || typeof value !== 'string') {
      return fallback;
    }
    try {
      return JSON.parse(value) as T;
    } catch {
      return fallback;
    }
  }

  private normalizeSeverity(severity?: string): Severity {
    const normalized = String(severity || 'medium').toLowerCase();
    if (normalized === 'critical' || normalized === 'high' || normalized === 'medium' || normalized === 'low') {
      return normalized;
    }
    return 'medium';
  }

  private mapSeverityLabel(severity: Severity): 'Critical' | 'High' | 'Medium' | 'Low' {
    return severity.charAt(0).toUpperCase() + severity.slice(1) as 'Critical' | 'High' | 'Medium' | 'Low';
  }

  private assetKey(tenantId: string, assetType: AssetType, externalRef: string): string {
    return `${tenantId}:${assetType}:${externalRef}`;
  }

  private relativeTime(timestamp?: string): string {
    if (!timestamp) return 'Just now';
    const diffMs = Date.now() - new Date(timestamp).getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins} mins ago`;
    if (diffHours < 24) return `${diffHours} hours ago`;
    return `${diffDays} days ago`;
  }

  private shouldUseShadowReads(): boolean {
    return postgresShadowStoreService.canServeReads();
  }

  private async queryShadowAllWithFallback<T>(sql: string, params: unknown[], fallback: () => T[]): Promise<T[]> {
    if (!this.shouldUseShadowReads()) {
      return fallback();
    }

    try {
      return await postgresShadowStoreService.queryAll<T>(sql, params);
    } catch {
      return fallback();
    }
  }

  private async queryShadowOneWithFallback<T>(sql: string, params: unknown[], fallback: () => T | null): Promise<T | null> {
    if (!this.shouldUseShadowReads()) {
      return fallback();
    }

    try {
      return await postgresShadowStoreService.queryOne<T>(sql, params);
    } catch {
      return fallback();
    }
  }

  upsertAsset(input: {
    tenantId: string;
    assetType: AssetType;
    externalRef: string;
    displayName: string;
    primaryAddress?: string;
    status?: string;
    metadata?: Record<string, any>;
  }): AssetSummary {
    this.assertPrepared();
    const db = getDatabase();
    const now = this.now();
    const key = this.assetKey(input.tenantId, input.assetType, input.externalRef);
    const existing = db.prepare('SELECT * FROM sec_assets WHERE asset_key = ?').get(key) as any;

    if (existing) {
      const nextMetadata = {
        ...this.parseJson(existing.metadata_json, {}),
        ...(input.metadata || {})
      };
      db.prepare(`
        UPDATE sec_assets
        SET display_name = ?, primary_address = ?, status = ?, metadata_json = ?, updated_at = ?, last_seen_at = ?
        WHERE asset_key = ?
      `).run(
        input.displayName || existing.display_name,
        input.primaryAddress || existing.primary_address || null,
        input.status || existing.status,
        JSON.stringify(nextMetadata),
        now,
        now,
        key
      );
      this.shadowGet('sec_assets', 'SELECT * FROM sec_assets WHERE asset_key = ? LIMIT 1', key);
      return this.getAssetById(input.tenantId, existing.asset_id)!;
    }

    const assetId = randomUUID();
    db.prepare(`
      INSERT INTO sec_assets (
        asset_id, tenant_id, asset_key, asset_type, external_ref, display_name, primary_address,
        status, risk_score, findings_open, alerts_open, metadata_json, created_at, updated_at, last_seen_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, ?, ?, ?, ?)
    `).run(
      assetId,
      input.tenantId,
      key,
      input.assetType,
      input.externalRef,
      input.displayName,
      input.primaryAddress || null,
      input.status || 'observed',
      JSON.stringify(input.metadata || {}),
      now,
      now,
      now
    );
    this.shadowGet('sec_assets', 'SELECT * FROM sec_assets WHERE asset_id = ? LIMIT 1', assetId);

    return this.getAssetById(input.tenantId, assetId)!;
  }

  listAssets(tenantId: string, limit = 100): AssetSummary[] {
    this.assertPrepared();
    const db = getDatabase();
    const rows = db.prepare(`
      SELECT * FROM sec_assets
      WHERE tenant_id = ?
      ORDER BY risk_score DESC, updated_at DESC
      LIMIT ?
    `).all(tenantId, limit) as any[];
    return rows.map((row) => this.mapAsset(row));
  }

  getAssetById(tenantId: string, assetId: string): AssetSummary | null {
    this.assertPrepared();
    const db = getDatabase();
    const row = db.prepare(`
      SELECT * FROM sec_assets
      WHERE tenant_id = ? AND asset_id = ?
      LIMIT 1
    `).get(tenantId, assetId) as any;
    return row ? this.mapAsset(row) : null;
  }

  async getAssetByIdView(tenantId: string, assetId: string): Promise<AssetSummary | null> {
    const row = await this.queryShadowOneWithFallback<any>(
      `
        SELECT * FROM sec_assets
        WHERE tenant_id = $1 AND asset_id = $2
        LIMIT 1
      `,
      [tenantId, assetId],
      () => {
        this.assertPrepared();
        const db = getDatabase();
        return db.prepare(`
          SELECT * FROM sec_assets
          WHERE tenant_id = ? AND asset_id = ?
          LIMIT 1
        `).get(tenantId, assetId) as any;
      }
    );
    return row ? this.mapAsset(row) : null;
  }

  getAssetByExternalRef(tenantId: string, assetType: AssetType, externalRef: string): AssetSummary | null {
    this.assertPrepared();
    const db = getDatabase();
    const key = this.assetKey(tenantId, assetType, externalRef);
    const row = db.prepare('SELECT * FROM sec_assets WHERE asset_key = ? LIMIT 1').get(key) as any;
    return row ? this.mapAsset(row) : null;
  }

  ingestFinding(input: {
    tenantId: string;
    assetId?: string;
    sourceType: string;
    sourceRef: string;
    target: string;
    category?: string;
    severity: string;
    title: string;
    description: string;
    evidence?: Record<string, any>;
    remediation?: Record<string, any>;
    fingerprint?: string;
    createAlert?: boolean;
    alertType?: 'security' | 'performance' | 'system';
  }): FindingRecord {
    this.assertPrepared();
    const db = getDatabase();
    const now = this.now();
    const severity = this.normalizeSeverity(input.severity);
    const fingerprint = input.fingerprint || `${input.sourceType}:${input.sourceRef}:${input.target}:${input.title}`;
    const existing = db.prepare(`
      SELECT * FROM sec_findings
      WHERE tenant_id = ? AND fingerprint = ?
      LIMIT 1
    `).get(input.tenantId, fingerprint) as any;

    if (existing) {
      const mergedEvidence = {
        ...this.parseJson(existing.evidence_json, {}),
        ...(input.evidence || {})
      };
      const mergedRemediation = {
        ...this.parseJson(existing.remediation_json, {}),
        ...(input.remediation || {})
      };
      const nextStatus: FindingStatus = existing.status === 'resolved' ? 'open' : existing.status;
      db.prepare(`
        UPDATE sec_findings
        SET asset_id = ?, severity = ?, description = ?, evidence_json = ?, remediation_json = ?, status = ?,
            last_seen_at = ?, updated_at = ?, occurrence_count = occurrence_count + 1
        WHERE finding_id = ?
      `).run(
        input.assetId || existing.asset_id || null,
        severity,
        input.description,
        JSON.stringify(mergedEvidence),
        JSON.stringify(mergedRemediation),
        nextStatus,
        now,
        now,
        existing.finding_id
      );
      this.recalculateAssetRisk(input.tenantId, input.assetId || existing.asset_id);
      this.shadowGet('sec_findings', 'SELECT * FROM sec_findings WHERE finding_id = ? LIMIT 1', existing.finding_id);
      const record = this.getFindingById(input.tenantId, existing.finding_id)!;
      if ((input.createAlert || severity === 'critical' || severity === 'high') && nextStatus === 'open') {
        this.createAlert({
          tenantId: input.tenantId,
          findingId: existing.finding_id,
          assetId: input.assetId || existing.asset_id || undefined,
          sourceType: input.sourceType,
          sourceRef: input.sourceRef,
          title: input.title,
          message: input.description,
          severity,
          alertType: input.alertType || 'security',
          metadata: {
            target: input.target,
            category: input.category || 'security-posture'
          }
        });
      }
      return record;
    }

    const findingId = randomUUID();
    db.prepare(`
      INSERT INTO sec_findings (
        finding_id, tenant_id, fingerprint, asset_id, source_type, source_ref, target, category, severity, status,
        title, description, evidence_json, remediation_json, first_seen_at, last_seen_at, occurrence_count, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'open', ?, ?, ?, ?, ?, ?, 1, ?, ?)
    `).run(
      findingId,
      input.tenantId,
      fingerprint,
      input.assetId || null,
      input.sourceType,
      input.sourceRef,
      input.target,
      input.category || 'security-posture',
      severity,
      input.title,
      input.description,
      JSON.stringify(input.evidence || {}),
      JSON.stringify(input.remediation || {}),
      now,
      now,
      now,
      now
    );

    this.recalculateAssetRisk(input.tenantId, input.assetId);
    this.shadowGet('sec_findings', 'SELECT * FROM sec_findings WHERE finding_id = ? LIMIT 1', findingId);
    const record = this.getFindingById(input.tenantId, findingId)!;

    if (input.createAlert || severity === 'critical' || severity === 'high') {
      this.createAlert({
        tenantId: input.tenantId,
        findingId,
        assetId: input.assetId,
        sourceType: input.sourceType,
        sourceRef: input.sourceRef,
        title: input.title,
        message: input.description,
        severity,
        alertType: input.alertType || 'security',
        metadata: {
          target: input.target,
          category: input.category || 'security-posture'
        }
      });
    }

    return record;
  }

  resolveFindingByFingerprint(tenantId: string, fingerprint: string, actor = 'system'): FindingRecord | null {
    this.assertPrepared();
    const db = getDatabase();
    const existing = db.prepare(`
      SELECT *
      FROM sec_findings
      WHERE tenant_id = ? AND fingerprint = ?
      LIMIT 1
    `).get(tenantId, fingerprint) as any;

    if (!existing) {
      return null;
    }

    const now = this.now();
    if (existing.status !== 'resolved') {
      db.prepare(`
        UPDATE sec_findings
        SET status = 'resolved', updated_at = ?, last_seen_at = ?
        WHERE finding_id = ?
      `).run(now, now, existing.finding_id);
      this.shadowGet('sec_findings', 'SELECT * FROM sec_findings WHERE finding_id = ? LIMIT 1', existing.finding_id);
    }

    const alertRows = db.prepare(`
      SELECT * FROM sec_alerts
      WHERE tenant_id = ? AND finding_id = ? AND status IN ('open', 'acknowledged', 'investigating')
    `).all(tenantId, existing.finding_id) as any[];

    for (const alert of alertRows) {
      const metadata = {
        ...this.parseJson(alert.metadata_json, {}),
        lastActor: actor,
        autoResolved: true
      };
      db.prepare(`
        UPDATE sec_alerts
        SET status = 'resolved', metadata_json = ?, updated_at = ?
        WHERE alert_id = ?
      `).run(JSON.stringify(metadata), now, alert.alert_id);
      this.shadowGet('sec_alerts', 'SELECT * FROM sec_alerts WHERE alert_id = ? LIMIT 1', alert.alert_id);
    }

    this.recalculateAssetRisk(tenantId, existing.asset_id);
    return this.getFindingById(tenantId, existing.finding_id);
  }

  syncSignalFinding(input: {
    tenantId: string;
    active: boolean;
    assetId?: string;
    sourceType: string;
    sourceRef: string;
    target: string;
    category: string;
    severity: Severity;
    title: string;
    description: string;
    evidence?: Record<string, any>;
    remediation?: Record<string, any>;
    fingerprint: string;
    createAlert?: boolean;
    alertType?: 'security' | 'performance' | 'system';
  }): FindingRecord | null {
    if (input.active) {
      return this.ingestFinding({
        tenantId: input.tenantId,
        assetId: input.assetId,
        sourceType: input.sourceType,
        sourceRef: input.sourceRef,
        target: input.target,
        category: input.category,
        severity: input.severity,
        title: input.title,
        description: input.description,
        evidence: input.evidence,
        remediation: input.remediation,
        fingerprint: input.fingerprint,
        createAlert: input.createAlert,
        alertType: input.alertType
      });
    }

    return this.resolveFindingByFingerprint(input.tenantId, input.fingerprint);
  }

  listFindingsBySource(tenantId: string, sourceType: string, sourceRef: string): FindingRecord[] {
    this.assertPrepared();
    const db = getDatabase();
    const rows = db.prepare(`
      SELECT * FROM sec_findings
      WHERE tenant_id = ? AND source_type = ? AND source_ref = ?
      ORDER BY
        CASE severity
          WHEN 'critical' THEN 4
          WHEN 'high' THEN 3
          WHEN 'medium' THEN 2
          ELSE 1
        END DESC,
        updated_at DESC
    `).all(tenantId, sourceType, sourceRef) as any[];
    return rows.map((row) => this.mapFinding(row));
  }

