    // Seed alerts
    const alertCount = options.alerts || 0;
    for (let i = 0; i < alertCount; i++) {
      const alert = TestDataFixtures.createTestAlert({
        severity: i % 3 === 0 ? 'critical' : i % 3 === 1 ? 'warning' : 'info'
