/**
 * Traffic Interceptor - Main Entry Point
 * High-performance network traffic capture and security analysis
 */

import {
    Platform,
    detectPlatform,
    InterceptorConfig,
    Verdict,
    InterceptionResult,
    InterceptorStats,
    ThreatEvent
} from './core/types';
import { Packet } from './core/packet';
import { FlowManager } from './core/flow';
import { createCaptureInterface, TrafficCaptureInterface } from './core/hal';
import { RingBuffer } from './processing/ring-buffer';
import { AgentBridge } from './integration/agent-bridge';
import logger from '../utils/logger';

export * from './core/types';
export { Packet } from './core/packet';
export { FlowManager } from './core/flow';
export { RingBuffer } from './processing/ring-buffer';
export { ProtocolParser } from './processing/protocol-parser';
export { AgentBridge } from './integration/agent-bridge';

const DEFAULT_CONFIG: Partial<InterceptorConfig> = {
    enabled: true,
    mode: 'transparent',
    interfaces: ['eth0'],
    bufferSize: 100000,
    batchSize: 64,
    workerThreads: 4,
    fastPathRules: [],
    slowPathThreshold: 0.7
};

export class TrafficInterceptor {
    private config: InterceptorConfig;
    private platform: Platform;
    private capture: TrafficCaptureInterface;
    private flowManager: FlowManager;
    private agentBridge: AgentBridge;
    private packetBuffer: RingBuffer<Packet>;
    private running: boolean = false;
    private processingLoop: NodeJS.Timeout | null = null;
    private eventListeners: Map<string, Set<Function>> = new Map();
    private startTime: number = 0;

    constructor(config: Partial<InterceptorConfig> = {}) {
        this.platform = detectPlatform();
        this.config = { ...DEFAULT_CONFIG, ...config, platform: this.platform } as InterceptorConfig;
        
        this.capture = createCaptureInterface(this.platform);
        this.flowManager = new FlowManager(100000, 300000);
        this.agentBridge = new AgentBridge(this.flowManager, {
            enabled: true,
            batchSize: 32,
            timeout: 5000,
            fallbackVerdict: 'allow'
        });
        this.packetBuffer = new RingBuffer({ size: this.config.bufferSize });

        this.setupVerdictCallback();
    }

    private setupVerdictCallback(): void {
        this.capture.setVerdictCallback(async (packet: Packet) => {
            return this.processPacket(packet);
        });
    }

    async initialize(): Promise<void> {
        logger.info('Initializing Traffic Interceptor', {
            platform: this.platform,
            mode: this.config.mode
        });

        await this.capture.initialize(this.config);
        await this.agentBridge.initialize();

        logger.info('Traffic Interceptor initialized successfully');
    }

    async start(): Promise<void> {
        if (this.running) {
            logger.warn('Traffic Interceptor already running');
            return;
        }

        this.running = true;
        this.startTime = Date.now();

        await this.capture.start();
        this.startProcessingLoop();

        logger.info('Traffic Interceptor started', {
            interfaces: this.config.interfaces
        });
    }

    private startProcessingLoop(): void {
        this.processingLoop = setInterval(async () => {
            await this.processBatch();
        }, 1);
    }

    private async processBatch(): Promise<void> {
        const packets = this.packetBuffer.readBatch(this.config.batchSize);
        
        if (packets.length === 0) return;

        for (const packet of packets) {
            try {
                const verdict = await this.agentBridge.analyzePacket(packet);
                await this.applyVerdict(packet, verdict);
            } catch (error: any) {
                logger.error('Error processing packet', { 
                    error: error.message,
                    packetId: packet.id 
                });
            }
        }
    }

    private async processPacket(packet: Packet): Promise<Verdict> {
        const result = await this.agentBridge.analyzePacket(packet);
        
        if (result.verdict === 'block') {
            this.emit('threat_detected', {
                packetId: packet.id,
                threatType: result.matchedRule || 'unknown',
                severity: 'high',
                sourceIP: packet.parsed.ipHeader?.sourceIP,
                destIP: packet.parsed.ipHeader?.destIP,
                timestamp: BigInt(Date.now()) * BigInt(1_000_000)
            } as ThreatEvent);
        }

        return result.verdict;
    }

    private async applyVerdict(packet: Packet, result: InterceptionResult): Promise<void> {
        switch (result.verdict) {
            case 'allow':
                break;
            case 'block':
                logger.debug('Packet blocked', { 
                    packetId: packet.id,
                    rule: result.matchedRule 
                });
                break;
            case 'inspect':
                this.emit('packet_captured', {
                    packetId: packet.id,
                    parsed: packet.parsed
                });
                break;
        }
    }

    async stop(): Promise<void> {
        if (!this.running) return;

        this.running = false;

        if (this.processingLoop) {
            clearInterval(this.processingLoop);
            this.processingLoop = null;
        }

        await this.capture.stop();
        await this.agentBridge.shutdown();
        this.flowManager.shutdown();

        logger.info('Traffic Interceptor stopped');
    }

    injectPacket(rawData: Buffer, metadata: {
        direction: 'inbound' | 'outbound';
        interfaceIndex?: number;
    }): void {
        const packet = Packet.createFromBuffer(rawData, {
            timestamp: BigInt(Date.now()) * BigInt(1_000_000),
            direction: metadata.direction,
            interfaceIndex: metadata.interfaceIndex || 0,
            packetLength: rawData.length,
            capturedLength: rawData.length
        });

        this.packetBuffer.write(packet);
    }

    on(event: string, listener: Function): void {
        if (!this.eventListeners.has(event)) {
            this.eventListeners.set(event, new Set());
        }
        this.eventListeners.get(event)!.add(listener);
    }

    off(event: string, listener: Function): void {
        const listeners = this.eventListeners.get(event);
        if (listeners) {
            listeners.delete(listener);
        }
    }

    private emit(event: string, data: any): void {
        const listeners = this.eventListeners.get(event);
        if (listeners) {
            for (const listener of listeners) {
                try {
                    listener(data);
                } catch (error: any) {
                    logger.error('Event listener error', { event, error: error.message });
                }
            }
        }
    }

    getStats(): InterceptorStats & {
        flows: ReturnType<FlowManager['getStats']>;
        bridge: ReturnType<AgentBridge['getStats']>;
        buffer: ReturnType<RingBuffer<any>['getStats']>;
        uptime: number;
    } {
        const captureStats = this.capture.getStats();
        
        return {
            ...captureStats,
            flows: this.flowManager.getStats(),
            bridge: this.agentBridge.getStats(),
            buffer: this.packetBuffer.getStats(),
            uptime: this.startTime > 0 ? Date.now() - this.startTime : 0
        };
    }

    getFlowManager(): FlowManager {
        return this.flowManager;
    }

    isRunning(): boolean {
        return this.running;
    }

    getPlatform(): Platform {
        return this.platform;
    }
}

export const createTrafficInterceptor = (config?: Partial<InterceptorConfig>): TrafficInterceptor => {
    return new TrafficInterceptor(config);
};

export default TrafficInterceptor;

/**
 * Agent Bridge - Integration with the rule-first detection pipeline
 */

import {
    Verdict,
    InterceptionResult,
    AnalysisResult,
    ThreatEvent,
    ParsedPacket
} from '../core/types';
import { Packet } from '../core/packet';
import { ProtocolParser } from '../processing/protocol-parser';
import { FlowManager } from '../core/flow';
import { detectionPipelineService } from '../../services/detection-pipeline.service';
import logger from '../../utils/logger';

export interface AgentBridgeConfig {
    enabled: boolean;
    batchSize: number;
    timeout: number;
    fallbackVerdict: Verdict;
    cacheResults: boolean;
    cacheTTL: number;
}

const DEFAULT_CONFIG: AgentBridgeConfig = {
    enabled: true,
    batchSize: 10,
    timeout: 5000,
    fallbackVerdict: 'allow',
    cacheResults: true,
    cacheTTL: 60000
};

export class AgentBridge {
    private config: AgentBridgeConfig;
    private protocolParser: ProtocolParser;
    private flowManager: FlowManager;
    private verdictCache: Map<string, { verdict: Verdict; timestamp: number }>;
    private stats = {
        totalAnalyzed: 0,
        cacheHits: 0,
        cacheMisses: 0,
        timeouts: 0,
        errors: 0,
        avgLatency: 0
    };

    constructor(
        flowManager: FlowManager,
        config: Partial<AgentBridgeConfig> = {}
    ) {
        this.config = { ...DEFAULT_CONFIG, ...config };
        this.protocolParser = new ProtocolParser();
        this.flowManager = flowManager;
        this.verdictCache = new Map();
    }

    async initialize(): Promise<void> {
        if (!this.config.enabled) {
            logger.info('Agent bridge disabled');
            return;
        }

        logger.info('Agent bridge initialized successfully');
    }

    async analyzePacket(packet: Packet): Promise<InterceptionResult> {
        const startTime = Date.now();
        const packetId = packet.id;

        try {
            const parsed = packet.parsed;

            const cacheKey = this.generateCacheKey(parsed);
            if (this.config.cacheResults) {
                const cached = this.verdictCache.get(cacheKey);
                if (cached && Date.now() - cached.timestamp < this.config.cacheTTL) {
                    this.stats.cacheHits++;
                    return {
                        packetId,
                        verdict: cached.verdict,
                        processingTime: Date.now() - startTime,
                        matchedRule: 'cache'
                    };
                }
                this.stats.cacheMisses++;
            }

            const analysisResult = await this.performDetectionPipelineAnalysis(parsed);

            const verdict = this.mapAnalysisVerdict(analysisResult);

            if (this.config.cacheResults) {
                this.verdictCache.set(cacheKey, { verdict, timestamp: Date.now() });
            }

            this.updateStats(Date.now() - startTime);

            return {
                packetId,
                verdict,
                processingTime: Date.now() - startTime,
                matchedRule: analysisResult.threatType,
                inspectionData: {
                    confidence: analysisResult.confidence,
                    threatLevel: analysisResult.threatLevel,
                    reasoning: analysisResult.reasoning
                }
            };

        } catch (error: any) {
            this.stats.errors++;
            logger.error('Packet analysis failed', { 
                packetId, 
                error: error.message 
            });

            return {
                packetId,
                verdict: this.config.fallbackVerdict,
                processingTime: Date.now() - startTime
            };
        }
    }

    private async performDetectionPipelineAnalysis(parsed: ParsedPacket): Promise<AnalysisResult> {
        try {
            const protocolResult = this.protocolParser.parse(parsed.payload);
            const existingSignals = protocolResult.threats.map((threat) => ({
                source: 'existing_signal' as const,
                key: `protocol:${threat.type}`,
                score: threat.severity === 'critical' ? 1 : threat.severity === 'high' ? 0.8 : 0.55,
                severity: threat.severity,
                description: threat.description
            }));

            const decision = await Promise.race([
                detectionPipelineService.evaluateRequest({
                    tenantId: 'global',
                    channel: 'packet',
                    requestId: parsed.id,
                    timestamp: new Date().toISOString(),
                    sourceIp: parsed.ipHeader?.sourceIP || '',
                    method: parsed.protocol.toUpperCase(),
                    path: this.extractPath(parsed),
                    headers: {},
                    body: parsed.payload.toString('utf-8'),
                    evidence: protocolResult.threats.map((threat) => threat.description).join('\n'),
                    protocol: parsed.protocol,
                    rawPayload: parsed.raw.toString('utf-8'),
                    existingSignals,
                    metadata: {
                        destIP: parsed.ipHeader?.destIP || '',
                        sourcePort: (parsed.transportHeader as any)?.sourcePort || 0,
                        destPort: (parsed.transportHeader as any)?.destPort || 0,
                        direction: parsed.metadata.direction,
                        flowId: this.flowManager.getOrCreateFlow(parsed)?.id || ''
                    }
                }),
                this.createTimeoutPromise<any>()
            ]);

            return {
                packetId: parsed.id,
                verdict: decision.verdict === 'allow' ? 'allow' :
                         decision.verdict === 'block' ? 'block' : 'monitor',
                confidence: decision.aiConfidence ?? decision.riskScore,
                threatType: decision.attackFamily !== 'benign' ? decision.attackFamily : undefined,
                threatLevel: decision.verdict === 'block'
                    ? 'high'
                    : decision.verdict === 'monitor'
                        ? 'medium'
                        : undefined,
                reasoning: decision.decisionSource
            };
        } catch (error: any) {
            this.stats.timeouts++;
            logger.warn('Deep analysis timeout or error', { error: error.message });
            return this.fallbackAnalysis(parsed);
        }
    }

    private extractPath(parsed: ParsedPacket): string {
        const appLayer = parsed.applicationLayer;
        if (appLayer?.parsed && 'path' in appLayer.parsed) {
            return appLayer.parsed.path;
        }
        return `/${parsed.protocol}/${(parsed.transportHeader as any)?.destPort || 0}`;
    }

    private createTimeoutPromise<T = AnalysisResult>(): Promise<T> {
        return new Promise((_, reject) => {
            setTimeout(() => reject(new Error('Analysis timeout')), this.config.timeout);
        });
    }

    private fallbackAnalysis(parsed: ParsedPacket): AnalysisResult {
        const protocolResult = this.protocolParser.parse(parsed.payload);
        
        let verdict: 'allow' | 'block' | 'monitor' = 'allow';
        let confidence = 0.5;
        let threatType: string | undefined;
        let threatLevel: 'low' | 'medium' | 'high' | 'critical' | undefined;

        if (protocolResult.threats.length > 0) {
            const maxSeverity = Math.max(
                ...protocolResult.threats.map(t => 
                    ({ low: 1, medium: 2, high: 3, critical: 4 })[t.severity]
                )
            );

            if (maxSeverity >= 4) {
                verdict = 'block';
                confidence = 0.9;
                threatLevel = 'critical';
            } else if (maxSeverity >= 3) {
                verdict = 'block';
                confidence = 0.8;
                threatLevel = 'high';
            } else {
                verdict = 'monitor';
                confidence = 0.6;
                threatLevel = 'medium';
            }

            threatType = protocolResult.threats[0].type;
        }

        return {
            packetId: parsed.id,
            verdict,
            confidence,
            threatType,
            threatLevel,
            reasoning: protocolResult.threats.length > 0
                ? `Detected ${protocolResult.threats.length} threat indicator(s)`
                : 'No threats detected in fallback analysis'
        };
    }

    private generateCacheKey(parsed: ParsedPacket): string {
        const parts = [
            parsed.ipHeader?.sourceIP || '',
            parsed.ipHeader?.destIP || '',
            (parsed.transportHeader as any)?.sourcePort || 0,
            (parsed.transportHeader as any)?.destPort || 0,
            parsed.protocol
        ];
        return parts.join(':');
    }

    private mapAnalysisVerdict(result: AnalysisResult): Verdict {
        switch (result.verdict) {
            case 'allow': return 'allow';
            case 'block': return 'block';
            default: return 'inspect';
        }
    }

    private updateStats(latency: number): void {
        this.stats.totalAnalyzed++;
        const total = this.stats.totalAnalyzed;
        this.stats.avgLatency = (this.stats.avgLatency * (total - 1) + latency) / total;
    }

    async analyzeBatch(packets: Packet[]): Promise<InterceptionResult[]> {
        const results: InterceptionResult[] = [];

        for (const packet of packets) {
            const result = await this.analyzePacket(packet);
            results.push(result);
        }

        return results;
    }

    getStats(): typeof this.stats & { cacheSize: number; pendingCount: number } {
        return {
            ...this.stats,
            cacheSize: this.verdictCache.size,
            pendingCount: 0
        };
    }

    clearCache(): void {
        this.verdictCache.clear();
    }

    async shutdown(): Promise<void> {
        this.verdictCache.clear();
        logger.info('Agent bridge shutdown complete');
    }
}

export default AgentBridge;

/**
 * Protocol Parser - Fast protocol detection and parsing
 */

import {
    ParsedPacket,
    HTTPRequest,
    DNSQuery,
    TLSHandshake
} from '../core/types';
import logger from '../../utils/logger';

export interface ProtocolDetectionResult {
    protocol: string;
    confidence: number;
    isEncrypted: boolean;
    isRequest: boolean;
}

export interface ParsedProtocol {
    type: string;
    data: any;
    threats: ThreatIndicator[];
}

export interface ThreatIndicator {
    type: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    location: { start: number; end: number };
}

export class ProtocolParser {
    private static readonly HTTP_METHODS = [
        'GET ', 'POST', 'PUT ', 'DELE', 'HEAD', 'OPTI', 'PATC', 'TRAC', 'CONN'
    ];

    private static readonly SQL_KEYWORDS = [
        'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'DROP', 'UNION', 'EXEC',
        'EXECUTE', 'DECLARE', 'CAST', 'CONVERT', 'CONCAT', 'CHAR',
        'NCHAR', 'VARCHAR', 'NVARCHAR', 'ALTER', 'CREATE', 'TRUNCATE'
    ];

    private static readonly XSS_PATTERNS = [
        /<script[\s\S]*?>/gi,
        /javascript:/gi,
        /on\w+\s*=/gi,
        /<iframe[\s\S]*?>/gi,
        /<object[\s\S]*?>/gi,
        /<embed[\s\S]*?>/gi,
        /expression\s*\(/gi,
        /vbscript:/gi,
        /data:\s*text\/html/gi
    ];

    private static readonly PATH_TRAVERSAL_PATTERNS = [
        /\.\.[\/\\]/g,
        /%2e%2e[%\/\\]/gi,
        /\.\.%2f/gi,
        /%2e%2e\//gi,
        /\.\.%5c/gi
    ];

    detectProtocol(payload: Buffer): ProtocolDetectionResult {
        if (payload.length < 4) {
            return { protocol: 'unknown', confidence: 0, isEncrypted: false, isRequest: false };
        }

        const firstBytes = payload.subarray(0, 4);
        const first4Str = firstBytes.toString('ascii');

        if (this.isHTTP(first4Str)) {
            return { protocol: 'http', confidence: 0.95, isEncrypted: false, isRequest: true };
        }

        if (this.isTLS(firstBytes)) {
            return { protocol: 'tls', confidence: 0.95, isEncrypted: true, isRequest: false };
        }

        if (this.isDNS(payload)) {
            return { protocol: 'dns', confidence: 0.9, isEncrypted: false, isRequest: true };
        }

        if (this.isSSH(firstBytes)) {
            return { protocol: 'ssh', confidence: 0.95, isEncrypted: true, isRequest: false };
        }

        if (this.isSMTP(first4Str)) {
            return { protocol: 'smtp', confidence: 0.9, isEncrypted: false, isRequest: false };
        }

        return { protocol: 'unknown', confidence: 0.5, isEncrypted: false, isRequest: false };
    }

    private isHTTP(first4: string): boolean {
        return ProtocolParser.HTTP_METHODS.some(method => first4.startsWith(method));
    }

    private isTLS(firstBytes: Buffer): boolean {
        const contentType = firstBytes[0];
        const version = (firstBytes[1] << 8) | firstBytes[2];
        
        return contentType >= 20 && contentType <= 23 &&
               (version === 0x0301 || version === 0x0302 || 
                version === 0x0303 || version === 0x0300);
    }

    private isDNS(payload: Buffer): boolean {
        if (payload.length < 12) return false;

        const flags = payload.readUInt16BE(2);
        const qr = (flags >> 15) & 1;
        const opcode = (flags >> 11) & 0xF;
        const qdcount = payload.readUInt16BE(4);
        const ancount = payload.readUInt16BE(6);

        return opcode <= 2 && qdcount <= 10 && ancount <= 100;
    }

    private isSSH(firstBytes: Buffer): boolean {
        return firstBytes.toString('ascii').startsWith('SSH-');
    }

    private isSMTP(first4: string): boolean {
        return first4.startsWith('220 ') || 
               first4.startsWith('EHLO') ||
               first4.startsWith('HELO') ||
               first4.startsWith('MAIL') ||
               first4.startsWith('RCPT');
    }

    parseHTTP(payload: Buffer): { request: HTTPRequest | null; threats: ThreatIndicator[] } {
        const threats: ThreatIndicator[] = [];
        let request: HTTPRequest | null = null;

        try {
            const headerEnd = this.findHeaderEnd(payload);
            if (headerEnd === -1) {
                return { request: null, threats };
            }

            const headerStr = payload.subarray(0, headerEnd).toString('utf-8');
            const lines = headerStr.split('\r\n');
            const [method, path, version] = (lines[0] || '').split(' ');

            const headers: Record<string, string> = {};
            for (let i = 1; i < lines.length; i++) {
                const colonIndex = lines[i].indexOf(':');
                if (colonIndex !== -1) {
                    const key = lines[i].substring(0, colonIndex).trim().toLowerCase();
                    const value = lines[i].substring(colonIndex + 1).trim();
                    headers[key] = value;
                }
            }

            const body = payload.subarray(headerEnd + 4);

            request = { method, path, version, headers, body };

            threats.push(...this.detectHTTPThreats(request, payload));

        } catch (error: any) {
            logger.debug('HTTP parsing error', { error: error.message });
        }

        return { request, threats };
    }

    private detectHTTPThreats(request: HTTPRequest, payload: Buffer): ThreatIndicator[] {
        const threats: ThreatIndicator[] = [];
        const fullRequest = payload.toString('utf-8');

        const sqlInjection = this.detectSQLInjection(fullRequest);
        threats.push(...sqlInjection);

        const xss = this.detectXSS(fullRequest);
        threats.push(...xss);

        const pathTraversal = this.detectPathTraversal(request.path || '');
        threats.push(...pathTraversal);

        const headerInjection = this.detectHeaderInjection(request.headers);
        threats.push(...headerInjection);

        return threats;
    }

    private detectSQLInjection(content: string): ThreatIndicator[] {
        const threats: ThreatIndicator[] = [];
        const upperContent = content.toUpperCase();

        for (const keyword of ProtocolParser.SQL_KEYWORDS) {
            let pos = 0;
            while ((pos = upperContent.indexOf(keyword, pos)) !== -1) {
                const context = content.substring(Math.max(0, pos - 5), pos + keyword.length + 5);
                
                if (this.isSQLContext(context)) {
                    threats.push({
                        type: 'sql_injection',
                        severity: 'high',
                        description: `SQL keyword detected: ${keyword}`,
                        location: { start: pos, end: pos + keyword.length }
                    });
                }
                pos++;
            }
        }

        const injectionPatterns = [
            { pattern: /'\s*(OR|AND)\s+['\d]/gi, type: 'sql_injection', severity: 'critical' as const },
            { pattern: /;\s*(DROP|DELETE|UPDATE|INSERT)/gi, type: 'sql_injection', severity: 'critical' as const },
            { pattern: /UNION\s+(ALL\s+)?SELECT/gi, type: 'sql_injection', severity: 'critical' as const },
            { pattern: /--\s*$/gm, type: 'sql_injection', severity: 'high' as const },
            { pattern: /\/\*[\s\S]*?\*\//g, type: 'sql_injection', severity: 'medium' as const }
        ];

        for (const { pattern, type, severity } of injectionPatterns) {
            let match;
            while ((match = pattern.exec(content)) !== null) {
                threats.push({
                    type,
                    severity,
                    description: `SQL injection pattern: ${match[0].substring(0, 50)}`,
                    location: { start: match.index, end: match.index + match[0].length }
                });
            }
        }

        return threats;
    }

    private isSQLContext(context: string): boolean {
        const suspiciousChars = ["'", '"', '=', '(', ')', ';', ' '];
        return suspiciousChars.some(c => context.includes(c));
    }

    private detectXSS(content: string): ThreatIndicator[] {
        const threats: ThreatIndicator[] = [];

        for (const pattern of ProtocolParser.XSS_PATTERNS) {
            let match;
            while ((match = pattern.exec(content)) !== null) {
                threats.push({
                    type: 'xss',
                    severity: 'high',
                    description: `XSS pattern detected: ${match[0].substring(0, 50)}`,
                    location: { start: match.index, end: match.index + match[0].length }
                });
            }
        }

        return threats;
    }

    private detectPathTraversal(path: string): ThreatIndicator[] {
        const threats: ThreatIndicator[] = [];

        for (const pattern of ProtocolParser.PATH_TRAVERSAL_PATTERNS) {
            let match;
            while ((match = pattern.exec(path)) !== null) {
                threats.push({
                    type: 'path_traversal',
                    severity: 'high',
                    description: `Path traversal attempt: ${match[0]}`,
                    location: { start: match.index, end: match.index + match[0].length }
                });
            }
        }

        return threats;
    }

    private detectHeaderInjection(headers: Record<string, string>): ThreatIndicator[] {
        const threats: ThreatIndicator[] = [];

        for (const [key, value] of Object.entries(headers)) {
            if (value.includes('\r\n')) {
                threats.push({
                    type: 'header_injection',
                    severity: 'high',
                    description: `Header injection in ${key}`,
                    location: { start: 0, end: value.length }
                });
            }
        }

        return threats;
    }

    parseDNS(payload: Buffer): { query: DNSQuery | null; threats: ThreatIndicator[] } {
        const threats: ThreatIndicator[] = [];
        let query: DNSQuery | null = null;

        try {
            if (payload.length < 12) {
                return { query: null, threats };
            }

            const transactionId = payload.readUInt16BE(0);
            const flags = payload.readUInt16BE(2);
            const qdcount = payload.readUInt16BE(4);
            const ancount = payload.readUInt16BE(6);

            const questions = this.parseDNSQuestions(payload, 12, qdcount);

            query = {
                transactionId,
                flags,
                questions,
                answers: []
            };

            for (const q of questions) {
                if (this.isSuspiciousDomain(q.name)) {
                    threats.push({
                        type: 'dns_exfil',
                        severity: 'medium',
                        description: `Suspicious DNS query: ${q.name}`,
                        location: { start: 0, end: q.name.length }
                    });
                }
            }

        } catch (error: any) {
            logger.debug('DNS parsing error', { error: error.message });
        }

        return { query, threats };
    }

    private parseDNSQuestions(payload: Buffer, offset: number, count: number): { name: string; type: number; class: number }[] {
        const questions: { name: string; type: number; class: number }[] = [];

        for (let i = 0; i < count && offset < payload.length; i++) {
            const name = this.readDNSName(payload, offset);
            offset += name.length + 2;

            if (offset + 4 > payload.length) break;

            const type = payload.readUInt16BE(offset);
            const cls = payload.readUInt16BE(offset + 2);
            offset += 4;

            questions.push({ name, type, class: cls });
        }

        return questions;
    }

    private readDNSName(payload: Buffer, offset: number): string {
        const labels: string[] = [];
        let pos = offset;
        let jumped = false;
        const maxJumps = 10;
        let jumps = 0;

        while (pos < payload.length) {
            const len = payload[pos];

            if (len === 0) {
                break;
            }

            if ((len & 0xC0) === 0xC0) {
                if (!jumped) {
                    jumped = true;
                }
                const jumpOffset = ((len & 0x3F) << 8) | payload[pos + 1];
                pos = jumpOffset;
                jumps++;
                if (jumps > maxJumps) break;
                continue;
            }

            pos++;
            if (pos + len > payload.length) break;

            labels.push(payload.subarray(pos, pos + len).toString('ascii'));
            pos += len;
        }

        return labels.join('.');
    }

    private isSuspiciousDomain(domain: string): boolean {
        const suspiciousPatterns = [
            /^[a-z0-9]{32,}\./i,
            /\.(local|localhost|internal)$/i,
            /^[a-f0-9]{16,}\./i
        ];

        return suspiciousPatterns.some(p => p.test(domain));
    }

    private findHeaderEnd(data: Buffer): number {
        for (let i = 0; i < data.length - 3; i++) {
            if (data[i] === 0x0D && data[i + 1] === 0x0A && 
                data[i + 2] === 0x0D && data[i + 3] === 0x0A) {
                return i;
            }
        }
        return -1;
    }

    parse(payload: Buffer): ParsedProtocol {
        const detection = this.detectProtocol(payload);
        const threats: ThreatIndicator[] = [];

        switch (detection.protocol) {
            case 'http':
                const httpResult = this.parseHTTP(payload);
                return {
                    type: 'http',
                    data: httpResult.request,
                    threats: httpResult.threats
                };

            case 'dns':
                const dnsResult = this.parseDNS(payload);
                return {
                    type: 'dns',
                    data: dnsResult.query,
                    threats: dnsResult.threats
                };

            case 'tls':
                return {
                    type: 'tls',
                    data: { encrypted: true },
                    threats: []
                };

            default:
                const genericThreats = [
                    ...this.detectSQLInjection(payload.toString('utf-8')),
                    ...this.detectXSS(payload.toString('utf-8'))
                ];
                return {
                    type: 'unknown',
                    data: null,
                    threats: genericThreats
                };
        }
    }
}

export const protocolParser = new ProtocolParser();
export default ProtocolParser;

/**
 * Ring Buffer - Lock-free ring buffer for high-performance packet processing
 */

import {
    RingBufferConfig,
    BufferSlice
} from '../core/types';
import logger from '../../utils/logger';

export class RingBuffer<T> {
    private buffer: Array<T | null>;
    private mask: number;
    private head: number = 0;
    private tail: number = 0;
    private capacity: number;
    private batchSize: number;
    private stats = {
        totalWritten: 0,
        totalRead: 0,
        overflows: 0,
        underflows: 0
    };

    constructor(config: Partial<RingBufferConfig> & { size: number }) {
        this.capacity = this.nextPowerOf2(config.size);
        this.mask = this.capacity - 1;
        this.buffer = new Array(this.capacity).fill(null);
        this.batchSize = config.batchSize || 32;
    }

    private nextPowerOf2(n: number): number {
        let power = 1;
        while (power < n) {
            power *= 2;
        }
        return power;
    }

    write(item: T): boolean {
        const nextHead = (this.head + 1) & this.mask;
        
        if (nextHead === this.tail) {
            this.stats.overflows++;
            return false;
        }

        this.buffer[this.head] = item;
        this.head = nextHead;
        this.stats.totalWritten++;
        return true;
    }

    writeBatch(items: T[]): number {
        const available = this.availableWriteSpace();
        const toWrite = Math.min(items.length, available);

        for (let i = 0; i < toWrite; i++) {
            this.buffer[this.head] = items[i];
            this.head = (this.head + 1) & this.mask;
        }

        this.stats.totalWritten += toWrite;
        
        if (toWrite < items.length) {
            this.stats.overflows++;
        }

        return toWrite;
    }

    read(): T | null {
        if (this.tail === this.head) {
            this.stats.underflows++;
            return null;
        }

        const item = this.buffer[this.tail];
        this.buffer[this.tail] = null;
        this.tail = (this.tail + 1) & this.mask;
        this.stats.totalRead++;
        return item;
    }

    readBatch(maxItems: number = this.batchSize): T[] {
        const items: T[] = [];
        const available = this.availableReadSpace();
        const toRead = Math.min(maxItems, available);

        for (let i = 0; i < toRead; i++) {
            const item = this.buffer[this.tail];
            if (item !== null) {
                items.push(item);
            }
            this.buffer[this.tail] = null;
            this.tail = (this.tail + 1) & this.mask;
        }

        this.stats.totalRead += toRead;
        return items;
    }

    peek(): T | null {
        if (this.tail === this.head) {
            return null;
        }
        return this.buffer[this.tail];
    }

    skip(count: number): number {
        const available = this.availableReadSpace();
        const toSkip = Math.min(count, available);

        for (let i = 0; i < toSkip; i++) {
            this.buffer[this.tail] = null;
            this.tail = (this.tail + 1) & this.mask;
        }

        return toSkip;
    }

    availableWriteSpace(): number {
        return (this.tail - this.head - 1 + this.capacity) & this.mask;
    }

    availableReadSpace(): number {
        return (this.head - this.tail) & this.mask;
    }

    isEmpty(): boolean {
        return this.head === this.tail;
    }

    isFull(): boolean {
        return ((this.head + 1) & this.mask) === this.tail;
    }

    size(): number {
        return this.availableReadSpace();
    }

    getCapacity(): number {
        return this.capacity - 1;
    }

    getUsagePercent(): number {
        return (this.size() / this.getCapacity()) * 100;
    }

    getStats(): typeof this.stats & { usage: number } {
        return {
            ...this.stats,
            usage: this.getUsagePercent()
        };
    }

    clear(): void {
        this.buffer.fill(null);
        this.head = 0;
        this.tail = 0;
    }
}

export class PacketRingBuffer {
    private buffer: Buffer;
    private descriptors: Array<{ offset: number; length: number; valid: boolean }>;
    private mask: number;
    private head: number = 0;
    private tail: number = 0;
    private chunkSize: number;
    private totalChunks: number;

    constructor(totalSize: number, chunkSize: number = 2048) {
        this.chunkSize = chunkSize;
        this.totalChunks = Math.floor(totalSize / chunkSize);
        this.mask = this.totalChunks - 1;
        
        if (!Number.isInteger(Math.log2(this.totalChunks))) {
            const power = Math.pow(2, Math.ceil(Math.log2(this.totalChunks)));
            this.totalChunks = power;
            this.mask = power - 1;
        }

        this.buffer = Buffer.allocUnsafe(this.totalChunks * this.chunkSize);
        this.descriptors = new Array(this.totalChunks).fill(null).map(() => ({
            offset: 0,
            length: 0,
            valid: false
        }));
    }

    write(packet: Buffer): boolean {
        const nextHead = (this.head + 1) & this.mask;
        
        if (nextHead === this.tail) {
            return false;
        }

        if (packet.length > this.chunkSize) {
            return false;
        }

        const offset = this.head * this.chunkSize;
        packet.copy(this.buffer, offset, 0, packet.length);

        this.descriptors[this.head] = {
            offset,
            length: packet.length,
            valid: true
        };

        this.head = nextHead;
        return true;
    }

    read(): Buffer | null {
        if (this.tail === this.head) {
            return null;
        }

        const desc = this.descriptors[this.tail];
        if (!desc.valid) {
            return null;
        }

        const packet = this.buffer.subarray(desc.offset, desc.offset + desc.length);
        const copy = Buffer.from(packet);

        desc.valid = false;
        desc.length = 0;

        this.tail = (this.tail + 1) & this.mask;
        return copy;
    }

    readRef(): { data: Buffer; length: number } | null {
        if (this.tail === this.head) {
            return null;
        }

        const desc = this.descriptors[this.tail];
        if (!desc.valid) {
            return null;
        }

        return {
            data: this.buffer.subarray(desc.offset, desc.offset + desc.length),
            length: desc.length
        };
    }

    release(): void {
        if (this.tail === this.head) {
            return;
        }

        const desc = this.descriptors[this.tail];
        desc.valid = false;
        desc.length = 0;
        this.tail = (this.tail + 1) & this.mask;
    }

    availableWriteSpace(): number {
        return (this.tail - this.head - 1 + this.totalChunks) & this.mask;
    }

    availableReadSpace(): number {
        return (this.head - this.tail) & this.mask;
    }

    getStats(): {
        totalChunks: number;
        usedChunks: number;
        chunkSize: number;
        bufferSize: number;
    } {
        return {
            totalChunks: this.totalChunks,
            usedChunks: this.availableReadSpace(),
            chunkSize: this.chunkSize,
            bufferSize: this.buffer.length
        };
    }
}

export class MultiProducerRingBuffer<T> {
    private buffer: Array<T | null>;
    private mask: number;
    private head: number = 0;
    private tails: number[];
    private numProducers: number;

    constructor(size: number, numProducers: number) {
        const capacity = Math.pow(2, Math.ceil(Math.log2(size)));
        this.mask = capacity - 1;
        this.buffer = new Array(capacity).fill(null);
        this.numProducers = numProducers;
        this.tails = new Array(numProducers).fill(0);
    }

    write(producerId: number, item: T): boolean {
        if (producerId < 0 || producerId >= this.numProducers) {
            return false;
        }

        const tail = this.tails[producerId];
        const nextTail = (tail + 1) & this.mask;

        if (nextTail === this.head) {
            return false;
        }

        this.buffer[tail] = item;
        this.tails[producerId] = nextTail;
        return true;
    }

    read(): T | null {
        let minTail = this.tails[0];
        for (let i = 1; i < this.numProducers; i++) {
            const diff = (this.tails[i] - minTail + this.mask + 1) & this.mask;
            if (diff > 0 && this.tails[i] < minTail) {
                minTail = this.tails[i];
            }
        }

        if (this.head === minTail) {
            return null;
        }

        const item = this.buffer[this.head];
        this.buffer[this.head] = null;
        this.head = (this.head + 1) & this.mask;
        return item;
    }

    availableReadSpace(): number {
        let minTail = this.tails[0];
        for (let i = 1; i < this.numProducers; i++) {
            const diff = (this.tails[i] - minTail + this.mask + 1) & this.mask;
            if (diff > 0 && this.tails[i] < minTail) {
                minTail = this.tails[i];
            }
        }
        return (minTail - this.head) & this.mask;
    }
}

