function asRecord(input: unknown): Record<string, any> | null {
    return input && typeof input === 'object' && !Array.isArray(input)
        ? input as Record<string, any>
        : null;
}

function optionalBoolean(value: unknown): boolean | undefined {
    return typeof value === 'boolean' ? value : undefined;
}

function optionalString(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

function optionalNumber(value: unknown): number | undefined {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : undefined;
}

function extractRuntimePatch(input: unknown): Record<string, any> {
    const payload = asRecord(input) || {};
    const systemInfo = asRecord(payload.systemInfo) || {};
    const physicalAuth = asRecord(payload.physicalAuth) || {};

    const patch: Record<string, any> = {};
    const transport = optionalString(payload.transport);
    const interlockState = optionalString(payload.interlockState ?? payload.interlock_state);
    const hostActionState = optionalString(payload.hostActionState ?? payload.host_action_state);
    const publicKeyPem = optionalString(
        physicalAuth.publicKeyPem
            ?? physicalAuth.public_key_pem
            ?? payload.publicKeyPem
            ?? payload.public_key_pem
    );
    const monotonicCounter = optionalNumber(
        physicalAuth.monotonicCounter
            ?? physicalAuth.monotonic_counter
            ?? payload.monotonicCounter
            ?? payload.monotonic_counter
    );

    if (transport) {
        patch.transport = transport;
    }
    if (optionalBoolean(payload.externalPowerPresent ?? payload.external_power_present) !== undefined) {
        patch.externalPowerPresent = optionalBoolean(payload.externalPowerPresent ?? payload.external_power_present);
    }
    if (optionalBoolean(payload.secureElementPresent ?? payload.secure_element_present) !== undefined) {
        patch.secureElementPresent = optionalBoolean(payload.secureElementPresent ?? payload.secure_element_present);
    }
    if (optionalBoolean(payload.pendingPhysicalApproval ?? payload.pending_physical_approval) !== undefined) {
        patch.pendingPhysicalApproval = optionalBoolean(payload.pendingPhysicalApproval ?? payload.pending_physical_approval);
    }
    if (interlockState) {
        patch.interlockState = interlockState;
    }
    if (hostActionState) {
        patch.hostActionState = hostActionState;
    }

    const nextSystemInfo = {
        hostname: optionalString(systemInfo.hostname ?? payload.hostname),
        os: optionalString(systemInfo.os ?? payload.os),
        kernel: optionalString(systemInfo.kernel ?? payload.kernel),
        arch: optionalString(systemInfo.arch ?? payload.arch)
    };
    if (nextSystemInfo.hostname || nextSystemInfo.os || nextSystemInfo.kernel || nextSystemInfo.arch) {
        patch.systemInfo = nextSystemInfo;
    }

    if (publicKeyPem || monotonicCounter !== undefined) {
        patch.physicalAuth = {
            ...(publicKeyPem ? { publicKeyPem } : {}),
            ...(monotonicCounter !== undefined ? { monotonicCounter } : {})
        };
    }

    return patch;
}

interface DeviceSocket extends Socket {
